import{d as S,C as g,o as A,c as B,j as n,a as e,E as a,a3 as E}from"./chunks/framework.Q4yG9rk_.js";const O=JSON.parse('{"title":"庄子·天地","description":"洋洋乎大哉初有无论到机心论与失性五者，理解庄子外篇结构最完整的篇章。","frontmatter":{"title":"庄子·天地","description":"洋洋乎大哉初有无论到机心论与失性五者，理解庄子外篇结构最完整的篇章。","category":"guide","aliases":["天地","庄子天地","zhuangzi chapter 12"],"source":["《庄子·天地》"]},"headers":[],"relativePath":"daoism/zhuang-zi/chapter-12.md","filePath":"daoism/zhuang-zi/chapter-12.md","lastUpdated":1792641266000}'),I={name:"daoism/zhuang-zi/chapter-12.md"},U=S({...I,setup(K){const r=[{id:"dejiandao1_s1",label:"天地虽大……其主君也",sentences:[["天地虽大，",{text:"其化均也",glossary:"qi_hua_jun"},"；"],["万物虽多，",{text:"其治一也",glossary:"qi_zhi_yi"},"；"],[{text:"人卒虽众",glossary:"ren_zu_sui_zhong"},"，",{text:"其主君也",glossary:"qi_zhu_jun"},"。"]]},{id:"dejiandao1_s2",label:"君原于德而成于天……天德而已矣",sentences:[["君原于德而成于天。"],["故曰：",{text:"玄古之",glossary:"xuan_gu_zhi"},{text:"君天下",glossary:"jun_tian_xia"},"，无为也，天德而已矣。"]]},{id:"dejiandao1_s3",label:"以道观言……天下之君正",sentences:[[{text:"以道观言",glossary:"yi_dao_guan_yan"},"而",{text:"天下之君正",glossary:"tian_xia_jun_zheng"},"；"]]},{id:"dejiandao1_s4",label:"以道观分……天下之官治",sentences:[["以道",{text:"观分",glossary:"guan_fen"},"而君臣之义明；"],["以道",{text:"观能",glossary:"guan_neng"},"而天下之官治；"]]},{id:"dejiandao1_s5",label:"以道泛观……万物之应备",sentences:[["以道",{text:"泛观",glossary:"fan_guan"},"而",{text:"万物之应备",glossary:"wan_wu_ying_bei"},"。"]]},{id:"dejiandao1_s6",label:"故通于天地者德也……能有所艺者技也",sentences:[["故通于天地者，德也；行于万物者，道也；"],[{text:"上治人者",glossary:"shang_zhi_ren"},"，",{text:"事也",glossary:"shi_ye"},"；"],[{text:"能有所艺者",glossary:"neng_you_suo_yi"},"，",{text:"技也",glossary:"ji_ye"},"。"]]},{id:"dejiandao1_s7",label:"技兼于事……道兼于天",sentences:[["技兼于事，事兼于义，义兼于德，"],["德兼于道，道兼于天。"]]},{id:"dejiandao1_s8",label:"古之畜天下者……百姓定",sentences:[["故曰：古之",{text:"畜",glossary:"xu_tian_xia"},"天下者，"],[{text:"无欲",glossary:"wu_yu"},"而天下",{text:"足",glossary:"tian_xia_zu"},"，无为而万物",{text:"化",glossary:"wan_wu_hua"},"，"],[{text:"渊静",glossary:"yuan_jing"},"而",{text:"百姓",glossary:"bai_xing"},{text:"定",glossary:"bai_xing_ding"},"。"]]},{id:"dejiandao1_s9",label:"记曰……无心得而鬼神服",sentences:[[{text:"《记》",glossary:"ji_yue"},"曰：「通于一而",{text:"万事毕",glossary:"wan_shi_bi"},"，"],[{text:"无心得",glossary:"wu_xin_de"},"而",{text:"鬼神服",glossary:"gui_shen_fu"},"。」"]]}],y=[{id:"qi_hua_jun",term:"其化均也",pinyin:"qí huà jūn yě",meaning:"天地的化育作用是均平而普遍的。化：化生、化育；均：均平、普遍。天地虽然广大，却以同一自然规律化育万物，不因私意而有所偏向。"},{id:"qi_zhi_yi",term:"其治一也",pinyin:"qí zhì yī yě",meaning:"万物的根本秩序是统一的。治：自然形成的秩序、条理；一：统一于道。万物形态虽然繁多，其生成运行所依据的根本原则却是一致的。"},{id:"ren_zu_sui_zhong",term:"人卒虽众",pinyin:"rén zú suī zhòng",meaning:"人民群众虽然众多。人卒：众人、民众；卒有群众、徒众之意。此处不是指士兵或人的死亡，而是泛指天下百姓。"},{id:"qi_zhu_jun",term:"其主君也",pinyin:"qí zhǔ jūn yě",meaning:"统领众人的主位是君主。主：主持、统领者；君：居于政治主位的人。庄子随后又指出，君主的根本在德，德又源于天，因此君主不能依个人私欲主宰天下。"},{id:"xuan_gu_zhi",term:"玄古之",pinyin:"xuán gǔ zhī",meaning:"在幽远的上古时代。玄古：玄远的古代、极其久远的时代；之：用于句中，连接时代背景与后文。玄古之君天下：上古统治天下的人。"},{id:"jun_tian_xia",term:"君天下",pinyin:"jūn tiān xià",meaning:"居君位而统领天下。君在这里用作动词，意为做天下的君主、统领天下。上古君主统领天下的根本方式不是刻意作为，而是体现自然天德。"},{id:"yi_dao_guan_yan",term:"以道观言",pinyin:"yǐ dào guān yán",meaning:"从道的立场审察名言称谓。言：名分、称谓及相关言论。以道审察君主这一名称及其实质，居君位者才能名实相符。"},{id:"tian_xia_jun_zheng",term:"天下之君正",pinyin:"tiān xià zhī jūn zhèng",meaning:"天下君主的名位得以端正。正：端正、名实相符。君主若以道为根本，才能真正符合「君」这一名号，而不是仅凭权势占据君位。"},{id:"guan_fen",term:"观分",pinyin:"guān fèn",meaning:"审察君臣各自的名分和职分。分：职分、界分，读 fèn。以道观分，才能明白君主与臣下各自应处的位置和责任。"},{id:"guan_neng",term:"观能",pinyin:"guān néng",meaning:"审察各人的才能。能：能力、才干。依据道审察才能，使官职与能力相称，天下官府的事务才能得到治理。"},{id:"fan_guan",term:"泛观",pinyin:"fàn guān",meaning:"广泛、全面地观察。泛：广泛、遍及。以道泛观，不局限于某一名分、职位或才能，而是遍观万物的变化和需要。"},{id:"wan_wu_ying_bei",term:"万物之应备",pinyin:"wàn wù zhī yìng bèi",meaning:"应对万物变化的方法无不完备。应：感应、应对；备：完备。由道遍观万物，便能随其自然情状作出适当回应，而不是以一种固定方法强制处理。"},{id:"shang_zhi_ren",term:"上治人者",pinyin:"shàng zhì rén zhě",meaning:"在上位治理人民的活动。上：居于上位，也可理解为向上承担治理；治人：处理人间政务。它属于具体的「事」，层次低于德、道与天。"},{id:"shi_ye",term:"事也",pinyin:"shì yě",meaning:"属于具体的人事和政务。事是实际治理活动，能够处理现实问题，但不是最高根本；它应当统属于义、德、道和天。"},{id:"neng_you_suo_yi",term:"能有所艺者",pinyin:"néng yǒu suǒ yì zhě",meaning:"能够在某一方面有所专长。艺：技能、才艺、专门本领。能够具体完成某项事务的是技术层面的能力。"},{id:"ji_ye",term:"技也",pinyin:"jì yě",meaning:"这属于具体的技术、技能。技只能解决局部问题，必须服从于事务；事务又须依次服从义、德、道和天，不能把技术提升为最高原则。"},{id:"xu_tian_xia",term:"畜·畜天下",pinyin:"xù · xù tiān xià",meaning:"养育、涵养天下。畜：蓄养、养育，读 xù。古之畜天下者：古代涵养天下的君主。这里强调养育、保存天下人的本性，而不是依靠权力控制天下。"},{id:"wu_yu",term:"无欲",pinyin:"wú yù",meaning:"没有以天下满足个人私欲的用心。无欲不是消灭一切自然需要，而是君主不以功名、利益和权力欲驱使天下。"},{id:"tian_xia_zu",term:"足",pinyin:"zú",meaning:"充足、知足。无欲而天下足：统治者不以私欲搜取天下，百姓便能保有生活所需，也不会被无尽欲望驱使。"},{id:"wan_wu_hua",term:"化",pinyin:"huà",meaning:"自行变化、自然生长。无为而万物化：不以人为智巧强制干预，万物反而能依照各自本性生成变化。"},{id:"yuan_jing",term:"渊静",pinyin:"yuān jìng",meaning:"像深渊一样深沉宁静。渊：深不可测；静：不躁动、不妄作。形容上位者内心虚静，不以喜怒和私欲扰动天下。"},{id:"bai_xing",term:"百姓",pinyin:"bǎi xìng",meaning:"天下人民。先秦时“百姓”原可指众多氏族，后来泛指民众。这里指受到君主政治行为影响的天下之人。"},{id:"bai_xing_ding",term:"定",pinyin:"dìng",meaning:"安定、安宁。渊静而百姓定：居上位者虚静无为，不以政令和欲望反复扰民，百姓便能自然安定。"},{id:"ji_yue",term:"《记》",pinyin:"jì",meaning:"古代流传下来的记言或典籍，具体书名已不可确考。庄子借《记》中的话总结本段：通达根本的一，万事便能自然完成。"},{id:"wan_shi_bi",term:"万事毕",pinyin:"wàn shì bì",meaning:"各种事务都能完成。毕：完成、完毕。通达统一万事的根本道体，就不必逐项以智巧经营，众事仍可各得其成。"},{id:"wu_xin_de",term:"无心得",pinyin:"wú xīn dé",meaning:"无意求得而自然有所成就。无心：没有机心和刻意求取之心；得：获得、成就。此句可理解为不以主观智巧追求功效，万物却自然归服；不宜按现代汉语解释为“没有心得”。"},{id:"gui_shen_fu",term:"鬼神服",pinyin:"guǐ shén fú",meaning:"连鬼神也自然归服。服：顺服、感服。鬼神在此代表幽微难测的自然力量；无心而合道者不刻意控制，就连幽冥变化也与之协调。"}],h=[{id:"wangde2_s1",label:"夫道覆载万物者也……君子不可以不刳心焉",sentences:[["夫子曰：「夫道，",{text:"覆载万物者",glossary:"fu_zai_wan_wu"},"也，洋洋乎大哉！"],["君子不可以不",{text:"刳心",glossary:"ku_xin"},"焉。"]]},{id:"wangde2_s2",label:"无为为之之谓天……有万不同之谓富",sentences:[["无为为之之谓天，无为言之之谓德，爱人利物之谓仁，"],[{text:"不同同之",glossary:"bu_tong_tong_zhi"},"之谓大，"],[{text:"行不崖异",glossary:"xing_bu_ya_yi"},"之谓宽，"],[{text:"有万不同",glossary:"you_wan_bu_tong"},"之谓富。"]]},{id:"wangde2_s3",label:"故执德之谓纪……不以物挫志之谓完",sentences:[["故",{text:"执德之谓纪",glossary:"zhi_de_wei_ji"},"，",{text:"德成之谓立",glossary:"de_cheng_wei_li"},"，"],["循于道",{text:"之谓备",glossary:"xun_dao_wei_bei"},"，"],[{text:"不以物挫志",glossary:"bu_yi_wu_cuo_zhi"},{text:"之谓完",glossary:"wei_wan"},"。"]]},{id:"wangde2_s4",label:"君子明于此十者……沛乎其为万物逝也",sentences:[["君子明于此十者，则",{text:"韬乎其事",glossary:"tao_hu_qi_shi"},"，",{text:"心之大也",glossary:"xin_zhi_da"},"；"],[{text:"沛乎其为",glossary:"pei_hu_qi_wei"},{text:"万物逝也",glossary:"wan_wu_shi"},"。"]]},{id:"wangde2_s5",label:"若然者藏金于山……不近贵富",sentences:[[{text:"若然者",glossary:"ruo_ran_zhe"},"，藏金于山，藏珠于渊；"],[{text:"不利货财",glossary:"bu_li_huo_cai"},"，不近贵富；"]]},{id:"wangde2_s6",label:"不乐寿不哀夭……不丑穷",sentences:[[{text:"不乐寿",glossary:"bu_le_shou"},"，",{text:"不哀夭",glossary:"bu_ai_yao"},"；"],[{text:"不荣通",glossary:"bu_rong_tong"},"，",{text:"不丑穷",glossary:"bu_chou_qiong"},"。"]]},{id:"wangde2_s7",label:"不拘一世之利以为己私分……不以王天下为己处显",sentences:[[{text:"不拘",glossary:"bu_ju"},{text:"一世之利",glossary:"yi_shi_zhi_li"},{text:"以为己私分",glossary:"yi_wei_ji_si_fen"},"，"],[{text:"不以王天下",glossary:"bu_yi_wang_tian_xia"},{text:"为己处显",glossary:"wei_ji_chu_xian"},"。"]]},{id:"wangde2_s8",label:"显则明……死生同状",sentences:[[{text:"显则明",glossary:"xian_ze_ming"},"。"],[{text:"万物一府",glossary:"wan_wu_yi_fu"},"，",{text:"死生同状",glossary:"si_sheng_tong_zhuang"},"。」"]]},{id:"wangde2_s9",label:"夫道渊乎其居也……漻乎其清也",sentences:[["夫子曰：「夫道，",{text:"渊乎其居也",glossary:"yuan_hu_qi_ju"},"，",{text:"漻乎其清也",glossary:"liao_hu_qi_qing"},"。"]]},{id:"wangde2_s10",label:"金石不得无以鸣……万物孰能定之",sentences:[["金石不得无以鸣。故金石有声，",{text:"不考不鸣",glossary:"bu_kao_bu_ming"},"。"],["万物孰能定之！"]]},{id:"wangde2_s11",label:"夫王德之人……故其德广",sentences:[["夫王德之人，",{text:"素逝",glossary:"su_shi"},"而",{text:"耻通于事",glossary:"chi_tong_yu_shi"},"，"],[{text:"立之本原",glossary:"li_zhi_ben_yuan"},"而",{text:"知通于神",glossary:"zhi_tong_yu_shen"},"，故其德广。"]]},{id:"wangde2_s12",label:"其心之出有物采之……生非德不明",sentences:[[{text:"其心之出",glossary:"qi_xin_zhi_chu"},"，",{text:"有物采之",glossary:"you_wu_cai_zhi"},"。"],[{text:"故形非道不生",glossary:"xing_fei_dao_bu_sheng"},"，",{text:"生非德不明",glossary:"sheng_fei_de_bu_ming"},"。"]]},{id:"wangde2_s13",label:"存形穷生……非王德者邪",sentences:[[{text:"存形穷生",glossary:"cun_xing_qiong_sheng"},"，",{text:"立德明道",glossary:"li_de_ming_dao"},"，"],[{text:"非王德者邪",glossary:"fei_wang_de_zhe"},"！"]]},{id:"wangde2_s14",label:"荡荡乎……此谓王德之人",sentences:[[{text:"荡荡乎",glossary:"dang_dang_hu"},"！"],[{text:"忽然出",glossary:"hu_ran_chu"},"，",{text:"勃然动",glossary:"bo_ran_dong"},"，而万物从之乎！"],["此谓王德之人。"]]},{id:"wangde2_s15",label:"视乎冥冥……独闻和焉",sentences:[[{text:"视乎冥冥",glossary:"shi_hu_ming_ming"},"，",{text:"听乎无声",glossary:"ting_hu_wu_sheng"},"。"],["冥冥之中，",{text:"独见晓焉",glossary:"du_jian_xiao"},"；"],[{text:"无声之中",glossary:"wu_sheng_zhi_zhong"},"，",{text:"独闻和焉",glossary:"du_wen_he"},"。"]]},{id:"wangde2_s16",label:"故深之又深而能物焉……神之又神而能精焉",sentences:[["故",{text:"深之又深",glossary:"shen_zhi_you_shen"},{text:"而能物焉",glossary:"er_neng_wu"},"；"],[{text:"神之又神",glossary:"shen_zhi_you_shen"},{text:"而能精焉",glossary:"er_neng_jing"},"。"]]},{id:"wangde2_s17",label:"故其与万物接也……大小长短修远",sentences:[["故其",{text:"与万物接也",glossary:"yu_wan_wu_jie"},"，"],[{text:"至无而供其求",glossary:"zhi_wu_gong_qiu"},"，",{text:"时骋而要其宿",glossary:"shi_cheng_yao_su"},"，"],["大小、长短、修远。」"]]}],m=[{id:"fu_zai_wan_wu",term:"覆载万物者",pinyin:"fù zài wàn wù zhě",meaning:"覆盖、承载一切万物的根本。覆如天覆盖万物，载如地承载万物。这里说大道无所不包，是天地万物得以生存和变化的共同根据。"},{id:"ku_xin",term:"刳心",pinyin:"kū xīn",meaning:"刳去心中的成见、欲望与机巧，使内心虚空。刳：剖开、挖空，读 kū。这里是精神修养的比喻，并非伤害身体；心虚之后，才能容纳大道和万物。"},{id:"bu_tong_tong_zhi",term:"不同同之",pinyin:"bù tóng tóng zhī",meaning:"使不同的万物在大道层面相通为一。同：视为相同、会通为一，用作动词。它不是抹杀具体差异，而是在包容差异的同时，看见万物共同根源，这就叫作“大”。"},{id:"xing_bu_ya_yi",term:"行不崖异",pinyin:"xíng bù yá yì",meaning:"行为不以边界自我标异。崖：边际、界限；异：标奇立异。大人的行为宽广通达，不故意划定界限、显示自己与众不同，故称“宽”。"},{id:"you_wan_bu_tong",term:"有万不同",pinyin:"yǒu wàn bù tóng",meaning:"包容无数彼此不同的事物。万表示极多。能够容纳万物的差异而不相排斥，内容丰富无尽，所以称为“富”。"},{id:"zhi_de_wei_ji",term:"执德之谓纪",pinyin:"zhí dé zhī wèi jì",meaning:"持守德性，就叫作纲纪。执：持守；纪：总纲、纲领。以内在德性统摄行为，万事便有根本条理，而不必依靠繁密外在规范。"},{id:"de_cheng_wei_li",term:"德成之谓立",pinyin:"dé chéng zhī wèi lì",meaning:"德性成就，就叫作确立自身。立：自立、成立。人的真正自立不在权位和声名，而在内在德性完整成熟。"},{id:"xun_dao_wei_bei",term:"循于道之谓备",pinyin:"xún yú dào zhī wèi bèi",meaning:"顺循大道，就叫作完备。循：顺从、遵行；备：完备。依道而行，才能兼顾万物而不偏滞于一端。"},{id:"bu_yi_wu_cuo_zhi",term:"不以物挫志",pinyin:"bù yǐ wù cuò zhì",meaning:"不因外物而折损自己的志意。挫：摧折、挫伤；物：财富、名位、生死、穷通等外在境遇。得道者不让外物改变内在方向。"},{id:"wei_wan",term:"之谓完",pinyin:"zhī wèi wán",meaning:"这就叫作完整无缺。完：完整、保全。不被外物摧折志意，便能保全自然德性和精神独立。"},{id:"tao_hu_qi_shi",term:"韬乎其事",pinyin:"tāo hū qí shì",meaning:"包藏、容纳其所应之事。韬：包容、收藏。君子明白十种德目后，心量足以包容众事，却不以事务扰乱本心。此句也有版本与断句解释差异。"},{id:"xin_zhi_da",term:"心之大也",pinyin:"xīn zhī dà yě",meaning:"这是内心广大无边的表现。心大不是欲望或野心广大，而是没有成见和私己，能够容纳不同的人与物。"},{id:"pei_hu_qi_wei",term:"沛乎其为",pinyin:"pèi hū qí wéi",meaning:"其作为盛大充沛、流行无碍。沛：水势盛大，也引申为充足流畅。得道者虽无心造作，其作用却能广泛流行。"},{id:"wan_wu_shi",term:"万物逝也",pinyin:"wàn wù shì yě",meaning:"使万物顺势流行、各自运行。逝：流行、前往、变化。这里不是万物死亡，而是万物随着大道自然迁流。"},{id:"ruo_ran_zhe",term:"若然者",pinyin:"ruò rán zhě",meaning:"像这样的人。若然：如此、像前文所说那样。指已经明白天、德、仁、大、宽、富、纪、立、备、完十者的君子。"},{id:"bu_li_huo_cai",term:"不利货财",pinyin:"bù lì huò cái",meaning:"不以货物钱财为利，不贪求财货。利：以……为利益、贪图。所谓藏金于山、藏珠于渊，就是让财富留在其自然所在，不据为己有。"},{id:"bu_le_shou",term:"不乐寿",pinyin:"bù lè shòu",meaning:"不因长寿而特别欣喜。乐：以……为乐，读 lè。并非厌恶生命，而是不把寿命长短作为绝对价值。"},{id:"bu_ai_yao",term:"不哀夭",pinyin:"bù āi yāo",meaning:"不因早死而陷入过度悲哀。夭：未到自然寿限而早死。得道者通达生死变化，不以寿夭扰乱本心。"},{id:"bu_rong_tong",term:"不荣通",pinyin:"bù róng tōng",meaning:"不把仕途通达视为荣耀。荣：以……为荣耀；通：显达、顺利。外在成功不能增加其内在价值。"},{id:"bu_chou_qiong",term:"不丑穷",pinyin:"bù chǒu qióng",meaning:"不把困穷失意视为羞耻。丑：以……为丑、轻视；穷：处境困顿。得道者不因穷通改变自我评价。"},{id:"bu_ju",term:"不拘",pinyin:"bù jū",meaning:"不聚敛、不独占。拘在这里有收取、据有之意。得道者不把天下的利益收拢为自己的私人份额。"},{id:"yi_shi_zhi_li",term:"一世之利",pinyin:"yī shì zhī lì",meaning:"整个时代、天下人的利益。一世：一代或当世天下。如此广大的公共利益，不能被统治者据为私有。"},{id:"yi_wei_ji_si_fen",term:"以为己私分",pinyin:"yǐ wéi jǐ sī fèn",meaning:"把它当作自己私有的份额。私分：个人所独占的利益，分读 fèn。得道者不将天下财富、土地和功业视为私人所有。"},{id:"bu_yi_wang_tian_xia",term:"不以王天下",pinyin:"bù yǐ wàng tiān xià",meaning:"不把统治天下这件事当作自己的荣耀。王：在天下称王、统治天下，用作动词，读 wàng。"},{id:"wei_ji_chu_xian",term:"为己处显",pinyin:"wéi jǐ chǔ xiǎn",meaning:"把统治天下看成自己居于显要地位。处显：处在尊贵显赫的位置。王德之人即使居天下之上，也不以权位彰显私己。"},{id:"xian_ze_ming",term:"显则明",pinyin:"xiǎn zé míng",meaning:"真正的显现只是自然明著。显不是个人炫耀权势，而是德性自然显明；明则无所偏私，能够照见万物一体。"},{id:"wan_wu_yi_fu",term:"万物一府",pinyin:"wàn wù yī fǔ",meaning:"万物同在一个府库、共同归于一体。一府是比喻，表示万物虽有差别，却共同蕴藏于大道，没有绝对隔阂。"},{id:"si_sheng_tong_zhuang",term:"死生同状",pinyin:"sǐ shēng tóng zhuàng",meaning:"死亡与生存同为大道变化的形态。状：状态、形态。不是否认生死差异，而是从道的整体看，二者都是生命变化过程，没有绝对价值高下。"},{id:"yuan_hu_qi_ju",term:"渊乎其居也",pinyin:"yuān hū qí jū yě",meaning:"大道静处时像深渊一样深沉。居：静止、安居；渊：幽深难测。道的根本状态寂静无形，却蕴含生成万物的力量。"},{id:"liao_hu_qi_qing",term:"漻乎其清也",pinyin:"liáo hū qí qīng yě",meaning:"大道清澈寥远。漻：清澈、寂寥，读 liáo。形容道虚静纯净，不受外物和人为欲望污染。"},{id:"bu_kao_bu_ming",term:"不考不鸣",pinyin:"bù kǎo bù míng",meaning:"不敲击就不会发声。考：敲击，读 kǎo。金石虽有发声的可能，也必须受到感触才鸣；比喻道或王德之人虚静无为，有所感才自然回应。"},{id:"su_shi",term:"素逝",pinyin:"sù shì",meaning:"依循朴素本然而行。素：朴素、未经人为文饰；逝：运行、前往。王德之人顺着自然本性行进，不以机巧追逐功业。"},{id:"chi_tong_yu_shi",term:"耻通于事",pinyin:"chǐ tōng yú shì",meaning:"以专门通晓世俗事务、智巧经营为可耻。耻：以……为耻；通于事：擅长繁琐事务和权术。这里不是拒绝一切事务，而是不以处理事务的技巧自负。"},{id:"li_zhi_ben_yuan",term:"立之本原",pinyin:"lì zhī běn yuán",meaning:"把自己确立在万物的根本本原之上。立：确立、安顿；本原：道的根源。王德之人不立足于枝末技术，而安处于大道本根。"},{id:"zhi_tong_yu_shen",term:"知通于神",pinyin:"zhì tōng yú shén",meaning:"智慧通达神妙的自然变化。知通“智”，读 zhì；神：幽微莫测的化育作用。因为立足本原，所以能够领会万物神妙变化。"},{id:"qi_xin_zhi_chu",term:"其心之出",pinyin:"qí xīn zhī chū",meaning:"他的心向外驰出。出：向外追逐、显露分别意识。内心一旦离开虚静本原而追逐外物，便会受到外物染饰。"},{id:"you_wu_cai_zhi",term:"有物采之",pinyin:"yǒu wù cǎi zhī",meaning:"便有外物染饰、牵引它。采：文彩、染饰，也可理解为外物采纳、占据其心。心向外驰逐，就会被名利、声色和成见塑造。"},{id:"xing_fei_dao_bu_sheng",term:"形非道不生",pinyin:"xíng fēi dào bù shēng",meaning:"形体没有大道就不能生成。形：有形生命；道：生成万物的根本。道是生命形体得以产生的根源。"},{id:"sheng_fei_de_bu_ming",term:"生非德不明",pinyin:"shēng fēi dé bù míng",meaning:"生命没有德便不能显明其本性。德是道落实于个体生命的内在所得；生命通过德，才能充分展现其自然光明。"},{id:"cun_xing_qiong_sheng",term:"存形穷生",pinyin:"cún xíng qióng shēng",meaning:"保存形体，使生命充分发展到自然限度。存：保全；穷：穷尽、充分实现。不是贪求肉体永生，而是不以人为欲望损害自然生命。"},{id:"li_de_ming_dao",term:"立德明道",pinyin:"lì dé míng dào",meaning:"确立内在德性，彰明大道。立德使个体生命有所根据，明道则通达天地万物的共同根源。"},{id:"fei_wang_de_zhe",term:"非王德者邪",pinyin:"fēi wáng dé zhě yé",meaning:"这难道不是具有王者之德的人吗？邪：反问语气词，读 yé。王德不单指政治权力，而是能保全生命、彰明大道、使万物自从的广大德性。"},{id:"dang_dang_hu",term:"荡荡乎",pinyin:"dàng dàng hū",meaning:"广大开阔、无边无际的样子。荡荡形容王德宽广无碍，能够涵容万物而不受固定边界限制。"},{id:"hu_ran_chu",term:"忽然出",pinyin:"hū rán chū",meaning:"无迹而自然显现。忽然：迅疾、无形迹的样子；出：出现、发动。王德之人的行动没有刻意谋划，因应事物而突然显现。"},{id:"bo_ran_dong",term:"勃然动",pinyin:"bó rán dòng",meaning:"蓬勃迅速地发动。勃然：兴起有力的样子。行动一旦发动便富有生命力，万物自然响应，而非受到强迫。"},{id:"shi_hu_ming_ming",term:"视乎冥冥",pinyin:"shì hū míng míng",meaning:"在幽冥不可见之处观看。冥冥：幽暗深远、没有具体形迹。王德之人不只观察外在现象，还能体察无形的根本。"},{id:"ting_hu_wu_sheng",term:"听乎无声",pinyin:"tīng hū wú shēng",meaning:"在没有声音之处聆听。指超越普通感官分辨，体会万物尚未发声以前的自然和谐。"},{id:"du_jian_xiao",term:"独见晓焉",pinyin:"dú jiàn xiǎo yān",meaning:"唯独能够在幽冥中看见明晓。晓：明白、光明。一般人只见有形现象，得道者却能在无形幽暗中体察大道的明晰。"},{id:"wu_sheng_zhi_zhong",term:"无声之中",pinyin:"wú shēng zhī zhōng",meaning:"在尚未形成具体声音的寂静境界中。它不是绝对空无，而是各种声音尚未分化、仍含自然和谐的状态。"},{id:"du_wen_he",term:"独闻和焉",pinyin:"dú wén hé yān",meaning:"唯独能够听见其中的和谐。和：阴阳、万物协调的根本节律。并非真的以耳朵听见无声，而是心神体会到无声之和。"},{id:"shen_zhi_you_shen",term:"深之又深",pinyin:"shēn zhī yòu shēn",meaning:"深入到更加幽深的根本。连续两个“深”强调不断超越表层现象，进入大道幽微难测的层次。"},{id:"shen_zhi_you_shen",term:"神之又神",pinyin:"shén zhī yòu shén",meaning:"神妙之中更加神妙。神指不可用固定形迹测度的自然变化；此句形容王德之人对大道变化的体会精微至极。"},{id:"er_neng_wu",term:"而能物焉",pinyin:"ér néng wù yān",meaning:"因而能够使万物各得其所。物用作动词，可理解为统摄、成就万物。越能深入无形本原，越能自然应对有形万物。"},{id:"er_neng_jing",term:"而能精焉",pinyin:"ér néng jīng yān",meaning:"因而能够达到精微纯粹。精：精微、本质，也有使万物精纯之意。通于神妙之道，才能把握生命最精微的根本。"},{id:"yu_wan_wu_jie",term:"与万物接也",pinyin:"yǔ wàn wù jiē yě",meaning:"与万物发生接触、应接万物。王德之人虽安处虚无，并不隔绝现实；万物到来时，仍能按照各自情状自然回应。"},{id:"zhi_wu_gong_qiu",term:"至无而供其求",pinyin:"zhì wú ér gōng qí qiú",meaning:"自身达到至虚无私，却能供应万物的需求。至无：不执著私己、不预设成见；供其求：因应万物所需。正因无私无执，才能不偏不倚地满足万物。"},{id:"shi_cheng_yao_su",term:"时骋而要其宿",pinyin:"shí chěng ér yāo qí sù",meaning:"随时舒展运行，并最终会归于其本根。时骋：因时运行、自由舒展；要：会合、归结；宿：归宿、本处。此句古注存在分歧，整体形容王德随万物变化而展开，又使万物各归其自然归宿。"}],l=[{id:"xuanzhu3_s1",label:"黄帝游乎赤水之北……登乎昆仑之丘而南望",sentences:[["黄帝游乎",{text:"赤水之北",glossary:"chi_shui_zhi_bei"},"，登乎昆仑之丘而南望。"]]},{id:"xuanzhu3_s2",label:"还归……遗其玄珠",sentences:[[{text:"还归",glossary:"huan_gui"},"，",{text:"遗其玄珠",glossary:"yi_qi_xuan_zhu"},"。"]]},{id:"xuanzhu3_s3",label:"使知索之而不得……使离朱索之而不得",sentences:[[{text:"使知索之",glossary:"shi_zhi_suo_zhi"},"而不得，"],["使",{text:"离朱",glossary:"li_zhu"},{text:"索之而不得",glossary:"suo_zhi_bu_de"},"，"]]},{id:"xuanzhu3_s4",label:"使喫诟索之而不得也……象罔得之",sentences:[["使",{text:"喫诟",glossary:"chi_gou"},"索之而不得也。"],["乃使",{text:"象罔",glossary:"xiang_wang"},"，",{text:"象罔得之",glossary:"xiang_wang_de_zhi"},"。"]]},{id:"xuanzhu3_s5",label:"黄帝曰异哉……象罔乃可以得之乎",sentences:[["黄帝曰：「",{text:"异哉",glossary:"yi_zai"},"，"],[{text:"象罔乃可以得之乎",glossary:"xiang_wang_nai_ke_de"},"？」"]]}],u=[{id:"chi_shui_zhi_bei",term:"赤水之北",pinyin:"chì shuǐ zhī běi",meaning:"神话地理中赤水以北的地方。赤水是传说中的水名；其北与昆仑之丘共同构成幽远、超越日常世界的空间。寓言借黄帝远游写精神向玄远境界探求。"},{id:"huan_gui",term:"还归",pinyin:"huán guī",meaning:"返回、归来。还：返回，读 huán；归：回到原处。黄帝从昆仑南望之后返回，却发现玄珠已经遗失。"},{id:"yi_qi_xuan_zhu",term:"遗其玄珠",pinyin:"yí qí xuán zhū",meaning:"遗失了他的玄珠。遗：丢失；玄珠：深黑幽玄的宝珠。寓言中玄珠通常象征幽深玄妙的大道、人的自然本性或纯一的精神。遗失玄珠，象征因向外观览和驰求而失去内在本真。"},{id:"shi_zhi_suo_zhi",term:"使知索之",pinyin:"shǐ zhì suǒ zhī",meaning:"让“知”去寻找玄珠。使：派遣；知通“智”，读 zhì，是智虑的拟人化；索：寻找；之：代指玄珠。智慧虽然善于思考分析，却不能凭分别智把握大道。"},{id:"li_zhu",term:"离朱",pinyin:"lí zhū",meaning:"传说中目力极强的人，也称离娄。这里象征敏锐的视觉和感官认识。离朱能够看见细微的有形之物，却不能发现无形无迹的玄道。"},{id:"suo_zhi_bu_de",term:"索之而不得",pinyin:"suǒ zhī ér bù dé",meaning:"寻找玄珠却没有找到。索：搜求、寻找；之：代指玄珠；不得：不能得到。反复出现这一句，说明大道不能通过刻意的外在搜寻获得。"},{id:"chi_gou",term:"喫诟",pinyin:"chī gòu",meaning:"寓言中的人物名，古注多解释为善于言语辩论者。喫诟象征语言、名辩和逻辑辨析。即使善于言说辩论，也不能通过概念和语言捕捉玄妙无形的大道。此词训释较为古奥，旧注存在不同说法。"},{id:"xiang_wang",term:"象罔",pinyin:"xiàng wǎng",meaning:"寓言中的人物名，也写作“罔象”。象有形象、迹象之意，罔有无、没有之意，合起来表示似有若无、无形无迹。象罔象征无心、虚静、不依赖感官与智辩的体道方式。"},{id:"xiang_wang_de_zhi",term:"象罔得之",pinyin:"xiàng wǎng dé zhī",meaning:"象罔找到了玄珠。之：代指玄珠。智虑、视觉和言辩都不能得到玄珠，似有若无、无心无迹的象罔反而能够得到，说明虚静无心比刻意求索更接近大道。"},{id:"yi_zai",term:"异哉",pinyin:"yì zāi",meaning:"奇异啊、令人惊异啊。异：奇异；哉：感叹语气词。黄帝惊讶于有知识、有目力、有言辩能力者都失败，唯独象罔成功。"},{id:"xiang_wang_nai_ke_de",term:"象罔乃可以得之乎",pinyin:"xiàng wǎng nǎi kě yǐ dé zhī hū",meaning:"竟然只有象罔能够得到玄珠吗？乃：竟然、原来；可以：能够；之：玄珠；乎：疑问兼感叹语气。这是黄帝领悟后的惊叹，点明大道不能依靠智虑、视觉和言辩求得，反而要以虚静无心与之相应。"}],o=[{id:"nieque4_s1",label:"尧之师曰许由……王倪之师曰被衣",sentences:[["尧之师曰",{text:"许由",glossary:"xu_you"},"，许由之师曰",{text:"啮缺",glossary:"nie_que"},"，"],["啮缺之师曰",{text:"王倪",glossary:"wang_ni"},"，王倪之师曰",{text:"被衣",glossary:"pi_yi"},"。"]]},{id:"nieque4_s2",label:"尧问于许由曰……吾藉王倪以要之",sentences:[["尧问于许由曰：「啮缺可以",{text:"配天",glossary:"pei_tian"},"乎？"],["吾",{text:"藉",glossary:"jie_wang_ni"},"王倪",{text:"以要之",glossary:"yi_yao_zhi"},"。」"]]},{id:"nieque4_s3",label:"许由曰殆哉……圾乎天下",sentences:[["许由曰：「",{text:"殆哉",glossary:"dai_zai"},"，",{text:"圾乎天下",glossary:"ji_hu_tian_xia"},"！"]]},{id:"nieque4_s4",label:"啮缺之为人也……而又乃以人受天",sentences:[["啮缺之为人也，聪明睿知，",{text:"给数以敏",glossary:"ji_shu_yi_min"},"，其性过人，"],[{text:"而又乃",glossary:"er_you_nai"},{text:"以人受天",glossary:"yi_ren_shou_tian"},"。"]]},{id:"nieque4_s5",label:"彼审乎禁过……与之配天乎",sentences:[[{text:"彼审乎禁过",glossary:"shen_hu_jin_guo"},"，而不知",{text:"过之所由生",glossary:"guo_suo_you_sheng"},"。"],["与之配天乎？"]]},{id:"nieque4_s6",label:"彼且乘人而无天……方且尊知而火驰",sentences:[["彼且",{text:"乘人而无天",glossary:"cheng_ren_wu_tian"},"。"],[{text:"方且",glossary:"fang_qie"},"本身而异形，方且",{text:"尊知而火驰",glossary:"zun_zhi_huo_chi"},"，"]]},{id:"nieque4_s7",label:"方且为绪使……方且应众宜",sentences:[["方且为",{text:"绪使",glossary:"wei_xu_shi"},"，方且为",{text:"物絯",glossary:"wei_wu_gai"},"，"],["方且",{text:"四顾而物应",glossary:"si_gu_wu_ying"},"，方且",{text:"应众宜",glossary:"ying_zhong_yi"},"，"]]},{id:"nieque4_s8",label:"方且与物化而未始有恒……夫何足以配天乎",sentences:[["方且与物化而",{text:"未始有恒",glossary:"wei_shi_you_heng"},"。"],["夫何足以配天乎！"]]},{id:"nieque4_s9",label:"虽然有族有祖……不可以为众父父",sentences:[["虽然，有族有祖，可以为",{text:"众父",glossary:"zhong_fu"},"而不可以为",{text:"众父父",glossary:"zhong_fu_fu"},"。"]]},{id:"nieque4_s10",label:"治乱之率也……南面之贼也",sentences:[["治，",{text:"乱之率也",glossary:"luan_zhi_shuai"},"，"],[{text:"北面之祸",glossary:"bei_mian_zhi_huo"},"也，",{text:"南面之贼",glossary:"nan_mian_zhi_zei"},"也。」"]]}],d=[{id:"xu_you",term:"许由",pinyin:"xǔ yóu",meaning:"传说中的上古隐士，也是庄子寓言中的得道者。相传尧曾想把天下让给他，他却拒不接受。文中尧尊许由为师，借此表示道的层次高于世俗君位。"},{id:"nie_que",term:"啮缺",pinyin:"niè quē",meaning:"庄子寓言中的人物，为许由之师、王倪之弟子。其名有牙齿残缺之意。许由认为他虽然聪明敏捷，却仍依赖人为智巧，不能与无为天道相配。"},{id:"wang_ni",term:"王倪",pinyin:"wáng ní",meaning:"庄子寓言中的得道者，为啮缺之师、被衣之弟子。尧想借助王倪邀请或促使啮缺出任与天相配的治理者。"},{id:"pi_yi",term:"被衣",pinyin:"pī yī",meaning:"庄子寓言中的上古得道者，为王倪之师。被衣即披着衣服，名称带有朴素自然、不加文饰的意味。"},{id:"pei_tian",term:"配天",pinyin:"pèi tiān",meaning:"与天道相配，代天治理天下。配：匹配、配合。这里不是说与天平等，而是说其德行是否足以顺应天道、居于统治天下的位置。"},{id:"jie_wang_ni",term:"藉",pinyin:"jiè",meaning:"借助、凭借。尧想借助王倪与啮缺之间的师生关系，请啮缺出来配天治理。此处不读表示狼藉的 jí。"},{id:"yi_yao_zhi",term:"以要之",pinyin:"yǐ yāo zhī",meaning:"借此邀请、约请或促使他接受。要通“邀”，读 yāo；之：代指啮缺。旧注也有理解为要约、强使就任者，核心都是借王倪促成啮缺出任。"},{id:"dai_zai",term:"殆哉",pinyin:"dài zāi",meaning:"危险啊。殆：危险；哉：感叹语气。许由认为让依赖聪明智术的啮缺配天治理，将给天下带来危险。"},{id:"ji_hu_tian_xia",term:"圾乎天下",pinyin:"jí hū tiān xià",meaning:"将使天下陷入危险。圾：危险、危殆，属于古义；乎：表示感叹。“殆哉，圾乎天下”是说此举危险，会危害天下，并非现代汉语的垃圾之义。"},{id:"ji_shu_yi_min",term:"给数以敏",pinyin:"jǐ shù yǐ mǐn",meaning:"口才便捷，智术繁多，反应敏锐。给：言辞敏捷，读 jǐ；数：智术、谋略；敏：敏捷。形容啮缺才智过人，却也因此容易依赖人为机巧。"},{id:"er_you_nai",term:"而又乃",pinyin:"ér yòu nǎi",meaning:"而且竟然又。乃：竟然、还。承接啮缺聪明过人的特点，进一步指出他还试图以人为智巧干预天道。"},{id:"yi_ren_shou_tian",term:"以人受天",pinyin:"yǐ rén shòu tiān",meaning:"以人为智巧承接、处理乃至干预自然天道。人：人为、人的心智和作为；天：自然本性与天道。啮缺不是虚静地顺任自然，而是试图用人的知识安排天，因此不能配天。"},{id:"shen_hu_jin_guo",term:"彼审乎禁过",pinyin:"bǐ shěn hū jìn guò",meaning:"他很明白怎样禁止已经发生的过失。审：清楚、明白；禁过：制止错误。啮缺善于制定办法防范过失，却仍停留在事后治理的层面。"},{id:"guo_suo_you_sheng",term:"过之所由生",pinyin:"guò zhī suǒ yóu shēng",meaning:"过失产生的根源。所由生：从哪里产生。许由批评啮缺只懂得禁止表面的错误，却不知道分别、禁制和人为治理本身也可能成为过失的来源。"},{id:"cheng_ren_wu_tian",term:"乘人而无天",pinyin:"chéng rén ér wú tiān",meaning:"依仗人为智术而忽略自然天道。乘：凭借、利用；人：人为；无天：心中没有自然天道。它概括了许由对啮缺的根本批评。"},{id:"fang_qie",term:"方且",pinyin:"fāng qiě",meaning:"正将、正要、而且还会。下文连续使用“方且”，列举啮缺若治理天下将会产生的一系列弊病。"},{id:"zun_zhi_huo_chi",term:"尊知而火驰",pinyin:"zūn zhì ér huǒ chí",meaning:"尊崇智巧，使心神像火一样迅疾奔驰。知通“智”，读 zhì；火驰：如火势般急速奔逐。形容思虑躁动、争相应物，不能保持虚静。"},{id:"wei_xu_shi",term:"为绪使",pinyin:"wéi xù shǐ",meaning:"被纷繁的事务线索驱使。绪：事物的端绪、头绪；使：役使。啮缺企图处理一切事务，结果反而受复杂事务支配，不能自主。"},{id:"wei_wu_gai",term:"为物絯",pinyin:"wéi wù gāi",meaning:"被外物束缚、牵制。絯：束缚、阻碍，读 gāi。越想依靠智术控制万物，越会被万物的变化牵累。"},{id:"si_gu_wu_ying",term:"四顾而物应",pinyin:"sì gù ér wù yìng",meaning:"向四方察看，不断应对外物。四顾：环顾四方；物应：与各种外物相接应。形容心神向外驰逐，处处观察、事事回应，不能守住根本。"},{id:"ying_zhong_yi",term:"应众宜",pinyin:"yìng zhòng yí",meaning:"应付众多不同的适宜标准。宜：合宜的办法、具体情势。啮缺忙于针对各种情况作出权宜处置，却缺乏恒常的天道根本。"},{id:"wei_shi_you_heng",term:"未始有恒",pinyin:"wèi shǐ yǒu héng",meaning:"从来没有恒常不变的根本。未始：未曾、从来没有；恒：恒常准则。啮缺随外物变化而变化，却不能安立于道，因而没有内在主宰。"},{id:"zhong_fu",term:"众父",pinyin:"zhòng fù",meaning:"众人的父长、领导者。父在这里不是血缘意义上的父亲，而是养育、领导众人的政治角色。啮缺有才智，可以在某一群体中担任领导者。"},{id:"zhong_fu_fu",term:"众父父",pinyin:"zhòng fù fù",meaning:"众多父长的父长，即超越一般统治者的最高根本。前一个“众父”指众人的领导者，末一“父”表示其本原。啮缺只能成为具体领导者，不能成为使所有领导者有所本的天道化身。"},{id:"luan_zhi_shuai",term:"乱之率也",pinyin:"luàn zhī shuài yě",meaning:"是祸乱的先导。率：引领、开端，读 shuài。刻意以智术治理，看似要消除混乱，实际上率先破坏自然秩序，成为进一步祸乱的根源。"},{id:"bei_mian_zhi_huo",term:"北面之祸",pinyin:"běi miàn zhī huò",meaning:"处于臣位时将造成祸患。古代君主面南而坐，臣下面北朝君，因此北面代表臣位。依靠智术的人若为臣，会以繁密事务和人为谋略扰乱政事。"},{id:"nan_mian_zhi_zei",term:"南面之贼",pinyin:"nán miàn zhī zéi",meaning:"处于君位时将成为天下的祸害。古代君主面南而坐，因此南面代表君位；贼：伤害、祸害。这样的人若成为君主，会用个人智术破坏天下的自然秩序。"}],x=[{id:"huafeng5_s1",label:"尧观乎华……请祝圣人使圣人寿",sentences:[["尧观乎华，",{text:"华封人",glossary:"hua_feng_ren"},"曰：「嘻，圣人！"],[{text:"请祝",glossary:"qing_zhu"},"圣人，使圣人",{text:"寿",glossary:"shou"},"。」"]]},{id:"huafeng5_s2",label:"尧曰辞……使圣人多男子尧曰辞",sentences:[["尧曰：「",{text:"辞",glossary:"ci"},"。」"],["「使圣人",{text:"富",glossary:"fu"},"。」尧曰：「辞。」"],["「使圣人",{text:"多男子",glossary:"duo_nan_zi"},"。」尧曰：「辞。」"]]},{id:"huafeng5_s3",label:"寿富多男子……女独不欲何邪",sentences:[["封人曰：「寿，富，多男子，人之所欲也。"],["女独不欲，何邪？」"]]},{id:"huafeng5_s4",label:"多男子则多惧……非所以养德也故辞",sentences:[["尧曰：「多男子则多惧，富则多事，寿则多辱。"],["是三者，非所以养德也，故辞。」"]]},{id:"huafeng5_s5",label:"始也我以女为圣人邪……今然君子也",sentences:[["封人曰：「",{text:"始",glossary:"shi_chu"},"也我以女为圣人邪，今然君子也。"]]},{id:"huafeng5_s6",label:"天生万民必授之职……则何惧之有",sentences:[["天生万民，",{text:"必授之职",glossary:"bi_shou_zhi_zhi"},"。"],["多男子而授之职，则何惧之有？"]]},{id:"huafeng5_s7",label:"富而使人分之……则何事之有",sentences:[["富而使人分之，则何事之有？"]]},{id:"huafeng5_s8",label:"夫圣人鹑居而彀食……鸟行而无彰",sentences:[["夫圣人，",{text:"鹑居而彀食",glossary:"chun_ju_kou_shi"},"，"],[{text:"鸟行而无彰",glossary:"niao_xing_wu_zhang"},"。"]]},{id:"huafeng5_s9",label:"天下有道则与物皆昌……天下无道则修德就闲",sentences:[["天下有道，则与物皆",{text:"昌",glossary:"chang"},"；"],["天下无道，则",{text:"修德就闲",glossary:"xiu_de_jiu_xian"},"。"]]},{id:"huafeng5_s10",label:"千岁厌世……至于帝乡",sentences:[["千岁厌世，去而上仙，乘彼白云，至于帝乡。"]]},{id:"huafeng5_s11",label:"三患莫至……则何辱之有",sentences:[["三患莫至，身常无殃，则何辱之有？」"]]},{id:"huafeng5_s12",label:"封人去之……尧随之曰请问",sentences:[["封人去之，尧",{text:"随之",glossary:"sui_zhi"},"曰：「",{text:"请问",glossary:"qing_wen"},"。」"]]},{id:"huafeng5_s13",label:"封人曰……退已",sentences:[["封人曰：「",{text:"退已",glossary:"tui_yi"},"！」"]]}],p=[{id:"hua_feng_ren",term:"华封人",pinyin:"huà fēng rén",meaning:"华地主管疆界的官吏。华：地名，读 huà；封人：守卫或管理疆界的人。庄子寓言常借身份卑微的普通人说出高于帝王的道理，华封人实际是一位深通天道的隐者形象。"},{id:"qing_zhu",term:"请祝",pinyin:"qǐng zhù",meaning:"请允许我为您祝愿。请：表示请求；祝：祝祷、祝愿。华封人依次祝尧长寿、富有、多子，提出世人通常追求的三种福分。"},{id:"shou",term:"寿",pinyin:"shòu",meaning:"长寿、寿命长。尧认为长寿会经历更多屈辱，因而拒绝；封人则认为真正的圣人不受外物伤害，长寿本身不会构成屈辱。"},{id:"fu",term:"富",pinyin:"fù",meaning:"财富丰足。尧认为财富越多，事务和牵累也越多；封人则指出，若让众人共同分享财富而不据为私有，便不会产生事务之累。"},{id:"ci",term:"辞",pinyin:"cí",meaning:"推辞、拒绝。尧连续三次辞谢长寿、富有和多子的祝愿，认为它们会分别带来辱、事、惧，不利于涵养德性。"},{id:"duo_nan_zi",term:"多男子",pinyin:"duō nán zǐ",meaning:"有许多儿子。男子在这里特指儿子。尧认为儿子多便会有更多忧惧；封人则认为天生每个人，必然赋予他相应的职分，让儿子各任其职便无须忧惧。"},{id:"shi_chu",term:"始",pinyin:"shǐ",meaning:"起初、开始时。“始也我以女为圣人邪”意为起初我还以为你是圣人。封人听到尧的解释后，认为尧仍害怕外物牵累，只能算君子，尚未达到圣人境界。"},{id:"bi_shou_zhi_zhi",term:"必授之职",pinyin:"bì shòu zhī zhí",meaning:"必然赋予他相应的职分。授：给予；之：代指每一个人；职：职责、自然功能。封人认为天生万民，各有适合自己的位置和作用，无须由父母全部操心安排。"},{id:"chun_ju_kou_shi",term:"鹑居而彀食",pinyin:"chún jū ér kòu shí",meaning:"像鹌鹑一样居无定所，像幼鸟一样接受自然供养。鹑居：鹌鹑随处栖息，不营固定巢穴；“彀”通行本多作“鷇”，指待哺幼鸟，读 kòu。全句形容圣人不营造固定居处，不积聚财物，随顺自然生活。"},{id:"niao_xing_wu_zhang",term:"鸟行而无彰",pinyin:"niǎo xíng ér wú zhāng",meaning:"像鸟飞行一样不留下可供夸示的踪迹。彰：彰明、显著。鸟飞过天空不留痕迹，比喻圣人行动自然，不刻意彰显功业，也不让自己的作为束缚万物。"},{id:"chang",term:"昌",pinyin:"chāng",meaning:"昌盛、生长繁荣。天下有道时，圣人与万物共同生长兴盛，不独占万物之利，也不把自己的昌盛建立在万物受损之上。"},{id:"xiu_de_jiu_xian",term:"修德就闲",pinyin:"xiū dé jiù xián",meaning:"修养德性，退处清闲。修德：涵养自身德性；就闲：趋向闲静、退居无事之地。天下无道时，圣人不强行干预，也不以功名为念，而是保全本性、等待时机。"},{id:"sui_zhi",term:"随之",pinyin:"suí zhī",meaning:"跟随他而去。之：代指华封人。尧听完封人的议论，认识到自己尚未达到圣人境界，于是追随封人，希望继续请教。"},{id:"qing_wen",term:"请问",pinyin:"qǐng wèn",meaning:"请允许我继续请教。尧从一开始接受祝愿的对象，转变为追随封人求教的学生，显示帝王与得道者身份地位的倒转。"},{id:"tui_yi",term:"退已",pinyin:"tuì yǐ",meaning:"退下吧、停止吧。“已”通“矣”，也有停止之意。封人拒绝继续回答，既可理解为让尧退去，也表明真正的道不能仅靠追问和言说获得，必须由尧自己体会。"}],z=[{id:"bocheng6_s1",label:"尧治天下……伯成子高立为诸侯",sentences:[["尧治天下，伯成子高立为诸侯。"]]},{id:"bocheng6_s2",label:"尧授舜……伯成子高辞为诸侯而耕",sentences:[["尧",{text:"授",glossary:"shou_tian_xia"},"舜，舜授禹，"],["伯成子高辞为诸侯而",{text:"耕",glossary:"geng"},"。"]]},{id:"bocheng6_s3",label:"禹往见之……立而问焉",sentences:[["禹往见之，则耕在野。"],["禹",{text:"趋就下风",glossary:"qu_jiu_xia_feng"},"，",{text:"立而问焉",glossary:"li_er_wen_yan"},"。"]]},{id:"bocheng6_s4",label:"昔尧治天下……敢问其故何也",sentences:[["曰：「昔尧治天下，吾子立为诸侯。"],["尧授舜，舜",{text:"授予",glossary:"shou_yu"},"，而吾子辞为诸侯而耕。"],["敢问其故何也？」"]]},{id:"bocheng6_s5",label:"昔者尧治天下……不罚而民畏",sentences:[["子高曰：「昔者尧治天下，",{text:"不赏而民劝",glossary:"bu_shang_min_quan"},"，"],[{text:"不罚而民畏",glossary:"bu_fa_min_wei"},"。"]]},{id:"bocheng6_s6",label:"今子赏罚而民且不仁……刑自此立",sentences:[["今子赏罚而",{text:"民且不仁",glossary:"min_qie_bu_ren"},"，"],[{text:"德自此衰",glossary:"de_zi_ci_shuai"},"，",{text:"刑自此立",glossary:"xing_zi_ci_li"},"，"]]},{id:"bocheng6_s7",label:"后世之乱自此始矣……无落吾事",sentences:[[{text:"后世之乱",glossary:"hou_shi_zhi_luan"},{text:"自此始矣",glossary:"zi_ci_shi_yi"},"！"],[{text:"夫子阖行邪",glossary:"fu_zi_he_xing"},"？"],[{text:"无落吾事",glossary:"wu_luo_wu_shi"},"！」"]]},{id:"bocheng6_s8",label:"俋俋乎耕……而不顾",sentences:[[{text:"俋俋乎",glossary:"yi_yi_hu"},"耕",{text:"而不顾",glossary:"geng_er_bu_gu"},"。"]]}],b=[{id:"shou_tian_xia",term:"授",pinyin:"shòu",meaning:"交付、传让。这里指尧将天下传给舜、舜再传给禹。它表示君位的转移，不是一般的教授或赏赐。"},{id:"geng",term:"耕",pinyin:"gēng",meaning:"耕种田地。伯成子高辞去诸侯之位，亲自在田野耕作，表示他放弃权位与人为政治，回归朴素自食其力的生活。"},{id:"qu_jiu_xia_feng",term:"趋就下风",pinyin:"qū jiù xià fēng",meaning:"快步走到下风的位置。趋：小步快走，表示恭敬；就：走近；下风：风向的下方，也是谦卑的位置。禹以君主身份谦敬地向伯成子高请教。"},{id:"li_er_wen_yan",term:"立而问焉",pinyin:"lì ér wèn yān",meaning:"站在那里向他询问。焉：兼有“于之”的意思，即向伯成子高。禹来到下风处站立发问，表现出对这位辞位隐者的尊重。"},{id:"shou_yu",term:"授予",pinyin:"shòu yǔ",meaning:"把天下交给我。此处应理解为“授予”，予是第一人称代词“我”，指说话者禹；不能把二字连读成现代汉语中表示给予的动词“授予”。"},{id:"bu_shang_min_quan",term:"不赏而民劝",pinyin:"bù shǎng ér mín quàn",meaning:"不用奖赏，人民便能自相勉励、勤勉向善。劝：勉励、勤勉。伯成子高认为，尧以自然德性化民，人民并非为了追求奖赏才行善。"},{id:"bu_fa_min_wei",term:"不罚而民畏",pinyin:"bù fá ér mín wèi",meaning:"不用刑罚，人民便自然有所敬畏。畏不是单纯害怕暴力，而是感受德化、敬畏自然规范，不愿主动为恶。"},{id:"min_qie_bu_ren",term:"民且不仁",pinyin:"mín qiě bù rén",meaning:"人民将要渐渐失去自然仁厚之性。且：将要。伯成子高认为，奖赏使人逐利，刑罚使人避害；人们若只为赏罚行动，其自然德性便会受到损害。"},{id:"de_zi_ci_shuai",term:"德自此衰",pinyin:"dé zì cǐ shuāi",meaning:"自然淳厚的德性从此开始衰败。自此：从这里、从实行赏罚开始。外在奖惩越受重视，人民发自内心的自然德性就越容易被功利计算取代。"},{id:"xing_zi_ci_li",term:"刑自此立",pinyin:"xíng zì cǐ lì",meaning:"刑罚制度从此确立并受到倚重。立：建立、确立。当德化衰退后，统治者便依赖外在刑罚维持秩序；刑罚的建立又会进一步强化人民的趋利避害之心。"},{id:"hou_shi_zhi_luan",term:"后世之乱",pinyin:"hòu shì zhī luàn",meaning:"后代社会的祸乱。伯成子高认为，有意设置赏罚虽然以治理为目的，却会破坏人民的自然淳朴，成为后世混乱的根源。"},{id:"zi_ci_shi_yi",term:"自此始矣",pinyin:"zì cǐ shǐ yǐ",meaning:"从这里开始了。此：指禹依靠赏罚进行治理；矣：表示变化已经发生。此句把由无为德化转向外在赏罚视为政治衰败的转折点。"},{id:"fu_zi_he_xing",term:"夫子阖行邪",pinyin:"fū zǐ hé xíng yé",meaning:"先生为什么还不离开呢？夫子：对禹的称呼；阖：何不、为什么不，读 hé；行：离开、走；邪：疑问语气词，读 yé。伯成子高不愿继续谈论政治，直接请禹离去。"},{id:"wu_luo_wu_shi",term:"无落吾事",pinyin:"wú luò wú shì",meaning:"不要耽误、扰乱我正在做的事。无：不要；落：耽误、废弃或扰乱；吾事：我的耕作。伯成子高认为实际耕作比讨论权位和治术更值得专心。"},{id:"yi_yi_hu",term:"俋俋乎",pinyin:"yì yì hū",meaning:"专心勤勉、低头劳作的样子。俋俋：勤勉不懈、专注于工作的状态，读 yì yì。它描写伯成子高不再理会禹，继续一心耕田。"},{id:"geng_er_bu_gu",term:"耕而不顾",pinyin:"gēng ér bù gù",meaning:"继续耕作，连头也不回。顾：回头看、理会。伯成子高不再与禹交谈，以实际行动表明自己彻底放下诸侯权位，也不愿参与赏罚政治。"}],c=[{id:"taichu7_s1",label:"泰初有无……无有无名",sentences:[[{text:"泰初有无",glossary:"tai_chu_you_wu"},"，"],[{text:"无有无名",glossary:"wu_you_wu_ming"},"。"]]},{id:"taichu7_s2",label:"一之所起……有一而未形",sentences:[[{text:"一之所起",glossary:"yi_zhi_suo_qi"},"，",{text:"有一而未形",glossary:"you_yi_er_wei_xing"},"。"]]},{id:"taichu7_s3",label:"物得以生……谓之德",sentences:[[{text:"物得以生",glossary:"wu_de_yi_sheng"},{text:"谓之德",glossary:"wei_zhi_de"},"；"]]},{id:"taichu7_s4",label:"未形者有分……且然无间谓之命",sentences:[[{text:"未形者有分",glossary:"wei_xing_you_fen"},"，"],[{text:"且然无间",glossary:"qie_ran_wu_jian"},{text:"谓之命",glossary:"wei_zhi_ming"},"；"]]},{id:"taichu7_s5",label:"留动而生物……物成生理谓之形",sentences:[[{text:"留动而生物",glossary:"liu_dong_sheng_wu"},"，"],[{text:"物成生理",glossary:"wu_cheng_sheng_li"},{text:"谓之形",glossary:"wei_zhi_xing"},"；"]]},{id:"taichu7_s6",label:"形体保神……各有仪则谓之性",sentences:[[{text:"形体保神",glossary:"xing_ti_bao_shen"},"，"],[{text:"各有仪则",glossary:"ge_you_yi_ze"},{text:"谓之性",glossary:"wei_zhi_xing_nature"},"；"]]},{id:"taichu7_s7",label:"性修反德……德至同于初",sentences:[[{text:"性修反德",glossary:"xing_xiu_fan_de"},"，"],[{text:"德至同于初",glossary:"de_zhi_tong_yu_chu"},"。"]]},{id:"taichu7_s8",label:"同乃虚……虚乃大",sentences:[[{text:"同乃虚",glossary:"tong_nai_xu"},"，",{text:"虚乃大",glossary:"xu_nai_da"},"。"]]},{id:"taichu7_s9",label:"合喙鸣……与天地为合",sentences:[[{text:"合喙鸣",glossary:"he_hui_ming"},"。"],[{text:"喙鸣合",glossary:"hui_ming_he"},"，",{text:"与天地为合",glossary:"yu_tian_di_wei_he"},"。"]]},{id:"taichu7_s10",label:"其合缗缗……同乎大顺",sentences:[[{text:"其合缗缗",glossary:"qi_he_min_min"},"，",{text:"若愚若昏",glossary:"ruo_yu_ruo_hun"},"，"],[{text:"是谓玄德",glossary:"shi_wei_xuan_de"},"，",{text:"同乎大顺",glossary:"tong_hu_da_shun"},"。"]]}],w=[{id:"tai_chu_you_wu",term:"泰初有无",pinyin:"tài chū yǒu wú",meaning:"宇宙最初只有虚无。“泰初”即太初，指天地万物尚未形成的原始状态；“有无”是说当时存在的是无形无名的“无”。这里的“无”不是绝对空无，而是尚未分化、蕴含生成可能的本原。"},{id:"wu_you_wu_ming",term:"无有无名",pinyin:"wú yǒu wú míng",meaning:"既没有具体存在，也没有名称。“有”指已经形成的事物；“名”指对事物的称谓和概念分别。太初之无尚未产生有形万物，因而也无从命名。"},{id:"yi_zhi_suo_qi",term:"一之所起",pinyin:"yī zhī suǒ qǐ",meaning:"统一的元气或生成原则由此开始。“一”指万物分化以前浑然统一的本原，也可理解为由无向有转化的第一个阶段。"},{id:"you_yi_er_wei_xing",term:"有一而未形",pinyin:"yǒu yī ér wèi xíng",meaning:"已经有了浑一的生成本原，却尚未形成具体形体。此时宇宙已经由纯粹的“无”进入“一”，但万物的形状和界限还没有出现。"},{id:"wu_de_yi_sheng",term:"物得以生",pinyin:"wù dé yǐ shēng",meaning:"万物从这一生成力量中获得生命。得：获得；生：生成、成长。万物各自从大道取得生成和发展的内在力量。"},{id:"wei_zhi_de",term:"谓之德",pinyin:"wèi zhī dé",meaning:"把万物所得的生成力量称为“德”。德不是外在道德规范，而是大道落实在每一个具体事物之中，使其得以生成并成为自身的内在能力。"},{id:"wei_xing_you_fen",term:"未形者有分",pinyin:"wèi xíng zhě yǒu fèn",meaning:"尚未形成具体形体的本原，已经开始出现分化。分：分际、差别，读 fèn。此时阴阳、物类等差别已有发生的趋势，但尚未凝结成外在形体。"},{id:"qie_ran_wu_jian",term:"且然无间",pinyin:"qiě rán wú jiàn",meaning:"这种分化将要发生，并且连续不断、没有间隙。且然：将要如此或自然如此；无间：连续不绝，没有间断，间读 jiàn。此句文字古奥，古注对“且然”的解释略有差异。"},{id:"wei_zhi_ming",term:"谓之命",pinyin:"wèi zhī mìng",meaning:"这种无间断的自然分化过程称为“命”。命不是外在神灵预先规定的宿命，而是生命从本原中获得并自然展开的内在限度与过程。"},{id:"liu_dong_sheng_wu",term:"留动而生物",pinyin:"liú dòng ér shēng wù",meaning:"元气流动、留聚，从而产生具体事物。“留动”可理解为气的留聚与运动，也有版本、古注解释为流动不息。此句说明未形之气通过聚散运动生成万物。"},{id:"wu_cheng_sheng_li",term:"物成生理",pinyin:"wù chéng shēng lǐ",meaning:"事物形成以后，产生自身的纹理与组织。理：纹理、条理，即构成某物并使其成为该物的内在结构，不仅指抽象道理。"},{id:"wei_zhi_xing",term:"谓之形",pinyin:"wèi zhī xíng",meaning:"事物具有完整的组织和条理，便称为“形”。形是生成过程中的有形阶段，表示万物已经由未形的元气凝聚成具体生命和物体。"},{id:"xing_ti_bao_shen",term:"形体保神",pinyin:"xíng tǐ bǎo shén",meaning:"形体保存、承载着生命精神。保：守护、容纳；神：生命中神妙的活动能力。形体并非孤立躯壳，而是精神得以存在和活动的载体。"},{id:"ge_you_yi_ze",term:"各有仪则",pinyin:"gè yǒu yí zé",meaning:"各种事物各有自身的样式和法则。仪：形态、仪范；则：准则、规律。不同生命都有自然赋予的结构、功能和行为方式。"},{id:"wei_zhi_xing_nature",term:"谓之性",pinyin:"wèi zhī xìng",meaning:"事物形体与精神所具有的自然法则，称为“性”。性是每一事物成为其自身的内在本性，并非由外在教化和制度强加。"},{id:"xing_xiu_fan_de",term:"性修反德",pinyin:"xìng xiū fǎn dé",meaning:"本性得到修养，便能返回内在之德。修：修养、保全；反通“返”，返回。修性不是人为改造本性，而是去除欲望和智巧的损害，使本性复归其从道所得的生命力量。"},{id:"de_zhi_tong_yu_chu",term:"德至同于初",pinyin:"dé zhì tóng yú chū",meaning:"德性达到极致，便与最初的本原相同。初：太初未分的状态。个体生命若充分实现自身之德，便能由分化的个体返回与大道浑一的境界。"},{id:"tong_nai_xu",term:"同乃虚",pinyin:"tóng nǎi xū",meaning:"与太初相同，便进入虚静无分别的状态。同：与大道本原冥合；虚：不被成见、私欲和固定形态占据。"},{id:"xu_nai_da",term:"虚乃大",pinyin:"xū nǎi dà",meaning:"内心虚静，才能广大无边。虚不是空洞匮乏，而是不执著于一物一己；正因无所偏据，才能包容万物，所以称“大”。"},{id:"he_hui_ming",term:"合喙鸣",pinyin:"hé huì míng",meaning:"闭合口喙而自然发声。喙：鸟兽的嘴，也泛指人的口，读 huì。此句断句、字义历来存在分歧，可理解为虽不刻意立言，声音与作用仍会自然发出，表现静默与言说相合。"},{id:"hui_ming_he",term:"喙鸣合",pinyin:"huì míng hé",meaning:"口中发出的声音又归于浑然之合。可理解为有所言说却不离静默本根，声音虽出而没有个人成见与造作。此句与“合喙鸣”互相回环，强调动静不二。"},{id:"yu_tian_di_wei_he",term:"与天地为合",pinyin:"yǔ tiān dì wéi hé",meaning:"与天地的自然运行浑然相合。合不是人为强求一致，而是去除私意以后，言行自然顺应天地变化。"},{id:"qi_he_min_min",term:"其合缗缗",pinyin:"qí hé mín mín",meaning:"这种与天地相合的状态浑然幽昧、不见分别。缗缗：昏暗混同、绵密无迹的样子，读 mín mín。它形容德行不显露人为痕迹，并非精神昏乱。"},{id:"ruo_yu_ruo_hun",term:"若愚若昏",pinyin:"ruò yú ruò hūn",meaning:"看起来仿佛愚钝、昏昧。得道者不炫耀聪明，也不处处作出分别判断，因此在世俗眼中似乎愚昧；实际上是心与天地冥合。"},{id:"shi_wei_xuan_de",term:"是谓玄德",pinyin:"shì wèi xuán dé",meaning:"这就叫作幽深玄妙的德。玄德是不显露主观造作、不自居功名，却能与天地共同化育万物的内在德性。"},{id:"tong_hu_da_shun",term:"同乎大顺",pinyin:"tóng hū dà shùn",meaning:"与天地万物最根本的自然顺序相同。大顺：宇宙整体自然而然的运行与变化。得玄德者不以个人意志逆物，而是完全顺应大道的生成流行。"}],q=[{id:"laoji8_s1",label:"夫子问于老聃曰……然不然",sentences:[["夫子问于老聃曰：「有人",{text:"治道若相放",glossary:"zhi_dao_xiang_fang"},"，"],[{text:"可不可",glossary:"ke_bu_ke"},"，",{text:"然不然",glossary:"ran_bu_ran"},"。"]]},{id:"laoji8_s2",label:"辩者有言曰……若是则可谓圣人乎",sentences:[["辩者有言曰：『",{text:"离坚白",glossary:"li_jian_bai"},"，",{text:"若县寓",glossary:"ruo_xuan_yu"},"。』"],["若是则可谓圣人乎？」"]]},{id:"laoji8_s3",label:"老聃曰是胥易技系……劳形怵心者也",sentences:[["老聃曰：「",{text:"是胥易技系",glossary:"shi_xu_yi_ji_xi"},"，"],[{text:"劳形怵心者",glossary:"lao_xing_chu_xin"},"也。"]]},{id:"laoji8_s4",label:"执留之狗成思……猿狙之便自山林来",sentences:[[{text:"执留之狗成思",glossary:"zhi_liu_zhi_gou_cheng_si"},"，"],[{text:"猿狙之便",glossary:"yuan_ju_zhi_bian"},"自山林来。"]]},{id:"laoji8_s5",label:"丘予告若……而所不能言",sentences:[[{text:"丘",glossary:"qiu"},"，",{text:"予告若",glossary:"yu_gao_ru"},"，"],["而所不能闻与而所不能言："]]},{id:"laoji8_s6",label:"凡有首有趾无心无耳者众……皆存者尽无",sentences:[["凡",{text:"有首有趾",glossary:"you_shou_you_zhi"},"、",{text:"无心无耳者众",glossary:"wu_xin_wu_er_zhe_zhong"},"；"],["有形者与无形无状而皆存者尽无。"]]},{id:"laoji8_s7",label:"其动止也……此又非其所以也",sentences:[[{text:"其动止也",glossary:"qi_dong_zhi"},"，",{text:"其死生也",glossary:"qi_si_sheng"},"，"],[{text:"其废起也",glossary:"qi_fei_qi"},"，",{text:"此又",glossary:"ci_you"},{text:"非其所以也",glossary:"fei_qi_suo_yi"},"。"]]},{id:"laoji8_s8",label:"有治在人……是之谓入于天",sentences:[[{text:"有治在人",glossary:"you_zhi_zai_ren"},"。"],[{text:"忘乎物",glossary:"wang_hu_wu"},"，",{text:"忘乎天",glossary:"wang_hu_tian"},"，"],[{text:"其名为忘己",glossary:"qi_ming_wei_wang_ji"},"。忘己之人，是之谓入于天。」"]]},{id:"laoji8_s9",label:"将闾葂见季彻曰……请受教",sentences:[[{text:"将闾葂",glossary:"jiang_lv_mian"},"见",{text:"季彻",glossary:"ji_che"},"曰：「鲁君",{text:"谓葂",glossary:"wei_mian"},"也曰：『",{text:"请受教",glossary:"qing_shou_jiao"},"。』"]]},{id:"laoji8_s10",label:"辞不获命……请尝荐之",sentences:[[{text:"辞不获命",glossary:"ci_bu_huo_ming"},"。"],[{text:"既已告矣",glossary:"ji_yi_gao_yi"},"，",{text:"未知中否",glossary:"wei_zhi_zhong_fou"},"。"],[{text:"请尝荐之",glossary:"qing_chang_jian_zhi"},"。"]]},{id:"laoji8_s11",label:"吾谓鲁君曰……民孰敢不辑",sentences:[["吾谓鲁君曰：『",{text:"必服恭俭",glossary:"bi_fu_gong_jian"},"，"],[{text:"拔出",glossary:"ba_chu"},{text:"公忠之属",glossary:"gong_zhong_zhi_shu"},"而",{text:"无阿私",glossary:"wu_e_si"},"，"],[{text:"民孰敢不辑",glossary:"min_shu_gan_bu_ji"},"！』」"]]},{id:"laoji8_s12",label:"季彻局局然笑曰……则必不胜任矣",sentences:[["季彻",{text:"局局然",glossary:"ju_ju_ran"},"笑曰：「若夫子之言，于帝王之德，"],[{text:"犹",glossary:"you_ru"},{text:"螳螂之怒臂",glossary:"tang_lang_nu_bi"},{text:"以当车轶",glossary:"yi_dang_che_zhe"},"，则必不胜任矣！"]]},{id:"laoji8_s13",label:"且若是……将往投迹者众",sentences:[[{text:"且若是",glossary:"qie_ruo_shi"},"，则",{text:"其自为处危",glossary:"qi_zi_wei_chu_wei"},"，"],[{text:"其观台多物",glossary:"qi_guan_tai_duo_wu"},"，",{text:"将往投迹者众",glossary:"wang_tou_ji_zhe_zhong"},"。」"]]},{id:"laoji8_s14",label:"将闾葂覷觑然惊曰……愿先生之言其风也",sentences:[["将闾葂",{text:"覷觑然",glossary:"qu_qu_ran"},"惊曰：「葂也",{text:"汒若于",glossary:"mang_ruo_yu"},"夫子之所言矣！"],["虽然，愿先生",{text:"言其风也",glossary:"yan_qi_feng"},"。」"]]},{id:"laoji8_s15",label:"大圣之治天下也……成教易俗",sentences:[["季彻曰：「大圣之治天下也，摇荡民心，使之",{text:"成教易俗",glossary:"cheng_jiao_yi_su"},"，"]]},{id:"laoji8_s16",label:"举灭其贼心……若性之自为",sentences:[[{text:"举灭其贼心",glossary:"ju_mie_qi_zei_xin"},"而",{text:"皆进其独志",glossary:"jie_jin_qi_du_zhi"},"。"],[{text:"若性之自为",glossary:"ruo_xing_zhi_zi_wei"},"，而民不知",{text:"其所由然",glossary:"qi_suo_you_ran"},"。"]]},{id:"laoji8_s17",label:"若然者岂兄尧舜之教民……溟涬然弟之哉",sentences:[["若然者，岂兄尧、舜之教民，",{text:"溟涬",glossary:"ming_xing"},"然弟之哉？"]]},{id:"laoji8_s18",label:"欲同乎德……而心居矣",sentences:[[{text:"欲同乎德",glossary:"yu_tong_hu_de"},"而心居矣！」"]]}],j=[{id:"zhi_dao_xiang_fang",term:"治道若相放",pinyin:"zhì dào ruò xiāng fǎng",meaning:"谈论治理之道的人彼此仿效。放通「仿」，仿效。这里指各种辩者沿袭同类言论，以概念辩说处理道和政治，却没有真正通达大道。此句古本、断句存在不同解释。"},{id:"ke_bu_ke",term:"可不可",pinyin:"kě bù kě",meaning:"把不可说成可，或围绕可与不可进行辩论。前一个「可」可作动词，意为认可。这里批评辩者利用语言改变通常的是非判断。"},{id:"ran_bu_ran",term:"然不然",pinyin:"rán bù rán",meaning:"把不然说成当然、正确。前一个「然」可作动词，意为认为正确。它与「可不可」并列，表现名辩可以在概念上翻转是非。"},{id:"li_jian_bai",term:"离坚白",pinyin:"lí jiān bái",meaning:"把石头的坚硬与白色分离开来讨论。离：分离；坚、白：触觉与视觉所认识的不同属性。这是先秦名家「坚白论」的著名命题，文中用来代表脱离整体经验的概念辨析。"},{id:"ruo_xuan_yu",term:"若县寓",pinyin:"ruò xuán yù",meaning:"如同高悬在空中一样明显。县通「悬」；寓可理解为空间、寄托之处。辩者认为其坚白之说昭然明白，老聃却认为这种明辨仍只是技巧。此词古注有异。"},{id:"shi_xu_yi_ji_xi",term:"是胥易技系",pinyin:"shì xū yì jì xì",meaning:"这只是小吏、役人一类凭借技巧而受技巧束缚的行为。胥：小吏、役人；技系：被技术和智巧系缚。「易」的具体训释古注不一，整体是说名辩者以技巧相尚，反而受技巧役使。"},{id:"lao_xing_chu_xin",term:"劳形怵心者",pinyin:"láo xíng chù xīn zhě",meaning:"使形体劳累、内心惊惧不安的人。怵：恐惧、警惕，读 chù。执著于名辩和智巧，需要不断应付胜负是非，结果使身心都不得安宁。"},{id:"zhi_liu_zhi_gou_cheng_si",term:"执留之狗成思",pinyin:"zhí liú zhī gǒu chéng sī",meaning:"被拘系、扣留的狗会产生忧思。执留：拘执、系留；成思：产生忧虑。狗的焦躁思虑由拘束而生，比喻人的复杂机心常由束缚和处境造成，并非自然本性。"},{id:"yuan_ju_zhi_bian",term:"猿狙之便",pinyin:"yuán jū zhī biàn",meaning:"猿猴灵活敏捷的本领。猿狙：猿猴；便：便利、敏捷，读 biàn。猿猴的敏捷来自山林环境，说明具体技能有其特定成因，不等于通达普遍大道。"},{id:"qiu",term:"丘",pinyin:"qiū",meaning:"孔子的名。老聃直接称孔子为「丘」，具有长者对后学直呼其名的意味。"},{id:"yu_gao_ru",term:"予告若",pinyin:"yú gào rǔ",meaning:"我告诉你。予：我；若：你。老聃由批评名辩转而向孔子说明无法凭耳闻和语言完全表达的道。"},{id:"you_shou_you_zhi",term:"有首有趾",pinyin:"yǒu shǒu yǒu zhǐ",meaning:"具有头和足，即具有完整有形身体。这里以首、趾概括人的形体，与无形无状的道形成对照。"},{id:"wu_xin_wu_er_zhe_zhong",term:"无心无耳者众",pinyin:"wú xīn wú ěr zhě zhòng",meaning:"没有真正虚心体道、也不能听闻无声之道的人很多。此句文字和断句古奥，也可从字面理解为形体具备而心耳闭塞者众多。核心是指出，仅有感官形体并不等于能够闻道。"},{id:"qi_dong_zhi",term:"其动止也",pinyin:"qí dòng zhǐ yě",meaning:"万物的运动与静止。动止是万物变化的两种状态，但不是人为名辩或治术所能从根本上决定的。"},{id:"qi_si_sheng",term:"其死生也",pinyin:"qí sǐ shēng yě",meaning:"万物的死亡与生存。死生是自然变化的过程，并不由人的知识、语言和制度任意支配。"},{id:"qi_fei_qi",term:"其废起也",pinyin:"qí fèi qǐ yě",meaning:"万物的衰废与兴起。废起与动止、死生并列，说明一切事物都有自然而然的盛衰变化。"},{id:"ci_you",term:"此又",pinyin:"cǐ yòu",meaning:"这些又、这些也。此代指万物的动止、死生与废起，引出它们并不是道之所以为道的根本原因。"},{id:"fei_qi_suo_yi",term:"非其所以也",pinyin:"fēi qí suǒ yǐ yě",meaning:"这并不是造成其变化的根本所在。其：指万物；所以：之所以如此的原因。人能够观察变化，却不能把所见现象或人为治术当成自然生成的本原。"},{id:"you_zhi_zai_ren",term:"有治在人",pinyin:"yǒu zhì zài rén",meaning:"有意安排的治理存在于人的作为之中。治：人为治术。人可以建立制度处理事务，却不能凭此主宰万物的动止、死生和兴废。也有解释为治理的关键在于人的内在修养。"},{id:"wang_hu_wu",term:"忘乎物",pinyin:"wàng hū wù",meaning:"忘掉对外物的分别、占有和执著。不是否认万物存在，而是不再让财富、名位及各种对象支配内心。"},{id:"wang_hu_tian",term:"忘乎天",pinyin:"wàng hū tiān",meaning:"连对「天」这一概念的执著也忘掉。体道者不再把天与人、自然与自我对立起来，因而超越刻意追求合天的意识。"},{id:"qi_ming_wei_wang_ji",term:"其名为忘己",pinyin:"qí míng wéi wàng jǐ",meaning:"这种境界称为忘掉自我。忘己不是丧失生命和意识，而是消除以自我为中心的分别、功名和控制欲。忘己以后，人与自然不再相对，故称「入于天」。"},{id:"jiang_lv_mian",term:"将闾葂",pinyin:"jiāng lǘ miǎn",meaning:"庄子寓言中的人物，鲁国人，曾受鲁君请求而进献治国意见。他提出恭俭、公忠等政治德目，后来向季彻请教更高层次的帝王之道。"},{id:"ji_che",term:"季彻",pinyin:"jì chè",meaning:"庄子寓言中的得道者。季彻认为仅靠恭俭、公忠和任用贤能不足以承担帝王之治，真正的大圣之治应使人民在不知不觉中复归本性。"},{id:"wei_mian",term:"谓葂",pinyin:"wèi miǎn",meaning:"对将闾葂说。谓：告诉、对……说；葂：将闾葂自称其名。"},{id:"qing_shou_jiao",term:"请受教",pinyin:"qǐng shòu jiào",meaning:"请允许我接受你的教导，即请你赐教。鲁君主动向将闾葂询问治国之道。"},{id:"ci_bu_huo_ming",term:"辞不获命",pinyin:"cí bù huò mìng",meaning:"推辞却未获准许。辞：辞谢；不获命：不能得到同意。将闾葂本想拒绝鲁君的请求，但鲁君坚持求教，他只得作答。"},{id:"ji_yi_gao_yi",term:"既已告矣",pinyin:"jì yǐ gào yǐ",meaning:"已经把自己的意见告诉他了。告：告知，指将恭俭、公忠等治国主张告诉鲁君。"},{id:"wei_zhi_zhong_fou",term:"未知中否",pinyin:"wèi zhī zhòng fǒu",meaning:"不知道是否合乎正道。中：适当、切合，读 zhòng；否：不合、错误。将闾葂并不确信自己的建议正确，所以请季彻评判。"},{id:"qing_chang_jian_zhi",term:"请尝荐之",pinyin:"qǐng cháng jiàn zhī",meaning:"请允许我试着把这些话陈述给您。尝：试；荐：进献、陈述；之：代指对鲁君所说的治国意见。"},{id:"bi_fu_gong_jian",term:"必服恭俭",pinyin:"bì fú gōng jiǎn",meaning:"一定要切实践行恭敬与节俭。服：实行、服行。将闾葂认为君主以身作则、恭敬节俭，便能感化百姓。"},{id:"ba_chu",term:"拔出",pinyin:"bá chū",meaning:"选拔、提升。指从众人之中提拔公正忠诚的人，使其居于适当职位。"},{id:"gong_zhong_zhi_shu",term:"公忠之属",pinyin:"gōng zhōng zhī shǔ",meaning:"公正忠诚的一类人。属：类别。将闾葂主张任用公忠之士，以此建立政治秩序。"},{id:"wu_e_si",term:"无阿私",pinyin:"wú ē sī",meaning:"不要曲从偏私。阿：迎合、偏袒，读 ē；私：私情、私利。指选拔人才时不因私人关系而偏袒。"},{id:"min_shu_gan_bu_ji",term:"民孰敢不辑",pinyin:"mín shú gǎn bù jí",meaning:"百姓谁敢不和顺归服？孰：谁；辑：和睦、安定、归服。将闾葂认为君主恭俭并任用公忠者，人民自然会服从。"},{id:"ju_ju_ran",term:"局局然",pinyin:"jú jú rán",meaning:"俯身弯腰而笑或局促发笑的样子。季彻听到将闾葂以恭俭、公忠治理天下，认为这种见解狭小不足，因而发笑。具体形态古注有异。"},{id:"you_ru",term:"犹",pinyin:"yóu",meaning:"如同、好像。此处引出螳螂举臂阻挡车轮的比喻。"},{id:"tang_lang_nu_bi",term:"螳螂之怒臂",pinyin:"táng láng zhī nù bì",meaning:"螳螂奋力举起前臂。怒：奋起、用力，不仅指愤怒。比喻能力有限却试图承担远远超出自身力量的事情。"},{id:"yi_dang_che_zhe",term:"以当车轶",pinyin:"yǐ dāng chē zhé",meaning:"用来阻挡车轮或车辙中的车辆。当：阻挡，读 dāng；轶在此与车轮、车行之迹相关。比喻用有限的人为德目阻挡或承担浩大的天下变化，必然不能胜任。"},{id:"qie_ruo_shi",term:"且若是",pinyin:"qiě ruò shì",meaning:"而且如果像这样做。是：指刻意实行恭俭、选拔公忠并以此招致人民归服。季彻接着说明这种有迹政治带来的危险。"},{id:"qi_zi_wei_chu_wei",term:"其自为处危",pinyin:"qí zì wéi chǔ wēi",meaning:"他将使自己处于危险境地。刻意树立德行、招聚人才和民众，会使君主成为利益与权力争夺的中心，从而自处于危地。"},{id:"qi_guan_tai_duo_wu",term:"其观台多物",pinyin:"qí guān tái duō wù",meaning:"他的宫观台榭将聚集许多财物。观台：宫殿、楼台，观读 guàn；多物：财货、人才或可供观赏利用之物众多。政治刻意彰显德行和功业，容易形成聚集外物的权力中心。"},{id:"wang_tou_ji_zhe_zhong",term:"将往投迹者众",pinyin:"jiāng wǎng tóu jì zhě zhòng",meaning:"将会有很多人前往投奔。投迹：投入其门下、前往依附。君主刻意招贤纳众，会吸引追逐名利者聚集，并不等于人民真正复归自然。"},{id:"qu_qu_ran",term:"覷觑然",pinyin:"qù qù rán",meaning:"惊惧而目光不定的样子。覷觑：惊视、惶惑地察看，读 qù qù。将闾葂听到自己的主张被比作螳臂当车，因而震惊失措。此词也有异体、异读。"},{id:"mang_ruo_yu",term:"汒若于",pinyin:"máng ruò yú",meaning:"对于……感到茫然不解。汒若：茫然、迷惘的样子，汒读 máng。将闾葂承认自己听不懂季彻所说的帝王之德。"},{id:"yan_qi_feng",term:"言其风也",pinyin:"yán qí fēng yě",meaning:"说一说其中的大概、风旨。风：风貌、旨趣、大略。将闾葂请求季彻不必详尽说明，只要略述大圣治理天下的根本方向。"},{id:"cheng_jiao_yi_su",term:"成教易俗",pinyin:"chéng jiào yì sú",meaning:"成就自然教化，改变旧有习俗。易：改变，读 yì。大圣不是靠外在命令强制人民，而是涤荡人心，使教化和风俗从内部自然转变。"},{id:"ju_mie_qi_zei_xin",term:"举灭其贼心",pinyin:"jǔ miè qí zéi xīn",meaning:"使所有人都消除伤害本性的心。举：全、皆；贼心：损害自身和他人的机诈、贪争之心。大圣之治不是惩罚已有罪行，而是使产生争害的机心自然消退。"},{id:"jie_jin_qi_du_zhi",term:"皆进其独志",pinyin:"jiē jìn qí dú zhì",meaning:"使每个人都能发展自己独特的自然志性。进：伸展、实现；独志：个体独有的本性与志向。大圣之治不是把所有人塑造成同一形态，而是让各人各遂其性。"},{id:"ruo_xing_zhi_zi_wei",term:"若性之自为",pinyin:"ruò xìng zhī zì wéi",meaning:"如同本性自行发挥作用。若：如同；性：自然本性；自为：自行成就。人民的改变看似完全出于自身，而看不见统治者刻意施教的痕迹。"},{id:"qi_suo_you_ran",term:"其所由然",pinyin:"qí suǒ yóu rán",meaning:"事情之所以如此的来源和原因。人民自然成教易俗，却不知道是谁使其如此，说明大圣的教化无形无迹、不以功业自居。"},{id:"ming_xing",term:"溟涬",pinyin:"míng xìng",meaning:"元气浑然未分、幽冥无迹的状态。这里象征自然无为、没有名目和人为教化痕迹的境界。句中「兄尧舜之教民，溟涬然弟之」可理解为尊崇尧舜有迹的教化，却轻视浑然无迹的自然之治。"},{id:"yu_tong_hu_de",term:"欲同乎德",pinyin:"yù tóng hū dé",meaning:"希望人民共同归于自然德性。这里的「同」不是消灭个体差异，而是使人人都不失其从道所得的本性；因此既能同乎德，又能各进其独志。"}],f=[{id:"zhangren9_s1",label:"子贡南游于楚……见一丈人方将为圃畦",sentences:[[{text:"子贡",glossary:"zi_gong"},"南游于楚，反于晋，过",{text:"汉阴",glossary:"han_yin"},"，"],["见一丈人",{text:"方将为圃畦",glossary:"fang_jiang_wei_pu_qi"},"。"]]},{id:"zhangren9_s2",label:"凿隧而入井……用力甚多而见功寡",sentences:[[{text:"凿隧而入井",glossary:"zao_sui_ru_jing"},"，",{text:"抱瓮而出灌",glossary:"bao_weng_chu_guan"},"，"],[{text:"搰然",glossary:"hu_ran"},"用力甚多而",{text:"见功寡",glossary:"jian_gong_gua"},"。"]]},{id:"zhangren9_s3",label:"子贡曰有械于此……夫子不欲乎",sentences:[["子贡曰：「有械于此，一日浸百畦，"],["用力甚寡而见功多，夫子不欲乎？」"]]},{id:"zhangren9_s4",label:"为圃者仰而视之曰奈何……其名为槔",sentences:[["为圃者仰而视之曰：「奈何？」"],["曰：「",{text:"凿木为机",glossary:"zao_mu_wei_ji"},"，",{text:"后重前轻",glossary:"hou_zhong_qian_qing"},"，"],[{text:"挈水若抽",glossary:"qie_shui_ruo_chou"},"，",{text:"数如泆汤",glossary:"shu_ru_yi_tang"},"，",{text:"其名为槔",glossary:"qi_ming_wei_gao"},"。」"]]},{id:"zhangren9_s5",label:"为圃者忿然作色而笑曰……有机事者必有机心",sentences:[["为圃者",{text:"忿然作色",glossary:"fen_ran_zuo_se"},"而笑曰：「吾闻之吾师，有机械者必有",{text:"机事",glossary:"ji_shi"},"，"],["有机事者必有",{text:"机心",glossary:"ji_xin"},"。"]]},{id:"zhangren9_s6",label:"机心存于胸中……道之所不载也",sentences:[["机心存于胸中则",{text:"纯白不备",glossary:"chun_bai_bu_bei"},"。"],["纯白不备则",{text:"神生不定",glossary:"shen_sheng_bu_ding"},"，神生不定者，道之所",{text:"不载",glossary:"bu_zai"},"也。"]]},{id:"zhangren9_s7",label:"吾非不知……俯而不对",sentences:[["吾非不知，",{text:"羞而不为",glossary:"xiu_er_bu_wei"},"也。」"],["子贡",{text:"瞒然惭",glossary:"man_ran_can"},"，",{text:"俯而不对",glossary:"fu_er_bu_dui"},"。"]]},{id:"zhangren9_s8",label:"有间为圃者曰……孔丘之徒也",sentences:[["有间，为圃者曰：「子奚为者邪？」"],["曰：「孔丘之徒也。」"]]},{id:"zhangren9_s9",label:"子非夫博学以拟圣……以卖名声于天下者乎",sentences:[["为圃者曰：「子非夫",{text:"博学以拟圣",glossary:"bo_xue_yi_ni_sheng"},"，",{text:"於于以盖众",glossary:"yu_yu_yi_gai_zhong"},"，"],[{text:"独弦哀歌",glossary:"du_xian_ai_ge"},{text:"以卖名声于",glossary:"yi_mai_ming_sheng"},"天下者乎？"]]},{id:"zhangren9_s10",label:"汝方将忘汝神气……无乏吾事",sentences:[["汝方将忘汝神气，",{text:"堕汝形骸",glossary:"hui_ru_xing_hai"},"，",{text:"而庶几乎",glossary:"er_shu_ji_hu"},"！"],[{text:"而身之不能治",glossary:"er_shen_bu_neng_zhi"},"，",{text:"而何暇",glossary:"er_he_xia"},{text:"治天下乎",glossary:"zhi_tian_xia_hu"},"！"],[{text:"子往矣",glossary:"zi_wang_yi"},"，",{text:"无乏吾事",glossary:"wu_fa_wu_shi"},"。」"]]},{id:"zhangren9_s11",label:"子贡卑陬失色……行三十里而后愈",sentences:[["子贡",{text:"卑陬失色",glossary:"bei_zou_shi_se"},"，",{text:"顼顼然",glossary:"xu_xu_ran"},{text:"不自得",glossary:"bu_zi_de"},"，"],["行三十里",{text:"而后愈",glossary:"er_hou_yu"},"。"]]},{id:"zhangren9_s12",label:"其弟子曰向之人何为者邪……终日不自反邪",sentences:[["其弟子曰：「向之人何为者邪？"],["夫子何故见之变容失色，",{text:"终日不自反",glossary:"zhong_ri_bu_zi_fan"},"邪？」"]]},{id:"zhangren9_s13",label:"始吾以为天下一人耳……不知复有夫人也",sentences:[["曰：「始吾以为",{text:"天下一人耳",glossary:"tian_xia_yi_ren_er"},"，"],["不知",{text:"复有夫人也",glossary:"fu_you_fu_ren"},"。"]]},{id:"zhangren9_s14",label:"吾闻之夫子事求可……今徒不然",sentences:[["吾闻之夫子：",{text:"事求可",glossary:"shi_qiu_ke"},"，",{text:"功求成",glossary:"gong_qiu_cheng"},"，"],[{text:"用力少",glossary:"yong_li_shao"},"，",{text:"见功多者",glossary:"jian_gong_duo_zhe"},"，",{text:"圣人之道",glossary:"sheng_ren_zhi_dao"},"。"],[{text:"今徒不然",glossary:"jin_tu_bu_ran"},"。"]]},{id:"zhangren9_s15",label:"执道者德全……神全者圣人之道也",sentences:[[{text:"执道者德全",glossary:"zhi_dao_zhe_de_quan"},"，",{text:"德全者形全",glossary:"de_quan_zhe_xing_quan"},"，"],[{text:"形全者神全",glossary:"xing_quan_zhe_shen_quan"},"。"],[{text:"神全者",glossary:"shen_quan_zhe"},"，圣人之道也。"]]},{id:"zhangren9_s16",label:"托生与民并行……功利机巧必忘夫人之心",sentences:[[{text:"托生",glossary:"tuo_sheng"},{text:"与民并行",glossary:"yu_min_bing_xing"},"而",{text:"不知其所之",glossary:"bu_zhi_qi_suo_zhi"},"，"],[{text:"汒乎淳备哉",glossary:"mang_hu_chun_bei"},"！"],[{text:"功利机巧",glossary:"gong_li_ji_qiao"},"必",{text:"忘夫人之心",glossary:"wang_fu_ren_zhi_xin"},"。"]]},{id:"zhangren9_s17",label:"若夫人者非其志不之……傥然不受",sentences:[["若夫人者，",{text:"非其志不之",glossary:"fei_qi_zhi_bu_zhi"},"，",{text:"非其心不为",glossary:"fei_qi_xin_bu_wei"},"。"],["虽以天下",{text:"誉之",glossary:"yu_zhi"},"，",{text:"得其所谓",glossary:"de_qi_suo_wei"},"，",{text:"謷然不顾",glossary:"ao_ran_bu_gu"},"；"],["以天下非之，失其所谓，",{text:"傥然不受",glossary:"tang_ran_bu_shou"},"。"]]},{id:"zhangren9_s18",label:"天下之非誉无益损焉……我之谓风波之民",sentences:[["天下之",{text:"非誉",glossary:"fei_yu"},"无益损焉，是谓全德之人哉！"],["我之谓",{text:"风波之民",glossary:"feng_bo_zhi_min"},"。」"]]},{id:"zhangren9_s19",label:"反于鲁以告孔子……何足以识之哉",sentences:[["反于鲁，以告孔子。孔子曰：「",{text:"彼",glossary:"bi"},{text:"假修",glossary:"jia_xiu"},{text:"浑沌氏之术",glossary:"hun_dun_shi_zhi_shu"},"者也。"],[{text:"识其一",glossary:"shi_qi_yi"},"，",{text:"不识其二",glossary:"bu_shi_qi_er"},"；",{text:"治其内",glossary:"zhi_qi_nei"},"而",{text:"不治其外",glossary:"bu_zhi_qi_wai"},"。"],["夫",{text:"明白入素",glossary:"ming_bai_ru_su"},"，",{text:"无为复朴",glossary:"wu_wei_fu_pu"},"，",{text:"体性抱神",glossary:"ti_xing_bao_shen"},"，以游世俗之间者，"],[{text:"汝将固惊邪",glossary:"ru_jiang_gu_jing"},"？"],["且浑沌氏之术，予与汝",{text:"何足以识之",glossary:"he_zu_yi_shi_zhi"},"哉！」"]]}],k=[{id:"zi_gong",term:"子贡",pinyin:"zǐ gòng",meaning:"孔子的弟子，姓端木，名赐，字子贡。以善于言辞、通晓事务著称。本则寓言借他崇尚效率的观念，与灌园丈人的朴素无机心形成对照。"},{id:"han_yin",term:"汉阴",pinyin:"hàn yīn",meaning:"汉水南岸。古代以山北、水南为阴。子贡从楚返回晋国，途经汉水南岸时遇见灌园丈人。"},{id:"fang_jiang_wei_pu_qi",term:"方将为圃畦",pinyin:"fāng jiāng wéi pǔ qí",meaning:"正要整理菜园中的田畦。方将：正在、正要；圃：菜园；畦：分割整齐的田垄。为在此是修治、制作的意思。"},{id:"zao_sui_ru_jing",term:"凿隧而入井",pinyin:"záo suì ér rù jǐng",meaning:"挖出通道走入井中。隧：通往井底的斜道。丈人不是用提水机械，而是沿通道进入井中取水。"},{id:"bao_weng_chu_guan",term:"抱瓮而出灌",pinyin:"bào wèng ér chū guàn",meaning:"抱着盛水的陶瓮出来灌溉。瓮：腹大口小的陶器。此法耗费体力且效率低，却没有使用机械。"},{id:"hu_ran",term:"搰然",pinyin:"hú rán",meaning:"用力劳作、疲劳勤苦的样子。搰：掘土或辛勤用力，读 hú。这里描写丈人抱瓮灌园时十分费力。"},{id:"jian_gong_gua",term:"见功寡",pinyin:"jiàn gōng guǎ",meaning:"显现出来的功效很少。见：显现；功：工作成效；寡：少。与后文的“用力少而见功多”形成对比。"},{id:"zao_mu_wei_ji",term:"凿木为机",pinyin:"záo mù wéi jī",meaning:"加工木材制成提水机械。机：具有机关构造的器械。子贡所介绍的是利用杠杆原理提水的桔槔。"},{id:"hou_zhong_qian_qing",term:"后重前轻",pinyin:"hòu zhòng qián qīng",meaning:"机械后端较重、前端较轻。借助后端重物的杠杆作用，可以轻易提起前端的水桶。"},{id:"qie_shui_ruo_chou",term:"挈水若抽",pinyin:"qiè shuǐ ruò chōu",meaning:"提水如同抽取一样轻快。挈：提起，读 qiè；抽：迅速抽引。形容桔槔取水省力。"},{id:"shu_ru_yi_tang",term:"数如泆汤",pinyin:"shuò rú yì tāng",meaning:"提水迅速频繁，如沸水奔涌。数：频繁、迅速，读 shuò；泆：水满溢出，读 yì；汤：热水、沸水。形容机械灌溉速度很快。"},{id:"qi_ming_wei_gao",term:"其名为槔",pinyin:"qí míng wéi gāo",meaning:"这种机械名叫槔，即桔槔。槔：古代利用杠杆原理提水的工具，通常一端系水桶，一端装配重物。"},{id:"fen_ran_zuo_se",term:"忿然作色",pinyin:"fèn rán zuò sè",meaning:"愤怒地改变脸色。忿然：生气的样子；作色：脸色因情绪而发生变化。丈人认为子贡推介机械会引入机心。"},{id:"ji_shi",term:"机事",pinyin:"jī shì",meaning:"使用机械、讲求机巧的事务。这里不仅指操作器械，也指依靠技巧计算、追求高效率的行事方式。"},{id:"ji_xin",term:"机心",pinyin:"jī xīn",meaning:"机巧、算计和追逐功利的心。丈人不是说使用工具必然邪恶，而是警惕人因依赖机械与效率而产生控制万物、计较得失的心理。"},{id:"chun_bai_bu_bei",term:"纯白不备",pinyin:"chún bái bù bèi",meaning:"纯朴洁白的本性不再完整。纯白：纯真无杂的心性；备：完备。机心一旦存在，人的自然淳朴便会受到损害。"},{id:"shen_sheng_bu_ding",term:"神生不定",pinyin:"shén shēng bù dìng",meaning:"精神活动不能保持安定。神生：精神、心神的活动；不定：躁动不安。人若不断盘算效率和利害，心神便难以虚静。"},{id:"bu_zai",term:"不载",pinyin:"bù zài",meaning:"不承载、不容纳。心神动荡者不能以道为其根本，也不能为大道所承载。载：承受、容纳，读 zài。"},{id:"xiu_er_bu_wei",term:"羞而不为",pinyin:"xiū ér bù wéi",meaning:"以使用这种机械为羞，所以不肯采用。丈人并非不知道桔槔，而是担心使用机械会引发机事与机心。"},{id:"man_ran_can",term:"瞒然惭",pinyin:"mán rán cán",meaning:"满面羞惭、神情惭愧的样子。瞒然：惭愧失意的神态。子贡发现自己的效率观受到更根本的质疑，因此无言以对。"},{id:"fu_er_bu_dui",term:"俯而不对",pinyin:"fǔ ér bù duì",meaning:"低下头而没有回答。俯首表示子贡羞愧，也说明他暂时无法回应丈人关于机心的批评。"},{id:"bo_xue_yi_ni_sheng",term:"博学以拟圣",pinyin:"bó xué yǐ nǐ shèng",meaning:"凭借广博学问仿效、比拟圣人。拟：模拟、比拟。丈人讥讽孔子以知识和礼法营造圣人形象，却未必真正忘己体道。"},{id:"yu_yu_yi_gai_zhong",term:"於于以盖众",pinyin:"yú yú yǐ gài zhòng",meaning:"自得张扬地想要压倒众人。於于：自负、夸耀的样子，读 yú yú；盖众：超过、压倒众人。此词古注存在不同解释。"},{id:"du_xian_ai_ge",term:"独弦哀歌",pinyin:"dú xián āi gē",meaning:"独自鼓弦，吟唱哀世之歌。比喻孔子以礼乐和忧世言论表现自己的与众不同。也有古注将“弦歌”理解为孔门以音乐施行教化。"},{id:"yi_mai_ming_sheng",term:"以卖名声于",pinyin:"yǐ mài míng shēng yú",meaning:"借此在……之中售卖、宣扬名声。卖：炫示、求取。丈人认为孔子周游讲学仍有向天下求名的嫌疑。"},{id:"hui_ru_xing_hai",term:"堕汝形骸",pinyin:"huī rǔ xíng hái",meaning:"忘掉你对形体的执著。堕通“隳”，读 huī，意为毁弃、消解；形骸：人的身体形貌。不是伤害身体，而是不再以外在身份、仪容和功名自限。"},{id:"er_shu_ji_hu",term:"而庶几乎",pinyin:"ér shù jī hū",meaning:"那样才差不多接近大道。庶几：或许可以、接近于。丈人认为子贡若能忘掉精神上的自我标榜和形体身份，才可能接近得道。"},{id:"er_shen_bu_neng_zhi",term:"身之不能治",pinyin:"ér shēn zhī bù néng zhì",meaning:"连自己的身心都不能修治。此处“而”通“尔”，即你；治身指安顿、保全自己的形神和本性。"},{id:"er_he_xia",term:"而何暇",pinyin:"ér hé xiá",meaning:"你哪里还有空闲。“而”通“尔”，指你；何暇：哪里有余暇。丈人反问子贡，连自身尚未安顿，怎能治理天下。"},{id:"zhi_tian_xia_hu",term:"治天下乎",pinyin:"zhì tiān xià hū",meaning:"去治理天下呢？丈人认为治天下必须以治身为根本；不能保全自身本性者，没有资格以人为方法干预天下。"},{id:"zi_wang_yi",term:"子往矣",pinyin:"zǐ wǎng yǐ",meaning:"你离开吧。子：对子贡的称呼；往：离去；矣：表示命令或催促。丈人不愿再与子贡谈论。"},{id:"wu_fa_wu_shi",term:"无乏吾事",pinyin:"wú fá wú shì",meaning:"不要耽误我的事情。无：不要；乏：废弃、妨碍；吾事：丈人的灌园工作。与“无落吾事”意思相近。"},{id:"bei_zou_shi_se",term:"卑陬失色",pinyin:"bēi zōu shī sè",meaning:"惭愧局促，脸色大变。卑陬：低下局促、不安的样子；失色：因震惊或惭愧而改变脸色。"},{id:"xu_xu_ran",term:"顼顼然",pinyin:"xù xù rán",meaning:"怅然失神、惶惑不安的样子。子贡受到丈人的强烈冲击，精神恍惚，不能恢复平常状态。"},{id:"bu_zi_de",term:"不自得",pinyin:"bù zì dé",meaning:"心中不自在，不能恢复安适自如。子贡原有的圣人观受到动摇，因此长时间惭愧失意。"},{id:"er_hou_yu",term:"而后愈",pinyin:"ér hòu yù",meaning:"然后才恢复正常。愈：痊愈、平复。子贡走了三十里，震惊惭愧的情绪才逐渐消退。"},{id:"zhong_ri_bu_zi_fan",term:"终日不自反",pinyin:"zhōng rì bù zì fǎn",meaning:"整日不能恢复原来的神态。反：返回、恢复。弟子不明白丈人是什么人，竟使子贡如此长久地失魂落魄。"},{id:"tian_xia_yi_ren_er",term:"天下一人耳",pinyin:"tiān xià yī rén ěr",meaning:"天下只有一个真正的圣人罢了。“一人”指孔子。子贡原以为孔子是天下唯一通达圣道的人。"},{id:"fu_you_fu_ren",term:"复有夫人也",pinyin:"fù yǒu fū rén yě",meaning:"竟然还有这样一个人。夫人：那个人，指灌园丈人，不是现代汉语中的妻子。子贡把丈人视为孔子之外的另一位得道者。"},{id:"shi_qiu_ke",term:"事求可",pinyin:"shì qiú kě",meaning:"做事追求妥善可行。可：合宜、可行。子贡过去认为圣人处理事务应讲求现实效果。"},{id:"gong_qiu_cheng",term:"功求成",pinyin:"gōng qiú chéng",meaning:"功业追求完成、成功。子贡所理解的圣人之道重视做成事情并取得实际功效。"},{id:"yong_li_shao",term:"用力少",pinyin:"yòng lì shǎo",meaning:"耗费的力量较少。与“见功多”结合，构成子贡原先崇尚的效率原则。"},{id:"jian_gong_duo_zhe",term:"见功多者",pinyin:"jiàn gōng duō zhě",meaning:"取得或显现的功效很多。见：显现。子贡原以为以较少力量取得较大成果便符合圣人之道。"},{id:"sheng_ren_zhi_dao",term:"圣人之道",pinyin:"shèng rén zhī dào",meaning:"圣人的行事原则。子贡原来把成功和效率视为圣人之道，遇见丈人后，开始把德、形、神的完整视为更深层的圣人之道。"},{id:"jin_tu_bu_ran",term:"今徒不然",pinyin:"jīn tú bù rán",meaning:"如今这个人却不是这样。徒：人、徒众，此处指灌园丈人。丈人明知机械省力，却主动拒绝效率原则。"},{id:"zhi_dao_zhe_de_quan",term:"执道者德全",pinyin:"zhí dào zhě dé quán",meaning:"持守大道的人，其内在之德完整。执道：持守、合于道；德全：从道所得的自然本性未受机心损害。"},{id:"de_quan_zhe_xing_quan",term:"德全者形全",pinyin:"dé quán zhě xíng quán",meaning:"内在德性完整的人，形体也能得到保全。形全不仅指身体无损，还指人的生命形态不受外在功名和人为造作扭曲。"},{id:"xing_quan_zhe_shen_quan",term:"形全者神全",pinyin:"xíng quán zhě shén quán",meaning:"形体生命得到保全的人，其精神也能保持完整安定。形与神相互依存，形体不被过度役使，心神才不会散乱。"},{id:"shen_quan_zhe",term:"神全者",pinyin:"shén quán zhě",meaning:"精神完整无损的人。神全表现为心神虚静，不受功利、名誉、毁谤和机巧扰动；子贡认为这才真正合于圣人之道。"},{id:"tuo_sheng",term:"托生",pinyin:"tuō shēng",meaning:"寄托生命形体而生存在世间。托：寄托。丈人虽生活于人世，却不执著于个人身份和功名。"},{id:"yu_min_bing_xing",term:"与民并行",pinyin:"yǔ mín bìng xíng",meaning:"与普通百姓一同生活行走。丈人外表只是平常的灌园者，不以得道者身份超越或炫耀于众人。"},{id:"bu_zhi_qi_suo_zhi",term:"不知其所之",pinyin:"bù zhī qí suǒ zhī",meaning:"不显露自己将要达到的目的或行迹。之：前往。丈人随众而行，不预设功名目标，也使旁人无法看出其精神归宿。"},{id:"mang_hu_chun_bei",term:"汒乎淳备哉",pinyin:"máng hū chún bèi zāi",meaning:"多么浑茫而淳朴完备啊。汒乎：浑然无边、难以测知；淳备：纯朴完整。子贡赞叹丈人的心性浑然无杂。"},{id:"gong_li_ji_qiao",term:"功利机巧",pinyin:"gōng lì jī qiǎo",meaning:"追求功效利益的机巧之术。包括计算投入产出、利用技巧控制事物及借功业谋求声名。"},{id:"wang_fu_ren_zhi_xin",term:"忘夫人之心",pinyin:"wàng fū rén zhī xīn",meaning:"必定不会留存在那个人的心中。忘：不存、不放在心上；夫人：丈人。丈人完全忘却功利机巧，不以效率得失扰乱本心。"},{id:"fei_qi_zhi_bu_zhi",term:"非其志不之",pinyin:"fēi qí zhì bù zhī",meaning:"不符合自己志向的地方便不前往。之：到、前往。丈人的行动只服从内在真实志向，不随外在诱惑转移。"},{id:"fei_qi_xin_bu_wei",term:"非其心不为",pinyin:"fēi qí xīn bù wéi",meaning:"不符合自己本心的事情便不去做。他不因效率、利益、称赞或压力而违背本心。"},{id:"yu_zhi",term:"誉之",pinyin:"yù zhī",meaning:"称赞他。誉：赞美；之：指丈人。即使全天下都称赞，丈人也不会因此改变自己的原则。"},{id:"de_qi_suo_wei",term:"得其所谓",pinyin:"dé qí suǒ wèi",meaning:"得到世人所赞许、所说的名声或成就。所谓：世俗称许的东西。即使获得名誉，丈人也不回头关注。"},{id:"ao_ran_bu_gu",term:"謷然不顾",pinyin:"áo rán bù gù",meaning:"高远超脱，毫不回头理会。謷然：超然高放、不受约束的样子；顾：回头看、在意。这里不是傲慢，而是不受赞誉诱惑。"},{id:"tang_ran_bu_shou",term:"傥然不受",pinyin:"tǎng rán bù shòu",meaning:"旷达自在，不接受毁谤的影响。傥然：无所系著、洒脱的样子；不受：不把非议纳入内心。"},{id:"fei_yu",term:"非誉",pinyin:"fēi yù",meaning:"非议与赞誉。非：责难；誉：称赞。全德之人不因外界毁誉而增加或损害自己的内在德性。"},{id:"feng_bo_zhi_min",term:"风波之民",pinyin:"fēng bō zhī mín",meaning:"内心像风波一样动荡的普通人。子贡以此自称，承认自己仍受到功利、名声、毁誉和外界评价的扰动，尚未达到全德。"},{id:"bi",term:"彼",pinyin:"bǐ",meaning:"那个人，指汉阴灌园丈人。孔子听完子贡的叙述后，对丈人的境界作进一步评价。"},{id:"jia_xiu",term:"假修",pinyin:"jiǎ xiū",meaning:"借助并修习，也可理解为暂时修行或托迹于某种方法。孔子认为丈人修习浑沌氏之术，已懂得保全内在本真，但还没有达到内外皆通的圆融境界。"},{id:"hun_dun_shi_zhi_shu",term:"浑沌氏之术",pinyin:"hún dùn shì zhī shù",meaning:"使心性复归浑然未分状态的方法。浑沌氏是寓言化的上古人物，象征无知无欲、无分别、无机心的原始自然境界。"},{id:"shi_qi_yi",term:"识其一",pinyin:"shí qí yī",meaning:"懂得其中一个方面。孔子认为丈人懂得修治内在、拒绝机心和保全纯白，这是其所识的“一”。"},{id:"bu_shi_qi_er",term:"不识其二",pinyin:"bù shí qí èr",meaning:"不懂得另一个方面。丈人不懂得真正得道者也能外在随顺世俗、使用器物而不被器物支配，在有为中保持无为。"},{id:"zhi_qi_nei",term:"治其内",pinyin:"zhì qí nèi",meaning:"修治、保全自己的内在心性。丈人拒绝机械和机心，以保存精神纯白，属于重视内在修养。"},{id:"bu_zhi_qi_wai",term:"不治其外",pinyin:"bù zhì qí wài",meaning:"不能妥善处理外在事物。丈人必须排斥机械才能保全内心，说明他还不能在使用外物时不受外物束缚。"},{id:"ming_bai_ru_su",term:"明白入素",pinyin:"míng bái rù sù",meaning:"内心明澈而归入纯素本真。明白：清明通达；素：未经文饰的本色。真正得道者既有清明智慧，又不失质朴本性。"},{id:"wu_wei_fu_pu",term:"无为复朴",pinyin:"wú wéi fù pǔ",meaning:"以不刻意造作的方式返回朴素本性。无为不是完全不行动，而是不以机心、私欲和功名意识强行作为。"},{id:"ti_xing_bao_shen",term:"体性抱神",pinyin:"tǐ xìng bào shén",meaning:"体认并保全本性，持守完整精神。体性：体现、安于自然本性；抱神：凝聚、守护精神，不使其受外物扰乱。"},{id:"ru_jiang_gu_jing",term:"汝将固惊邪",pinyin:"rǔ jiāng gù jīng yé",meaning:"你本来就会因此感到惊异吗？固：本来、当然。孔子指出，如果真有人能够内外圆融地游于世俗，其境界更高，子贡自然会更加惊讶。"},{id:"he_zu_yi_shi_zhi",term:"何足以识之",pinyin:"hé zú yǐ shí zhī",meaning:"哪里足以真正认识它呢？之：指浑沌氏之术。孔子以谦辞说明，浑沌之道幽深难知，自己和子贡都不能轻易断定其全部境界。"}],P=[{id:"zhunmang10_s1",label:"谆芒将东之大壑……适遇苑风于东海之滨",sentences:[[{text:"谆芒",glossary:"zhun_mang"},"将东之",{text:"大壑",glossary:"da_he"},"，"],[{text:"适遇",glossary:"shi_yu"},{text:"苑风",glossary:"yuan_feng"},"于东海之滨。"]]},{id:"zhunmang10_s2",label:"苑风曰子将奚之……将之大壑",sentences:[["苑风曰：「子将奚之？」"],["曰：「将之大壑。」"]]},{id:"zhunmang10_s3",label:"夫大壑之为物也……吾将游焉",sentences:[["曰：「奚为焉？」"],["曰：「夫大壑",{text:"之为物",glossary:"zhi_wei_wu"},"也，",{text:"注焉而不满",glossary:"zhu_yan_bu_man"},"，"],[{text:"酌焉而不竭",glossary:"zhuo_yan_bu_jie"},"。吾将游焉！」"]]},{id:"zhunmang10_s4",label:"夫子无意于横目之民乎……愿闻圣治",sentences:[["苑风曰：「夫子",{text:"无意于",glossary:"wu_yi_yu"},{text:"横目之民",glossary:"heng_mu_zhi_min"},"乎？"],["愿闻圣治。」"]]},{id:"zhunmang10_s5",label:"圣治乎……拔举而不失其能",sentences:[["谆芒曰：「圣治乎？"],[{text:"官施",glossary:"guan_shi"},"而",{text:"不失其宜",glossary:"bu_shi_qi_yi"},"，"],[{text:"拔举",glossary:"ba_ju"},"而",{text:"不失其能",glossary:"bu_shi_qi_neng"},"，"]]},{id:"zhunmang10_s6",label:"毕见其情事而行其所为……行言自为而天下化",sentences:[[{text:"毕见其情事",glossary:"bi_jian_qi_qing_shi"},"而",{text:"行其所为",glossary:"xing_qi_suo_wei"},"，"],[{text:"行言自为",glossary:"xing_yan_zi_wei"},"而",{text:"天下化",glossary:"tian_xia_hua"},"。"]]},{id:"zhunmang10_s7",label:"手挠顾指……此之谓圣治",sentences:[[{text:"手挠顾指",glossary:"shou_nao_gu_zhi"},"，四方之民",{text:"莫不俱至",glossary:"mo_bu_ju_zhi"},"，"],["此之谓圣治。」"]]},{id:"zhunmang10_s8",label:"愿闻德人……不藏是非美恶",sentences:[["「愿闻德人。」"],["曰：「德人者，",{text:"居无思",glossary:"ju_wu_si"},"，",{text:"行无虑",glossary:"xing_wu_lv"},"，"],["不藏是非美恶。"]]},{id:"zhunmang10_s9",label:"四海之内共利之之谓悦……共给之之谓安",sentences:[["四海之内",{text:"共利之",glossary:"gong_li_zhi"},{text:"之谓悦",glossary:"zhi_wei_yue"},"，"],[{text:"共给之",glossary:"gong_ji_zhi"},{text:"之谓安",glossary:"zhi_wei_an"},"。"]]},{id:"zhunmang10_s10",label:"怊乎若婴儿之失其母也……傥乎若行而失其道也",sentences:[[{text:"怊乎若",glossary:"chao_hu_ruo"},"婴儿之失其母也，"],[{text:"傥乎若",glossary:"tang_hu_ruo"},{text:"行而失其道",glossary:"xing_er_shi_qi_dao"},"也。"]]},{id:"zhunmang10_s11",label:"财用有余而不知其所自来……此谓德人之容",sentences:[["财用有余而不知",{text:"其所自来",glossary:"qi_suo_zi_lai"},"，"],["饮食取足而不知",{text:"其所从",glossary:"qi_suo_cong"},"，"],["此谓",{text:"德人之容",glossary:"de_ren_zhi_rong"},"。」"]]},{id:"zhunmang10_s12",label:"愿闻神人……此之谓混溟",sentences:[["「愿闻神人。」"],["曰：「",{text:"上神乘光",glossary:"shang_shen_cheng_guang"},"，",{text:"与形灭亡",glossary:"yu_xing_mie_wang"},"，",{text:"是谓照旷",glossary:"shi_wei_zhao_kuang"},"。"],[{text:"致命尽情",glossary:"zhi_ming_jin_qing"},"，天地乐而万事",{text:"销亡",glossary:"xiao_wang"},"，"],[{text:"万物复情",glossary:"wan_wu_fu_qing"},"，",{text:"此之谓混溟",glossary:"ci_zhi_wei_hun_ming"},"。」"]]}],T=[{id:"zhun_mang",term:"谆芒",pinyin:"zhūn máng",meaning:"庄子寓言中的人物，是通达大道者的形象。其名具有浑厚、广大而难以测知的意味。本段借他之口说明圣治、德人和神人三种境界。"},{id:"da_he",term:"大壑",pinyin:"dà hè",meaning:"巨大的沟壑，此处指东海或容纳众水的深渊。壑：深谷、深沟。大壑接受无数流水而不满，被汲取也不枯竭，象征广大无穷、包容万物的大道。"},{id:"shi_yu",term:"适遇",pinyin:"shì yù",meaning:"恰好遇见。适：恰逢、正好。谆芒向东前往大壑，恰好在东海岸边遇见苑风。"},{id:"yuan_feng",term:"苑风",pinyin:"yuàn fēng",meaning:"庄子寓言中的人物。他在东海之滨遇见谆芒，依次请教圣治、德人和神人的境界。"},{id:"zhi_wei_wu",term:"之为物",pinyin:"zhī wéi wù",meaning:"作为这样一种事物、从它的性质来说。之：用于主谓之间；为物：作为事物所具有的样态。下文说明大壑容纳不满、取用不竭的特性。"},{id:"zhu_yan_bu_man",term:"注焉而不满",pinyin:"zhù yān ér bù mǎn",meaning:"不断向其中注水，它也不会充满。注：水流注入；焉：于之，即向大壑之中。形容大壑容量无穷，也象征大道包容万物而没有限量。"},{id:"zhuo_yan_bu_jie",term:"酌焉而不竭",pinyin:"zhuó yān ér bù jié",meaning:"不断从中舀取，它也不会枯竭。酌：舀取、取用；焉：从其中；竭：枯尽。象征大道供万物取用而自身无穷。"},{id:"wu_yi_yu",term:"无意于",pinyin:"wú yì yú",meaning:"没有把心意放在……上、不关心……。苑风询问谆芒是否无意关心世间百姓，并由此请求听取圣人治世之道。"},{id:"heng_mu_zhi_min",term:"横目之民",pinyin:"héng mù zhī mín",meaning:"眼睛横生的人民，即人类。古人常以禽兽之目多纵而人目横列作区别，因此用“横目”代称世人。"},{id:"guan_shi",term:"官施",pinyin:"guān shī",meaning:"设置并授予官职。官：官位、职务；施：设置、授予。圣治能根据实际需要安排官职，不使职位与事务失去适当配合。"},{id:"bu_shi_qi_yi",term:"不失其宜",pinyin:"bù shī qí yí",meaning:"不失去应有的适宜性。宜：合宜、恰当。设置官职时能使职务符合实际需要，不作多余或失当的安排。"},{id:"ba_ju",term:"拔举",pinyin:"bá jǔ",meaning:"从众人中选拔、推举人才。拔：提升；举：推荐任用。圣人选拔人才，不以个人好恶为标准，而是顺应各人的实际能力。"},{id:"bu_shi_qi_neng",term:"不失其能",pinyin:"bù shī qí néng",meaning:"不埋没、错置人才的能力。任用者能使各人的才能得到恰当发挥，既不使其过任，也不使其不足任。"},{id:"bi_jian_qi_qing_shi",term:"毕见其情事",pinyin:"bì jiàn qí qíng shì",meaning:"完全看清事物的真实情况。毕：全部；见：察见；情事：真实情状和实际事务。圣人明察人事，却不以私意干预。"},{id:"xing_qi_suo_wei",term:"行其所为",pinyin:"xíng qí suǒ wéi",meaning:"使适合施行的事情得到施行，也可理解为顺着人和事物自身所能做的去实行。重点在于依据真实情势行动，而不是用主观成见强作安排。"},{id:"xing_yan_zi_wei",term:"行言自为",pinyin:"xíng yán zì wéi",meaning:"行动与言语都出于自然，不依赖刻意造作。也可理解为使人民的言行如同出于自身。圣人的教化不显露强制痕迹，天下人自然认为一切是自己完成的。"},{id:"tian_xia_hua",term:"天下化",pinyin:"tiān xià huà",meaning:"天下自然受到感化。化：潜移默化、自然转变。圣人没有用强制命令塑造百姓，百姓却在无形中归于适宜的秩序。"},{id:"shou_nao_gu_zhi",term:"手挠顾指",pinyin:"shǒu náo gù zhǐ",meaning:"举手招引、回顾示意。挠：挥动、招引；顾：回头看；指：指示。形容圣人的号召极其自然省力，只需略加示意，天下人便共同响应。此语古注有不同训释。"},{id:"mo_bu_ju_zhi",term:"莫不俱至",pinyin:"mò bù jù zhì",meaning:"没有人不一同到来。莫不：无不；俱至：共同来到。形容四方百姓自然归附，并非受到武力胁迫。"},{id:"ju_wu_si",term:"居无思",pinyin:"jū wú sī",meaning:"安居时没有刻意的思索筹划。无思并非没有意识，而是不预设成见，不以功利计算扰乱内心。"},{id:"xing_wu_lv",term:"行无虑",pinyin:"xíng wú lǜ",meaning:"行动时没有预先的谋虑。德人因时顺物、自然应对，不依靠反复算计利害来决定行动。"},{id:"gong_li_zhi",term:"共利之",pinyin:"gòng lì zhī",meaning:"共同使天下人获得利益，也可理解为共同享有利益。共：共同；利：使受益或分享利益；之：指四海之内的人民。"},{id:"zhi_wei_yue",term:"之谓悦",pinyin:"zhī wèi yuè",meaning:"这便叫作喜悦。之：复指前文共同受益的状态。天下之利不被一人独占，众人共同受益，因而自然喜悦。"},{id:"gong_ji_zhi",term:"共给之",pinyin:"gòng jǐ zhī",meaning:"共同使天下人的生活得到供给。给：供给充足，读 jǐ。指人人所需都能得到满足，而不是少数人独占财物。"},{id:"zhi_wei_an",term:"之谓安",pinyin:"zhī wèi ān",meaning:"这便叫作安定。人民生活所需共同充足，不因争夺资源而相互伤害，因此天下安宁。"},{id:"chao_hu_ruo",term:"怊乎若",pinyin:"chāo hū ruò",meaning:"怅惘失意得仿佛……。怊乎：怅然、若有所失的样子，怊读 chāo；若：好像。德人无所依恃，在世俗人看来如同失去母亲的婴儿。"},{id:"tang_hu_ruo",term:"傥乎若",pinyin:"tǎng hū ruò",meaning:"恍惚无所系着得仿佛……。傥乎：无所依凭、若有所失的样子。这里形容德人不遵循世俗预设的道路和规则。"},{id:"xing_er_shi_qi_dao",term:"行而失其道",pinyin:"xíng ér shī qí dào",meaning:"行走时仿佛迷失了道路。这里不是说德人真正迷路，而是以迷途者无所趋向的状态，比喻德人不预设目的、不执守固定方法。"},{id:"qi_suo_zi_lai",term:"其所自来",pinyin:"qí suǒ zì lái",meaning:"它从哪里而来。德人财物够用，却不追查来源、不把财物据为己功，表现出随得随用、不积聚计较的态度。"},{id:"qi_suo_cong",term:"其所从",pinyin:"qí suǒ cóng",meaning:"它所从来的地方，即来源。德人饮食足够便停止，不为食物的来路、积藏和占有而费尽心机。"},{id:"de_ren_zhi_rong",term:"德人之容",pinyin:"dé rén zhī róng",meaning:"德人呈现出来的精神面貌。容：仪态、状态。其特征是无思无虑、不藏是非，不计财食来源，看似怅惘迷失，实则无所执著。"},{id:"shang_shen_cheng_guang",term:"上神乘光",pinyin:"shàng shén chéng guāng",meaning:"精神上升而乘着光明。上：升起；神：神妙精神；乘光：与清明之光相合。形容神人的精神超越幽暗和形体局限，进入通明广大的境界。"},{id:"yu_xing_mie_wang",term:"与形灭亡",pinyin:"yǔ xíng miè wáng",meaning:"与形体的界限一同消失。这里不是普通意义上的肉体死亡，而是神人不再执著于形体和自我，形神对立及个体界限归于消解。"},{id:"shi_wei_zhao_kuang",term:"是谓照旷",pinyin:"shì wèi zhào kuàng",meaning:"这就叫作明彻空旷。照：明照、通明；旷：广大、空阔。神人精神清明，无形体与成见遮蔽，因此能与天地万物相通。"},{id:"zhi_ming_jin_qing",term:"致命尽情",pinyin:"zhì mìng jìn qíng",meaning:"充分实现天命，穷尽自然真性。致命：使自然生命达到其极致；尽情：让万物的真实本性完全实现。不是牺牲性命或任意放纵感情。"},{id:"xiao_wang",term:"销亡",pinyin:"xiāo wáng",meaning:"消散、不再存在。万事销亡不是具体事物全部毁灭，而是人为事务、分别、纷争和对立在与天地和乐的境界中消解。"},{id:"wan_wu_fu_qing",term:"万物复情",pinyin:"wàn wù fù qíng",meaning:"万物复归自身的真实本性。复：返回；情：真实情状、自然本性。人为造作消退以后，各种事物便能各自恢复其本来状态。"},{id:"ci_zhi_wei_hun_ming",term:"此之谓混溟",pinyin:"cǐ zhī wèi hùn míng",meaning:"这就叫作浑然幽深、无所分别的境界。混溟：混同幽冥，形容人与万物的分别消融，整体复归未分而深远的大道本原。"}],G=[{id:"menwugui11_s1",label:"门无鬼与赤张满稽……观于武王之师",sentences:[[{text:"门无鬼",glossary:"men_wu_gui"},"与",{text:"赤张满稽",glossary:"chi_zhang_man_ji"},"观于武王之师。"]]},{id:"menwugui11_s2",label:"赤张满稽曰不及有虞氏乎……故离此患也",sentences:[["赤张满稽曰：「不及",{text:"有虞氏",glossary:"you_yu_shi"},"乎！"],[{text:"故离此患也",glossary:"gu_li_ci_huan"},"。」"]]},{id:"menwugui11_s3",label:"天下均治而有虞氏治之邪……其乱而后治之与",sentences:[["门无鬼曰：「",{text:"天下均治",glossary:"tian_xia_jun_zhi"},"而有虞氏治之邪？"],[{text:"其乱",glossary:"qi_luan"},{text:"而后治之与",glossary:"er_hou_zhi_zhi_yu"},"？」"]]},{id:"menwugui11_s4",label:"天下均治之为愿……而何计以有虞氏为",sentences:[["赤张满稽曰：「天下均治之",{text:"为愿",glossary:"wei_yuan"},"，"],["而",{text:"何计",glossary:"he_ji"},"以有虞氏为！"]]},{id:"menwugui11_s5",label:"有虞氏之药疡也……病而求医",sentences:[["有虞氏之",{text:"药疡",glossary:"yao_yang"},"也，"],[{text:"秃而施髢",glossary:"tu_er_shi_di"},"，",{text:"病而求医",glossary:"bing_er_qiu_yi"},"。"]]},{id:"menwugui11_s6",label:"孝子操药以修慈父……圣人羞之",sentences:[["孝子",{text:"操药",glossary:"cao_yao"},{text:"以修慈父",glossary:"yi_xiu_ci_fu"},"，"],[{text:"其色燋然",glossary:"qi_se_jiao_ran"},"，",{text:"圣人羞之",glossary:"sheng_ren_xiu_zhi"},"。"]]},{id:"menwugui11_s7",label:"至德之世不尚贤……民如野鹿",sentences:[["至德之世，",{text:"不尚贤",glossary:"bu_shang_xian"},"，",{text:"不使能",glossary:"bu_shi_neng"},"，"],[{text:"上如标枝",glossary:"shang_ru_biao_zhi"},"，民如野鹿。"]]},{id:"menwugui11_s8",label:"端正而不知以为义……相爱而不知以为仁",sentences:[[{text:"端正而不知",glossary:"duan_zheng_er_bu_zhi"},{text:"以为义",glossary:"yi_wei_yi"},"，"],[{text:"相爱而不知",glossary:"xiang_ai_er_bu_zhi"},{text:"以为仁",glossary:"yi_wei_ren"},"，"]]},{id:"menwugui11_s9",label:"实而不知以为忠……当而不知以为信",sentences:[[{text:"实而不知",glossary:"shi_er_bu_zhi"},{text:"以为忠",glossary:"yi_wei_zhong"},"，"],[{text:"当而不知",glossary:"dang_er_bu_zhi"},{text:"以为信",glossary:"yi_wei_xin"},"，"]]},{id:"menwugui11_s10",label:"蠢动而相使不以为赐……事而无传",sentences:[[{text:"蠢动而相使",glossary:"chun_dong_er_xiang_shi"},{text:"不以为赐",glossary:"bu_yi_wei_ci"},"。"],["是故",{text:"行而无迹",glossary:"xing_er_wu_ji"},"，",{text:"事而无传",glossary:"shi_er_wu_chuan"},"。」"]]}],v=[{id:"men_wu_gui",term:"门无鬼",pinyin:"mén wú guǐ",meaning:"庄子寓言中的人物。本段中他通过追问指出：如果天下本已安定，便无须圣王治理；如果天下已经混乱，圣王之治也只是乱后的补救。"},{id:"chi_zhang_man_ji",term:"赤张满稽",pinyin:"chì zhāng mǎn jī",meaning:"庄子寓言中的人物。他先感叹武王不及有虞氏，继而借治病、施髢等比喻反思有迹之治，并描述自然无为的至德之世。"},{id:"you_yu_shi",term:"有虞氏",pinyin:"yǒu yú shì",meaning:"指上古帝王舜。有虞是舜的氏族或国号。古代常以尧、舜代表圣王之治。"},{id:"gu_li_ci_huan",term:"故离此患也",pinyin:"gù lí cǐ huàn yě",meaning:"所以遭受了这样的祸患。离通“罹”，意为遭遇、遭受；此患指武王必须兴兵作战的军旅之患。"},{id:"tian_xia_jun_zhi",term:"天下均治",pinyin:"tiān xià jūn zhì",meaning:"天下普遍安定。均：普遍、一概；治：安定，与“乱”相对。门无鬼借此追问：天下若本来安定，又何须有虞氏治理？"},{id:"qi_luan",term:"其乱",pinyin:"qí luàn",meaning:"还是天下已经混乱。“其”在这里带有选择、反问语气，与前面的“天下均治”构成两种相反假设。"},{id:"er_hou_zhi_zhi_yu",term:"而后治之与",pinyin:"ér hòu zhì zhī yú",meaning:"然后才去治理它吗？之：代指天下；与通“欤”，表示疑问。意在说明有迹之治常是混乱发生后的补救。"},{id:"wei_yuan",term:"为愿",pinyin:"wéi yuàn",meaning:"作为愿望、成为所希望的目标。“天下均治之为愿”是说真正值得希望的是天下普遍安定。"},{id:"he_ji",term:"何计",pinyin:"hé jì",meaning:"何必计较、哪里还须考虑。“何计以有虞氏为”意为既然目标是天下安定，又何必执着于由有虞氏建立治理功名。"},{id:"yao_yang",term:"药疡",pinyin:"yào yáng",meaning:"用药医治疮伤。药在此作动词；疡：疮、创伤。比喻有虞氏之治是社会发生弊病后的补救，并非最高的无迹之治。"},{id:"tu_er_shi_di",term:"秃而施髢",pinyin:"tū ér shī dì",meaning:"秃头以后戴上假发。施：加上；髢：用头发制成的假发，读 dì。比喻自然完整已经受损，只能借外在手段补饰。"},{id:"bing_er_qiu_yi",term:"病而求医",pinyin:"bìng ér qiú yī",meaning:"生病以后才去求医生。比喻圣王的制度和教化，是社会失去自然秩序以后才出现的救治办法。"},{id:"cao_yao",term:"操药",pinyin:"cāo yào",meaning:"拿着药物。操：持、拿。这里写孝子拿药医治生病的父亲。"},{id:"yi_xiu_ci_fu",term:"以修慈父",pinyin:"yǐ xiū cí fù",meaning:"用药来医治、调养慈爱的父亲。修：修治、治疗。以孝子救治父病，比喻圣人救治已经混乱的天下。"},{id:"qi_se_jiao_ran",term:"其色燋然",pinyin:"qí sè jiāo rán",meaning:"他的脸色忧愁憔悴。燋然：焦虑、憔悴的样子，燋读 jiāo。孝子虽能进药行孝，却因父亲患病而忧虑。"},{id:"sheng_ren_xiu_zhi",term:"圣人羞之",pinyin:"shèng rén xiū zhī",meaning:"圣人以这种事后补救为羞。并非认为救治有错，而是不愿以平定乱世自夸，因为显露治理之功，已说明天下先失去了自然秩序。"},{id:"bu_shang_xian",term:"不尚贤",pinyin:"bù shàng xián",meaning:"不刻意推崇、标举贤人。不是排斥贤者，而是不制造贤与不贤的名位对立，不用贤名诱发争夺。"},{id:"bu_shi_neng",term:"不使能",pinyin:"bù shǐ néng",meaning:"不刻意任使、标榜能人。不是废弃才能，而是不把才能变成求取名位和支配他人的工具。"},{id:"shang_ru_biao_zhi",term:"上如标枝",pinyin:"shàng rú biāo zhī",meaning:"居上位者如同高处的树枝。标枝：树梢、高枝。树枝自然居高而无心支配，比喻君主居上却无为、不自显权势。"},{id:"duan_zheng_er_bu_zhi",term:"端正而不知",pinyin:"duān zhèng ér bù zhī",meaning:"行为端正，却不知道自己正在实行某种道德规范。人们出于自然本性而正直，不以获得德名为目的。"},{id:"yi_wei_yi",term:"以为义",pinyin:"yǐ wéi yì",meaning:"把这种端正行为称作“义”。至德之世已有合宜行为，却没有刻意为其建立“义”的名目。"},{id:"xiang_ai_er_bu_zhi",term:"相爱而不知",pinyin:"xiāng ài ér bù zhī",meaning:"彼此相爱，却不知道自己是在实行某种德目。这种爱出于自然亲近，并非为了显示仁德。"},{id:"yi_wei_ren",term:"以为仁",pinyin:"yǐ wéi rén",meaning:"把彼此相爱称作“仁”。至德之世的人自然相爱，无须以“仁”的名称加以劝导和标榜。"},{id:"shi_er_bu_zhi",term:"实而不知",pinyin:"shí ér bù zhī",meaning:"诚实无欺，却不知道自己正在表现某种德目。实：诚实、真实，指人的内心和行为自然一致。"},{id:"yi_wei_zhong",term:"以为忠",pinyin:"yǐ wéi zhōng",meaning:"把真诚无欺称作“忠”。至德之世有忠实的行为，却没有刻意建立忠的名义。"},{id:"dang_er_bu_zhi",term:"当而不知",pinyin:"dàng ér bù zhī",meaning:"言行恰当、彼此相合，却不知道自己在遵守某种规范。当：恰当、相称，读 dàng。"},{id:"yi_wei_xin",term:"以为信",pinyin:"yǐ wéi xìn",meaning:"把言行相合称作“信”。至德之世的人自然可信，不为取得守信的名声而如此行事。"},{id:"chun_dong_er_xiang_shi",term:"蠢动而相使",pinyin:"chǔn dòng ér xiāng shǐ",meaning:"众人顺着自然本能行动，并彼此帮助、相互为用。蠢动指像虫类一样自然活动，在这里没有愚笨的贬义。"},{id:"bu_yi_wei_ci",term:"不以为赐",pinyin:"bù yǐ wéi cì",meaning:"不把彼此帮助看作恩赐。人们相互协助出于自然，不认为自己施予了恩惠，也不要求对方报答。"},{id:"xing_er_wu_ji",term:"行而无迹",pinyin:"xíng ér wú jì",meaning:"有所行动，却不留下人为造作的痕迹。事情自然完成，看不出谁在刻意安排，也没有可以炫耀的功绩。"},{id:"shi_er_wu_chuan",term:"事而无传",pinyin:"shì ér wú chuán",meaning:"事情完成，却没有个人功名流传。至德之世虽然有实际作为，却没有人据功立名，也无须留下圣王治世的传说。"}],D=[{id:"dahuo12_s1",label:"孝子不谀其亲……臣子之盛也",sentences:[["孝子",{text:"不谀",glossary:"bu_yu"},"其亲，忠臣",{text:"不谄",glossary:"bu_chan"},"其君，"],["臣、子之盛也。"]]},{id:"dahuo12_s2",label:"亲之所言而然……世俗谓之不肖臣",sentences:[["亲之所言而然，所行而善，则世俗谓之不肖子；"],["君之所言而然，所行而善，则世俗谓之不肖臣。"]]},{id:"dahuo12_s3",label:"而未知此其必然邪……不谓之道谀之人也",sentences:[["而未",{text:"知此其必然",glossary:"zhi_ci_qi_bi_ran"},"邪？"],["世俗之所谓然而",{text:"然之",glossary:"ran_er_ran_zhi"},"，所谓善而",{text:"善之",glossary:"shan_er_shan_zhi"},"，"],["则",{text:"不谓之",glossary:"bu_wei_zhi"},{text:"道谀之人也",glossary:"dao_yu_zhi_ren"},"！"]]},{id:"dahuo12_s4",label:"然则俗故严于亲……谓己谀人则怫然作色",sentences:[["然则俗故严于亲而尊于君邪？"],[{text:"谓己道人",glossary:"wei_ji_dao_ren"},"，",{text:"勃然作色",glossary:"bo_ran_zuo_se"},"；"],[{text:"谓己谀人",glossary:"wei_ji_yu_ren"},"，则",{text:"怫然作色",glossary:"fu_ran_zuo_se"},"。"]]},{id:"dahuo12_s5",label:"而终身道人也……终始本末不相坐",sentences:[["而",{text:"终身道人",glossary:"zhong_shen_dao_ren"},"也，终身谀人也，"],[{text:"合譬",glossary:"he_pi"},{text:"饰辞",glossary:"shi_ci"},{text:"聚众",glossary:"ju_zhong"},"也，"],["是",{text:"终始本末",glossary:"zhong_shi_ben_mo"},{text:"不相坐",glossary:"bu_xiang_zuo"},"。"]]},{id:"dahuo12_s6",label:"垂衣裳设采色……而不自谓道谀",sentences:[[{text:"垂衣裳",glossary:"chui_yi_chang"},"，",{text:"设采色",glossary:"she_cai_se"},"，",{text:"动容貌",glossary:"dong_rong_mao"},"，"],[{text:"以媚一世",glossary:"yi_mei_yi_shi"},"，而不自谓道谀；"]]},{id:"dahuo12_s7",label:"与夫人之为徒……愚之至也",sentences:[["与夫人之为徒，",{text:"通是非",glossary:"tong_shi_fei"},"，而不",{text:"自谓众人也",glossary:"zi_wei_zhong_ren"},"，"],[{text:"愚之至",glossary:"yu_zhi_zhi"},"也。"]]},{id:"dahuo12_s8",label:"知其愚者非大愚也……大愚者终身不灵",sentences:[["知其愚者，非大愚也；知其惑者，非大惑也。"],["大惑者，",{text:"终身不解",glossary:"zhong_shen_bu_jie"},"；大愚者，终身",{text:"不灵",glossary:"bu_ling"},"。"]]},{id:"dahuo12_s9",label:"三人行而一人惑……惑者胜也",sentences:[["三人行而一人惑，",{text:"所适者",glossary:"suo_shi_zhe"},"，",{text:"犹可致",glossary:"you_ke_zhi"},"也，惑者少也；"],["二人惑则",{text:"劳而不至",glossary:"lao_er_bu_zhi"},"，",{text:"惑者胜也",glossary:"huo_zhe_sheng"},"。"]]},{id:"dahuo12_s10",label:"而今也以天下惑……不亦悲乎",sentences:[["而今也以天下惑，予虽有",{text:"祈向",glossary:"qi_xiang"},"，不可得也。"],["不亦悲乎！"]]},{id:"dahuo12_s11",label:"大声不入于里耳……则嗑然而笑",sentences:[["大声不入于",{text:"里耳",glossary:"li_er"},"，"],[{text:"折杨",glossary:"zhe_yang"},"、",{text:"皇荂",glossary:"huang_hua"},"，则",{text:"嗑然而笑",glossary:"ke_ran_er_xiao"},"。"]]},{id:"dahuo12_s12",label:"是故高言不止于众人之心……俗言胜也",sentences:[["是故",{text:"高言不止",glossary:"gao_yan_bu_zhi"},"于众人之心；"],[{text:"至言不出",glossary:"zhi_yan_bu_chu"},"，",{text:"俗言胜也",glossary:"su_yan_sheng"},"。"]]},{id:"dahuo12_s13",label:"以二缶钟惑……其庸可得邪",sentences:[[{text:"以二缶钟惑",glossary:"yi_er_fou_zhong_huo"},"，而所适不得矣。"],["而今也以天下惑，予虽有祈向，",{text:"其庸",glossary:"qi_yong"},"可得邪！"]]},{id:"dahuo12_s14",label:"知其不可得也而强之……谁其比忧",sentences:[["知其不可得也而",{text:"强之",glossary:"qiang_zhi"},"，又一惑也！"],["故莫若",{text:"释之而不推",glossary:"shi_zhi_er_bu_tui"},"。"],["不推，",{text:"谁其比忧",glossary:"shui_qi_bi_you"},"！"]]},{id:"dahuo12_s15",label:"厉之人夜半生其子……唯恐其似己也",sentences:[[{text:"厉之人",glossary:"lai_zhi_ren"},"，",{text:"夜半生其子",glossary:"ye_ban_sheng_qi_zi"},"，"],[{text:"遽",glossary:"ju"},{text:"取火而视之",glossary:"qu_huo_er_shi_zhi"},"，"],[{text:"汲汲然",glossary:"ji_ji_ran"},{text:"唯恐",glossary:"wei_kong"},{text:"其似己也",glossary:"qi_si_ji"},"。"]]}],C=[{id:"bu_yu",term:"不谀",pinyin:"bù yú",meaning:"不曲意奉承。谀：为了讨好对方而附和其言行。真正的孝子不会不辨是非地顺从父母，而会以正道相待。"},{id:"bu_chan",term:"不谄",pinyin:"bù chǎn",meaning:"不以卑下言辞奉承。谄：迎合、巴结。真正的忠臣不会为了取悦君主而把君主的一切言行都说成正确。"},{id:"zhi_ci_qi_bi_ran",term:"知此其必然",pinyin:"zhī cǐ qí bì rán",meaning:"知道这种判断难道一定正确。其：岂、难道，带有反问意味；此：指世俗把附和父母、君主的人称为不肖的判断。庄子进一步追问，世俗自身是否值得无条件附和。"},{id:"ran_er_ran_zhi",term:"然而然之",pinyin:"rán ér rán zhī",meaning:"世俗认为正确，自己便也认为正确。前一“然”是世俗所认定的正确；后一“然”作意动用法，意为认为它正确。"},{id:"shan_er_shan_zhi",term:"善而善之",pinyin:"shàn ér shàn zhī",meaning:"世俗认为好，自己便也把它当作好。后一“善”作意动用法。此句批评人们不经独立判断便附和社会评价。"},{id:"bu_wei_zhi",term:"不谓之",pinyin:"bù wèi zhī",meaning:"却不把这种人称为……。之：代指一味附和世俗是非善恶的人。世人批评臣子谄君、子女谀亲，却不认为迎合大众也是谄谀。"},{id:"dao_yu_zhi_ren",term:"道谀之人也",pinyin:"dǎo yú zhī rén yě",meaning:"顺从、奉承他人的人。道在此有顺从、迎合之意，可与“谀”连用，并非讲说道理。指不加判断地迎合世俗意见的人。"},{id:"wei_ji_dao_ren",term:"谓己道人",pinyin:"wèi jǐ dǎo rén",meaning:"说自己是一个迎合、顺从别人的人。道：顺从、附和。世人虽然实际上一生迎合大众，却不愿接受这种评价。"},{id:"bo_ran_zuo_se",term:"勃然作色",pinyin:"bó rán zuò sè",meaning:"突然生气而改变脸色。勃然：怒气骤起的样子；作色：脸色因愤怒而改变。"},{id:"wei_ji_yu_ren",term:"谓己谀人",pinyin:"wèi jǐ yú rén",meaning:"说自己奉承别人。人们不愿承认自己谄谀，却终身按照世俗标准言行，形成自我认识与实际行为的矛盾。"},{id:"fu_ran_zuo_se",term:"怫然作色",pinyin:"fú rán zuò sè",meaning:"愤怒不悦地改变脸色。怫然：气愤、心中不满的样子，怫读 fú；作色：显出怒容。"},{id:"zhong_shen_dao_ren",term:"终身道人",pinyin:"zhōng shēn dǎo rén",meaning:"一生都在迎合、附和别人。这里主要指终身顺从世俗的是非标准，却误以为自己有独立判断。"},{id:"he_pi",term:"合譬",pinyin:"hé pì",meaning:"汇合、罗列各种譬喻。合：聚合；譬：比喻、譬说。指借助众多比喻为世俗意见辩护，使自己的言论显得合理。"},{id:"shi_ci",term:"饰辞",pinyin:"shì cí",meaning:"修饰言辞。饰：文饰、美化。指用华丽巧妙的语言包装观点，以迎合和取悦大众。"},{id:"ju_zhong",term:"聚众",pinyin:"jù zhòng",meaning:"聚集、招引众人。这里指通过譬喻和文饰言辞争取大众认同，以人数和声势证明自己的意见。"},{id:"zhong_shi_ben_mo",term:"终始本末",pinyin:"zhōng shǐ běn mò",meaning:"从终到始、从本到末，即事情的全部方面。这里概括人的实际言行、动机和自我评价。"},{id:"bu_xiang_zuo",term:"不相坐",pinyin:"bù xiāng zuò",meaning:"彼此不能对应、互不符合。坐：相当、对应。人终身迎合大众，却坚持认为自己没有谄谀，其名与实、始与终、本与末互相矛盾。"},{id:"chui_yi_chang",term:"垂衣裳",pinyin:"chuí yī cháng",meaning:"穿着垂挂整齐的礼服。衣裳：上衣和下裳，裳读 cháng。这里指用符合世俗礼制的服饰装扮自己。"},{id:"she_cai_se",term:"设采色",pinyin:"shè cǎi sè",meaning:"设置、配饰各种彩色纹饰。采色：礼服上的色彩与文饰。指以外在服饰表现合乎礼制的身份和德行。"},{id:"dong_rong_mao",term:"动容貌",pinyin:"dòng róng mào",meaning:"刻意调整神情仪态。动：修饰、改变；容貌：面容与举止。指按照世俗礼法安排自己的表情动作。"},{id:"yi_mei_yi_shi",term:"以媚一世",pinyin:"yǐ mèi yī shì",meaning:"借此讨好整个时代的人。媚：取悦、迎合；一世：一世之人、当时社会。指用服饰、仪态和礼节迎合普遍风尚。"},{id:"tong_shi_fei",term:"通是非",pinyin:"tōng shì fēi",meaning:"与众人共同采用一套是非标准。通：相通、相同。这里不是通晓是非，而是与世俗之人共享、附和其判断。"},{id:"zi_wei_zhong_ren",term:"自谓众人也",pinyin:"zì wèi zhòng rén yě",meaning:"把自己看作普通世俗之人。原文说“不自谓众人”，即明明与众人结为同类、共享世俗是非，却不承认自己也是众人之一。"},{id:"yu_zhi_zhi",term:"愚之至",pinyin:"yú zhī zhì",meaning:"愚昧到了极点。至：极点。最大的愚昧不只是判断错误，而是完全不知道自己受世俗意见支配。"},{id:"zhong_shen_bu_jie",term:"终身不解",pinyin:"zhōng shēn bù jiě",meaning:"一生都不能从迷惑中解脱。解：解开、醒悟。大惑者不知道自己迷惑，因此没有反省和解除迷惑的机会。"},{id:"bu_ling",term:"不灵",pinyin:"bù líng",meaning:"不能觉悟、心智不明。灵：灵明、觉察。大愚之人终身缺乏对自身愚昧的觉知。"},{id:"suo_shi_zhe",term:"所适者",pinyin:"suǒ shì zhě",meaning:"所要前往的目的地。适：前往。以三人同行比喻共同追求正确道路：若清醒者占多数，仍可能到达目标。"},{id:"you_ke_zhi",term:"犹可致",pinyin:"yóu kě zhì",meaning:"还能够到达。致：到达。三人之中只有一人迷路，另外两人仍能纠正方向，因此尚可抵达目的地。"},{id:"lao_er_bu_zhi",term:"劳而不至",pinyin:"láo ér bù zhì",meaning:"虽然劳累奔走，却不能到达目的地。当迷惑者占多数时，清醒者无法决定方向，众人只能徒劳而行。"},{id:"huo_zhe_sheng",term:"惑者胜也",pinyin:"huò zhě shèng yě",meaning:"迷惑的人占了优势。胜：超过、占多数。错误意见因人数较多而主导行动，却不会因此变成真理。"},{id:"qi_xiang",term:"祈向",pinyin:"qí xiàng",meaning:"希望前往的方向、所追求的目标。祈：希望、求取；向：方向。庄子说即使自己具有正确方向，面对天下人的共同迷惑，也难以带领众人抵达。此词古注有不同解释。"},{id:"li_er",term:"里耳",pinyin:"lǐ ěr",meaning:"乡里世俗之人的耳朵，借指缺乏高雅鉴赏力的俗耳。高妙宏大的音乐不能进入俗耳，比喻至理难以被普通人接受。"},{id:"zhe_yang",term:"折杨",pinyin:"zhé yáng",meaning:"古代通俗流行的歌曲名。曲调浅近，容易被普通人理解和喜爱，与高妙的“大声”形成对比。"},{id:"huang_hua",term:"皇荂",pinyin:"huáng huā",meaning:"古代通俗歌曲名，也有版本作“皇华”。与“折杨”并举，代表浅近流行、容易取悦大众的音乐。"},{id:"ke_ran_er_xiao",term:"嗑然而笑",pinyin:"kē rán ér xiào",meaning:"便发出声音高兴地笑起来。嗑然：笑声或众声发出的样子。世俗之耳听不懂高雅音乐，听到浅近流行的曲调却立刻感到愉悦。"},{id:"gao_yan_bu_zhi",term:"高言不止",pinyin:"gāo yán bù zhǐ",meaning:"高深的言论不能停留在众人心中。止：停驻、被接受。俗人缺乏理解至理的心境，高言即使说出也不能留下影响。"},{id:"zhi_yan_bu_chu",term:"至言不出",pinyin:"zhì yán bù chū",meaning:"最高妙的言论不能显现、流行。至言：合于大道的言论；不出：不能从俗言包围中出现，也可指得道者最终不愿再说。"},{id:"su_yan_sheng",term:"俗言胜也",pinyin:"sú yán shèng yě",meaning:"世俗言论占据了优势。胜：占上风。由于大众普遍接受浅近成见，真正合道的言论反而无法传播。"},{id:"yi_er_fou_zhong_huo",term:"以二缶钟惑",pinyin:"yǐ èr fǒu zhōng huò",meaning:"被两个瓦缶与钟的声音扰乱、迷惑。缶：瓦制容器，也可敲击发声；钟：乐器。一般理解为杂乱浅近的声音妨碍辨别真正钟声，比喻受到多数俗见干扰而失去判断。此句文字古奥，古注另有不同解释。"},{id:"qi_yong",term:"其庸",pinyin:"qí yōng",meaning:"难道、岂能。庸：表示反问，可译为哪里、难道。“其庸可得邪”即在天下都迷惑的情况下，自己希望达到的目标难道还能实现吗？"},{id:"qiang_zhi",term:"强之",pinyin:"qiǎng zhī",meaning:"勉强去做、强行推行。强读 qiǎng；之指在天下皆惑时仍强求改变众人。明知无法达到而执意强求，本身又是一重迷惑。"},{id:"shi_zhi_er_bu_tui",term:"释之而不推",pinyin:"shì zhī ér bù tuī",meaning:"放下此事，不再向外推求或强行推行。释：放下；推：推行、推究。不是赞成世俗迷惑，而是不以强制方式纠正天下。"},{id:"shui_qi_bi_you",term:"谁其比忧",pinyin:"shuí qí bǐ yōu",meaning:"还有谁会与我一同承担这种忧愁呢？比：并列、相伴。也可理解为不再强行推求后，哪里还有与世俗纠缠所产生的忧患。此句古注存在不同解释。"},{id:"lai_zhi_ren",term:"厉之人",pinyin:"lài zhī rén",meaning:"患恶疾而形貌毁坏的人，也泛指相貌丑陋者。厉通“癞”一类恶疾之义。此人唯恐新生的孩子外貌像自己。"},{id:"ye_ban_sheng_qi_zi",term:"夜半生其子",pinyin:"yè bàn shēng qí zǐ",meaning:"半夜里生下了他的孩子。因夜间昏暗看不清婴儿相貌，故下文急忙取火察看。"},{id:"ju",term:"遽",pinyin:"jù",meaning:"立即、急忙。形容丑者迫不及待地点火查看孩子，生怕孩子与自己相貌相似。"},{id:"qu_huo_er_shi_zhi",term:"取火而视之",pinyin:"qǔ huǒ ér shì zhī",meaning:"取来灯火察看孩子。之：代指新生的孩子。夜半不能看清，便赶快借火光观察其相貌。"},{id:"ji_ji_ran",term:"汲汲然",pinyin:"jí jí rán",meaning:"急切紧张的样子。汲汲：心情迫切、焦虑不安。形容此人极度担心孩子继承自己的丑貌。"},{id:"wei_kong",term:"唯恐",pinyin:"wéi kǒng",meaning:"只怕、非常担心。唯：只；恐：担忧。表示担忧某种不愿出现的情况。"},{id:"qi_si_ji",term:"其似己也",pinyin:"qí sì jǐ yě",meaning:"孩子长得像自己。其：指新生儿。结尾以此讽刺世人只知道害怕后代继承自己的外在丑貌，却不知道自己精神上的愚惑也会影响他人。"}],N=[{id:"shixing13_s1",label:"百年之木……其断在沟中",sentences:[["百年之木，",{text:"破为牺尊",glossary:"po_wei_xi_zun"},"，",{text:"青黄而文之",glossary:"qing_huang_er_wen_zhi"},"，"],[{text:"其断在沟中",glossary:"qi_duan_zai_gou_zhong"},"。"]]},{id:"shixing13_s2",label:"比牺尊于沟中之断……其于失性一也",sentences:[["比牺尊于沟中之断，则",{text:"美恶有间",glossary:"mei_e_you_jian"},"矣，"],["其",{text:"于失性一也",glossary:"yu_shi_xing_yi"},"。"]]},{id:"shixing13_s3",label:"跖与曾史……然其失性均也",sentences:[["跖与曾、史，",{text:"行义有间",glossary:"xing_yi_you_jian"},"矣，"],["然其失性均也。"]]},{id:"shixing13_s4",label:"且夫失性有五……使耳不聪",sentences:[["且夫失性有五：一曰",{text:"五色乱目",glossary:"wu_se_luan_mu"},"，使目不明；"],["二曰",{text:"五声乱耳",glossary:"wu_sheng_luan_er"},"，使耳不聪；"]]},{id:"shixing13_s5",label:"三曰五臭熏鼻……使口厉爽",sentences:[["三曰",{text:"五臭熏鼻",glossary:"wu_xiu_xun_bi"},"，",{text:"困惾中颡",glossary:"kun_zong_zhong_sang"},"；"],["四曰",{text:"五味浊口",glossary:"wu_wei_zhuo_kou"},"，使口",{text:"厉爽",glossary:"li_shuang"},"；"]]},{id:"shixing13_s6",label:"五曰趣舍滑心……皆生之害也",sentences:[["五曰",{text:"趣舍滑心",glossary:"qu_she_gu_xin"},"，",{text:"使性飞扬",glossary:"shi_xing_fei_yang"},"。"],["此五者，皆",{text:"生之害",glossary:"sheng_zhi_hai"},"也。"]]},{id:"shixing13_s7",label:"而杨墨乃始离跂自以为得……非吾所谓得也",sentences:[["而",{text:"杨、墨",glossary:"yang_mo"},{text:"乃始",glossary:"nai_shi"},{text:"离跂",glossary:"li_qi"},{text:"自以为得",glossary:"zi_yi_wei_de"},"，"],["非吾所谓得也。"]]},{id:"shixing13_s8",label:"夫得者困……亦可以为得矣",sentences:[["夫得者",{text:"困",glossary:"kun"},"，可以为得乎？"],["则",{text:"鸠鸮之在于笼",glossary:"jiu_xiao_zai_long"},"也，亦可以为得矣。"]]},{id:"shixing13_s9",label:"且夫趣舍声色以柴其内……搢笏绅修以约其外",sentences:[["且夫趣舍",{text:"声色",glossary:"sheng_se"},{text:"以柴其内",glossary:"yi_chai_qi_nei"},"，"],[{text:"皮弁鹬冠",glossary:"pi_bian_yu_guan"},{text:"搢笏绅修",glossary:"jin_hu_shen_xiu"},{text:"以约其外",glossary:"yi_yue_qi_wai"},"。"]]},{id:"shixing13_s10",label:"内支盈于柴栅……外重纆缴",sentences:[[{text:"内支",glossary:"nei_zhi"},{text:"盈于",glossary:"ying_yu"},{text:"柴栅",glossary:"chai_zha"},"，"],[{text:"外重",glossary:"wai_chong"},{text:"纆缴",glossary:"mo_zhuo"},"，"]]},{id:"shixing13_s11",label:"睆睆然在纆缴之中……而自以为得",sentences:[[{text:"睆睆然",glossary:"huan_huan_ran"},"在",{text:"纆缴之中",glossary:"mo_zhuo_zhi_zhong"},"，"],["而自以为得，"]]},{id:"shixing13_s12",label:"则是罪人交臂历指……亦可以为得矣",sentences:[["则是",{text:"罪人",glossary:"zui_ren"},{text:"交臂历指",glossary:"jiao_bi_li_zhi"},"而"],[{text:"虎豹在于囊槛",glossary:"hu_bao_zai_nang_jian"},"，亦可以为得矣！"]]}],V=[{id:"po_wei_xi_zun",term:"破为牺尊",pinyin:"pò wéi xī zūn",meaning:"把百年大树砍破、剖削，制成牺尊。破：砍开、破割；牺尊：古代祭祀时使用的酒器，常雕成牛羊等牺牲的形状。树木虽被制成贵重礼器，却已经丧失自然生长的本性。"},{id:"qing_huang_er_wen_zhi",term:"青黄而文之",pinyin:"qīng huáng ér wén zhī",meaning:"用青色、黄色等色彩装饰它。文：彩饰、绘饰，作动词；之：代指牺尊。外在文饰使酒器显得华美，却不能弥补树木本性的毁坏。"},{id:"qi_duan_zai_gou_zhong",term:"其断在沟中",pinyin:"qí duàn zài gōu zhōng",meaning:"砍削剩下的断木被丢弃在沟里。断：被截断的残木。制器时一部分木材成为华美牺尊，另一部分则成为沟中的废料。"},{id:"mei_e_you_jian",term:"美恶有间",pinyin:"měi è yǒu jiàn",meaning:"在美与丑、贵与贱方面存在差别。间：间隔、差别，读 jiàn。牺尊受到彩饰和尊崇，断木则被弃置沟中，二者的社会评价明显不同。"},{id:"yu_shi_xing_yi",term:"于失性一也",pinyin:"yú shī xìng yī yě",meaning:"在丧失树木自然本性这一点上却完全相同。一：相同。无论成为贵重礼器还是沟中废木，都已不能保持百年之木原有的生命形态。"},{id:"xing_yi_you_jian",term:"行义有间",pinyin:"xíng yì yǒu jiàn",meaning:"在行为是否合乎世俗义理方面有明显差别。跖代表恶人，曾参、史鱼代表忠孝之士；二者虽有善恶差异，却都可能因执著外在目标而偏离自然本性。"},{id:"wu_se_luan_mu",term:"五色乱目",pinyin:"wǔ sè luàn mù",meaning:"青、黄、赤、白、黑等纷繁色彩扰乱眼睛。五色泛指各种强烈华丽的视觉刺激；过度追逐这些刺激，使视觉失去自然清明。"},{id:"wu_sheng_luan_er",term:"五声乱耳",pinyin:"wǔ shēng luàn ěr",meaning:"宫、商、角、徵、羽等繁复声音扰乱耳朵。五声泛指各种音乐声响；沉溺其中会使听觉受扰，不能保持自然敏锐。"},{id:"wu_xiu_xun_bi",term:"五臭熏鼻",pinyin:"wǔ xiù xūn bí",meaning:"各种气味熏扰鼻子。臭在这里泛指气味，读 xiù，并非只指臭味；五臭通常指膻、焦、香、腥、腐等气味。"},{id:"kun_zong_zhong_sang",term:"困惾中颡",pinyin:"kùn zōng zhòng sǎng",meaning:"鼻窍壅塞不通，使额头受到刺激而困苦。惾：壅塞不通，读 zōng；中：击中、伤害，读 zhòng；颡：额头。形容浓烈气味对鼻腔和头部的损害。此语古奥，旧注训释略有差异。"},{id:"wu_wei_zhuo_kou",term:"五味浊口",pinyin:"wǔ wèi zhuó kǒu",meaning:"酸、苦、甘、辛、咸等浓厚滋味使口舌混浊。浊：扰乱、损害。过度追逐美味，会使自然味觉迟钝失常。"},{id:"li_shuang",term:"厉爽",pinyin:"lì shuǎng",meaning:"口舌受损，味觉出现差失。厉：受到伤害、发生疾病；爽：差失、失去常态。并非现代汉语中“爽快”的意思。"},{id:"qu_she_gu_xin",term:"趣舍滑心",pinyin:"qǔ shě gǔ xīn",meaning:"趋向与舍弃的利害选择扰乱内心。趣通“取”或趋，指追求；舍：放弃；滑：扰乱，读 gǔ。不断计较取舍得失，会使心失去安定。"},{id:"shi_xing_fei_yang",term:"使性飞扬",pinyin:"shǐ xìng fēi yáng",meaning:"使自然本性浮动散乱、向外驰逐。飞扬：不能安定、四处追逐。人的心若不断趋利避害，本性便不能守住自身。"},{id:"sheng_zhi_hai",term:"生之害",pinyin:"shēng zhī hài",meaning:"对生命和自然本性的伤害。生不仅指肉体生存，也包括完整的生命状态。五色、五声、五臭、五味和趣舍若被过度追逐，都会损害生命。"},{id:"yang_mo",term:"杨、墨",pinyin:"yáng mò",meaning:"指杨朱与墨翟。杨朱常被概括为重己、贵生，墨翟主张兼爱、尚贤、节用等。庄子认为二者各执一端，以人为原则约束生命，仍未能保全自然本性。"},{id:"nai_shi",term:"乃始",pinyin:"nǎi shǐ",meaning:"竟然还、于是便。这里带有批评意味，指杨朱、墨翟在有所执著和困迫的情况下，竟然还自以为得道。"},{id:"li_qi",term:"离跂",pinyin:"lí qǐ",meaning:"竭力自立、踮足企求的样子。跂：踮起脚跟，读 qǐ；离有独立、分离或奋力标举之意。形容杨、墨各自突出一端，辛苦追求并标榜自己的学说。此词古注有不同解释。"},{id:"zi_yi_wei_de",term:"自以为得",pinyin:"zì yǐ wéi dé",meaning:"自己认为已经得道或有所获得。这里批评杨、墨虽受固定学说和取舍标准拘束，却误把这种状态当成真正的得道。"},{id:"kun",term:"困",pinyin:"kùn",meaning:"受到困迫、拘束。若所谓“得”反而使生命陷入束缚和劳苦，就不能算是真正的获得。"},{id:"jiu_xiao_zai_long",term:"鸠鸮之在于笼",pinyin:"jiū xiāo zhī zài yú lóng",meaning:"斑鸠和鸮鸟被关在笼子里。鸮：猫头鹰一类的鸟，读 xiāo。笼中或许食物充足，却失去了自由飞翔的本性，因此不能称为真正有所得。"},{id:"sheng_se",term:"声色",pinyin:"shēng sè",meaning:"声音与色彩，泛指外界感官享受。与“趣舍”并列，表示人对外物、感官刺激以及利害得失的追逐。"},{id:"yi_chai_qi_nei",term:"以柴其内",pinyin:"yǐ chái qí nèi",meaning:"用这些东西堵塞人的内心。柴：木栅、堵塞，作动词。趣舍与声色像柴木栅栏一样充满心中，使本性失去自由。"},{id:"pi_bian_yu_guan",term:"皮弁鹬冠",pinyin:"pí biàn yù guān",meaning:"皮弁和鹬羽装饰的冠帽。皮弁：古代贵族所戴的礼冠；鹬冠：以鹬羽装饰的帽冠。这里代表等级礼制服饰以及外在身份标志。"},{id:"jin_hu_shen_xiu",term:"搢笏绅修",pinyin:"jìn hù shēn xiū",meaning:"把笏板插在腰带中，系着长大的衣带。搢：插，读 jìn；笏：古代臣子朝见时所执的手板；绅：大带；修：长。泛指繁复的礼仪装束。"},{id:"yi_yue_qi_wai",term:"以约其外",pinyin:"yǐ yuē qí wài",meaning:"用礼服、冠带和仪节束缚其外在身体。约：捆束、约束。内心受声色取舍堵塞，外在又受礼制形式拘束，生命内外皆不得自由。"},{id:"nei_zhi",term:"内支",pinyin:"nèi zhī",meaning:"内心受到支撑、阻隔，也可理解为内在四处抵触。支：支撑、阻塞。它承接“以柴其内”，形容内心被取舍声色构成的栅栏塞满。此处古注存在异释。"},{id:"ying_yu",term:"盈于",pinyin:"yíng yú",meaning:"充满在……之中。盈：充满。这里指人的内心充满声色、取舍等人为欲念，如同被栅栏占据。"},{id:"chai_zha",term:"柴栅",pinyin:"chái zhà",meaning:"用木柴构成的栅栏。这里比喻声色、利害和取舍构成的内在障碍，把自然本性围困起来。"},{id:"wai_chong",term:"外重",pinyin:"wài chóng",meaning:"外在又层层加上。重：重复、层层，读 chóng。指身体之外又加上礼服、冠带及礼法规范等多重束缚。"},{id:"mo_zhuo",term:"纆缴",pinyin:"mò zhuó",meaning:"捆绑用的绳索。纆：粗绳，读 mò；缴：缠绕、捆束之绳，读 zhuó。这里以绳索比喻外在礼制和名分对身体行为的拘束。"},{id:"huan_huan_ran",term:"睆睆然",pinyin:"huǎn huǎn rán",meaning:"睁大眼睛张望、身受束缚而无可奈何的样子。睆睆：睁眼注视的样子。形容人在内外重重约束中不能自解，却还自认为有所得。"},{id:"mo_zhuo_zhi_zhong",term:"纆缴之中",pinyin:"mò zhuó zhī zhōng",meaning:"绳索捆绑之中。比喻人处在礼法、名分、声色和利害取舍的重重束缚中，失去自然自由。"},{id:"zui_ren",term:"罪人",pinyin:"zuì rén",meaning:"受到刑罚拘系的犯人。文中把受声色、礼法拘束却自以为得的人，比作双臂被缚的罪犯。"},{id:"jiao_bi_li_zhi",term:"交臂历指",pinyin:"jiāo bì lì zhǐ",meaning:"双臂反交而被捆绑，手指受到拘束或刑罚。交臂：两臂交叉捆住；历指：手指依次受到控制、检点或刑治。形容罪犯身受严密束缚。此语古注有异。"},{id:"hu_bao_zai_nang_jian",term:"虎豹在于囊槛",pinyin:"hǔ bào zài yú náng jiàn",meaning:"虎豹被关在袋子和笼槛之中。囊：袋；槛：圈禁猛兽的笼栏，读 jiàn。虎豹虽仍有强健形体，却不能施展其自然能力，比喻人的本性被内外规范牢牢囚禁。"}];return(L,i)=>{const R=g("DaoReadingPrelude"),s=g("DaoTextReading"),t=g("DaoKeywordCards"),_=g("DaoLineGuide");return A(),B("div",null,[i[0]||(i[0]=n("h1",{id:"庄子·天地",tabindex:"-1"},[e("庄子·天地 "),n("a",{class:"header-anchor",href:"#庄子·天地","aria-label":'Permalink to "庄子·天地"'},"​")],-1)),i[1]||(i[1]=n("h2",{id:"篇名释义",tabindex:"-1"},[e("篇名释义 "),n("a",{class:"header-anchor",href:"#篇名释义","aria-label":'Permalink to "篇名释义"'},"​")],-1)),i[2]||(i[2]=n("blockquote",null,[n("p",null,[n("strong",null,"《天地》是《庄子》外篇第五篇，也是外篇中篇幅最长、内容最丰富的一篇。")]),n("p",null,"篇名「天地」——不是说天地本身，而是说：以天地为参照，来理解道·德·人·治。"),n("p",null,"《天地》承接《在宥》——《在宥》的核心命题是「闻在宥天下，不闻治天下也」；《天地》的核心命题是「古之畜天下者，无欲而天下足，无为而万物化」。两篇，是同一个命题的两个方向：《在宥》说：不要治天下；《天地》说：真正的「畜天下」，是无欲无为。"),n("p",null,"《天地》的特色，在于它的层次感——从宇宙生成（泰初有无），到政治哲学（古之畜天下者），到个人修养（刳心·王德·全德），到具体批判（机心·失性五者）——是《庄子》外篇中结构最完整的一篇。")],-1)),a(R,{title:"从德兼于道到泰初有无、机心与失性五者",summary:"《天地》以「技兼于事，事兼于义，义兼于德，德兼于道，道兼于天」的层级为哲学骨架，展开外篇第五篇的完整结构：宇宙生成（泰初有无）、政治哲学（畜天下者无欲无为）、个人修养（刳心·王德·全德）、具体批判（象罔得玄珠、机心纯白、失性五者）。",points:[{label:"先看",text:"顺着德兼于道→刳心十者→玄珠→许由→华封→伯成子高→泰初→机心→至德之世→大惑→失性五者这条线走一遍。"},{label:"再问",text:"「象罔」为什么能找回玄珠？知、离朱、喫诟为什么都不行？"},{label:"最后",text:"「机心存于胸中则纯白不备」——今天的你，还在用桔槔灌园吗？"}],hint:"这是外篇结构最完整的一篇。读的时候可以不断回看《在宥》——两篇是同一个命题的两个方向。"}),i[3]||(i[3]=n("h2",{id:"一、德兼于道·道兼于天",tabindex:"-1"},[e("一、德兼于道·道兼于天 "),n("a",{class:"header-anchor",href:"#一、德兼于道·道兼于天","aria-label":'Permalink to "一、德兼于道·道兼于天"'},"​")],-1)),i[4]||(i[4]=n("h3",{id:"原文",tabindex:"-1"},[e("原文 "),n("a",{class:"header-anchor",href:"#原文","aria-label":'Permalink to "原文"'},"​")],-1)),a(s,{sections:r,glossary:y,"default-mode":"classic","aria-label":"天地·德兼于道 原文"}),i[5]||(i[5]=n("h3",{id:"生僻字词",tabindex:"-1"},[e("生僻字词 "),n("a",{class:"header-anchor",href:"#生僻字词","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(t,{items:[{term:"其化均也",pinyin:["jūn"],meaning:"均：均一、一致。它的化育是均一的（天地化育万物，没有偏私）。"},{term:"其治一也",pinyin:["qí","zhì","yī","yě"],meaning:"它的主宰是同一个（万物虽多，都受同一个道的主宰）。"},{term:"人卒虽众",pinyin:["rén","zú"],meaning:"人卒：人群、众人。人群虽然众多。"},{term:"天德而已矣",pinyin:["tiān","dé","ér","yǐ","yǐ"],meaning:"以天德（自然之德）行事而已。"},{term:"以道观言",pinyin:["yǐ","dào","guān","yán"],meaning:"用道来观察言论。"},{term:"以道观分",pinyin:["fèn"],meaning:"分：名分、职分。用道来观察名分。"},{term:"以道观能",pinyin:["yǐ","dào","guān","néng"],meaning:"用道来观察才能。"},{term:"以道泛观",pinyin:["fàn"],meaning:"泛：广泛、全面。用道来广泛观察。"},{term:"技兼于事",pinyin:["jiān"],meaning:"兼：统摄于、包含于。技，统摄于事之中。"},{term:"道兼于天",pinyin:["dào","jiān","yú","tiān"],meaning:"道，统摄于天之中。"}]}),i[6]||(i[6]=n("h3",{id:"核心句引读",tabindex:"-1"},[e("核心句引读 "),n("a",{class:"header-anchor",href:"#核心句引读","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(_,{title:"天地虽大，其化均也——以天地为参照",subtitle:"君，不是层级的顶端——君，是德与天在人间的体现。",lines:[{text:"天地虽大，其化均也；万物虽多，其治一也；人卒虽众，其主君也。君原于德而成于天。",tone:"总纲",guide:"《天地》开篇，三个「虽……其……」——构成全篇的哲学总纲：天地虽大，其化均也（天地化育万物，没有偏私，一视同仁）；万物虽多，其治一也（万物再多，都受同一个道的主宰——多，是表象；一，是根本）；人卒虽众，其主君也（人，以君为主）。君原于德而成于天——君，根源于德，成就于天。这四句，建立了《天地》的基本层级：天→道→德→君→人卒。君，不是层级的顶端——君，是德与天在人间的体现——君的权威，来自德与天，而不来自自身。"},{text:"技兼于事，事兼于义，义兼于德，德兼于道，道兼于天。",tone:"层级",guide:"这五句，是第一段最重要的命题——技，统摄于事之中；事，统摄于义之中；义，统摄于德之中；德，统摄于道之中；道，统摄于天之中。「兼」——统摄、包含、归属——每一个低层次，都统摄于更高层次之中。这个层级，有两层含义：归属关系（每一个层次都不能脱离更高层次而独立存在）与优先关系（高层次永远优先于低层次）。这个层级，是《天地》全篇的哲学骨架——当人只关注技·事，而忘记德·道·天——这，就是《天地》批判的根源。"},{text:"故曰：古之畜天下者，无欲而天下足，无为而万物化，渊静而百姓定。",tone:"畜天下",guide:"第一段的结论——古之畜天下者——古代养育天下的人——「畜」——养育、蓄养——不是「治天下」，而是「畜天下」——这与《在宥》「在宥天下」完全一致。无欲而天下足——不是「努力让天下充足」，而是「没有欲望，天下自然就充足了」——欲望，是天下不足的根源；无为而万物化——有为，是万物不化的根源；渊静而百姓定——躁动，是百姓不定的根源。三句，结构完全一致：无……而……自然……——不是主动去做，而是通过「不做」，让结果自然出现。"}]}),i[7]||(i[7]=n("h2",{id:"二、夫子论道·刳心十者·王德之人",tabindex:"-1"},[e("二、夫子论道·刳心十者·王德之人 "),n("a",{class:"header-anchor",href:"#二、夫子论道·刳心十者·王德之人","aria-label":'Permalink to "二、夫子论道·刳心十者·王德之人"'},"​")],-1)),i[8]||(i[8]=n("h3",{id:"原文-1",tabindex:"-1"},[e("原文 "),n("a",{class:"header-anchor",href:"#原文-1","aria-label":'Permalink to "原文"'},"​")],-1)),a(s,{sections:h,glossary:m,"default-mode":"classic","aria-label":"天地·刳心十者 原文"}),i[9]||(i[9]=n("h3",{id:"生僻字词-1",tabindex:"-1"},[e("生僻字词 "),n("a",{class:"header-anchor",href:"#生僻字词-1","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(t,{items:[{term:"洋洋乎大哉",pinyin:["yáng","yáng"],meaning:"洋洋：广大无边的样子。广大无边啊！"},{term:"刳心",pinyin:["kū","xīn"],meaning:"刳：剖开、挖空。刳心：挖空心中的成见与执着，使心虚空以容道。"},{term:"执德之谓纪",pinyin:["jì"],meaning:"纪：纲纪、准则。执守德，叫做纪（有了准则）。"},{term:"德成之谓立",pinyin:["dé","chéng","zhī","wèi","lì"],meaning:"德性成就，叫做立（有所建立）。"},{term:"王德之人",pinyin:["wàng","dé"],meaning:"王德：最高的德。王德之人：拥有最高德性的人，得道之人。"}]}),i[10]||(i[10]=n("h3",{id:"核心句引读-1",tabindex:"-1"},[e("核心句引读 "),n("a",{class:"header-anchor",href:"#核心句引读-1","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(_,{title:"君子不可以不刳心焉",subtitle:"不是往心里装东西——而是把心里的东西挖空——心越空，道越能进入。",lines:[{text:"夫道，覆载万物者也，洋洋乎大哉！君子不可以不刳心焉。",tone:"刳心",guide:"第二段，以「夫子曰」开始——夫道，覆载万物者也（道，是覆盖并承载万物的——覆：天覆；载：地载——道，既是天，又是地——万物，在道之中）。洋洋乎大哉！君子不可以不刳心焉——「刳心」——刳：剖开、挖空——刳心：挖空心中的成见与执着，使心虚空，以容纳道。这是《天地》对「修道」的核心表述：不是往心里装东西——而是把心里的东西挖空——心越空，道越能进入——这与《人间世》「心斋」完全呼应：「唯道集虚，虚者，心斋也。」"},{text:"无为为之之谓天，无为言之之谓德，爱人利物之谓仁，不同同之之谓大，行不崖异之谓宽，有万不同之谓富。",tone:"六定义",guide:"六句，定义六个概念——天·德·仁·大·宽·富。庄子的六个定义，与儒家的定义有根本的不同：儒家的仁·大·宽·富，都是积极的、主动的、需要努力实现的；庄子的仁·大·宽·富，都是包容的、顺应的、以「不……」为特征的——不同同之（不强求相同，而是在差异中达到大同——包容差异，才是真正的大），行不崖异（不刻意标新立异，才是真正的宽广），有万不同（真正的富，不是财富的积累——而是包容万种差异的能力）。"},{text:"故执德之谓纪，德成之谓立，循于道之谓备，不以物挫志之谓完。",tone:"四递进",guide:"四句，再定义四个概念——纪·立·备·完，构成一个递进：纪（有准则）→立（有建立）→备（完备）→完（完整）。「不以物挫志之谓完」——这一句，是四者中最重要的：完整，不是外在的完整——而是：内在的志向不被外物所挫伤——这，才是真正的完整。外物，永远在变化——真正的完整，在于内在的志向不被外物所动。"},{text:"视乎冥冥，听乎无声。冥冥之中，独见晓焉；无声之中，独闻和焉。",tone:"冥冥",guide:"王德之人——荡荡乎！忽然出，勃然动，而万物从之乎！——不是刻意的，不是预谋的——这种「突然」，是自然的流露。视乎冥冥，听乎无声——向幽暗深远之处观看，向无声之处聆听——冥冥之中，独见晓焉（不是在光明中看见光明——而是在幽暗中，独自见到光明——这种「见」，不是感官的见，而是道的见）；无声之中，独闻和焉（不是在声音中听见和谐——而是在无声中，独自听到和谐）。这与广成子「无视无听，抱神以静」完全呼应：不用感官，而用道——在感官无法到达的地方，道独自见到、听到。"}]}),i[11]||(i[11]=n("h2",{id:"三、黄帝遗玄珠·象罔得之",tabindex:"-1"},[e("三、黄帝遗玄珠·象罔得之 "),n("a",{class:"header-anchor",href:"#三、黄帝遗玄珠·象罔得之","aria-label":'Permalink to "三、黄帝遗玄珠·象罔得之"'},"​")],-1)),i[12]||(i[12]=n("h3",{id:"原文-2",tabindex:"-1"},[e("原文 "),n("a",{class:"header-anchor",href:"#原文-2","aria-label":'Permalink to "原文"'},"​")],-1)),a(s,{sections:l,glossary:u,"default-mode":"classic","aria-label":"天地·黄帝遗玄珠 原文"}),i[13]||(i[13]=n("h3",{id:"生僻字词-2",tabindex:"-1"},[e("生僻字词 "),n("a",{class:"header-anchor",href:"#生僻字词-2","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(t,{items:[{term:"赤水之北",pinyin:["chì","shuǐ","zhī","běi"],meaning:"赤水：传说中的河流，昆仑山附近。"},{term:"昆仑之丘",pinyin:["kūn","lún"],meaning:"昆仑：传说中的神山，道的象征之地。"},{term:"遗其玄珠",pinyin:["yí","xuán","zhū"],meaning:"遗：遗失、丢失。玄珠：黑色的珠，象征道（玄：深远幽暗，道的颜色）。"},{term:"使知索之",pinyin:["zhī","suǒ"],meaning:"知：智慧、机巧之知。派智慧去寻找。"},{term:"离朱",pinyin:["lí","zhū"],meaning:"传说中视力极佳的人，能在百步之外看清秋毫之末。象征极致的视觉感知。"},{term:"喫诟",pinyin:["chī","gòu"],meaning:"传说中善于辩论的人。象征极致的辩论能力。"},{term:"象罔",pinyin:["xiàng","wǎng"],meaning:"象：形象、有形；罔：无、虚无。象罔：有形与无形之间，若有若无的状态。象征无心、无执的状态。"}]}),i[14]||(i[14]=n("h3",{id:"核心句引读-2",tabindex:"-1"},[e("核心句引读 "),n("a",{class:"header-anchor",href:"#核心句引读-2","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(_,{title:"异哉，象罔乃可以得之乎？",subtitle:"越主动地找，越找不到——因为「找」本身，就是一种执着。",lines:[{text:"使知索之而不得，使离朱索之而不得，使喫诟索之而不得也。乃使象罔，象罔得之。",tone:"四者",guide:"黄帝，派了三个人去寻找——知（智慧·机巧之知），不得；离朱（极致的视觉感知），不得；喫诟（极致的辩论能力），不得。三者，都没有找到——乃使象罔，象罔得之。四个人物，各有象征：知·离朱·喫诟——代表了人类最引以为傲的三种能力：智识、感知、辩论——这三种能力，在寻找道的时候，全部失败。为什么？因为道，是「玄珠」——玄：深远幽暗，不可以用智识把握；珠：圆满完整，不可以用感官分割。道，不是可以被「找」到的——越主动地找，越找不到——因为「找」本身，就是一种执着，而执着，与道相悖。"},{text:"乃使象罔，象罔得之。黄帝曰：异哉，象罔乃可以得之乎？",tone:"象罔",guide:"象罔——若有若无——象：有形象；罔：无、虚无——象罔，是有形与无形之间的状态——不完全有，不完全无——若有若无，无心无执。这种状态，才能找到玄珠——不是因为象罔更聪明，更有眼力，更善辩——而是因为：象罔，不执着于「找」——无心，才能得；有心，反而失。这与鸿蒙「若彼知之，乃是离之」完全呼应：越想知道道，越离开道——象罔，不想知道，反而得到了。黄帝的感叹「异哉」——是真正的惊异：他派出了最强的能力，全部失败——却被一个「若有若无」的象罔找到了——这，颠覆了黄帝对「能力」的全部认知。"}]}),i[15]||(i[15]=n("h2",{id:"四、尧问许由·啮缺不配天",tabindex:"-1"},[e("四、尧问许由·啮缺不配天 "),n("a",{class:"header-anchor",href:"#四、尧问许由·啮缺不配天","aria-label":'Permalink to "四、尧问许由·啮缺不配天"'},"​")],-1)),i[16]||(i[16]=n("h3",{id:"原文-3",tabindex:"-1"},[e("原文 "),n("a",{class:"header-anchor",href:"#原文-3","aria-label":'Permalink to "原文"'},"​")],-1)),a(s,{sections:o,glossary:d,"default-mode":"classic","aria-label":"天地·尧问许由 原文"}),i[17]||(i[17]=n("h3",{id:"生僻字词-3",tabindex:"-1"},[e("生僻字词 "),n("a",{class:"header-anchor",href:"#生僻字词-3","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(t,{items:[{term:"许由",pinyin:["xǔ","yóu"],meaning:"传说中的隐士，尧欲让天下于他而不受。尧的老师。"},{term:"啮缺",pinyin:["niè","quē"],meaning:"传说中的人物，许由的学生，王倪的老师。"},{term:"被衣",pinyin:["pī","yī"],meaning:"传说中的人物，王倪的老师。"},{term:"配天",pinyin:["pèi","tiān"],meaning:"与天相配，成为天子（治理天下）。"},{term:"聪明睿知",pinyin:["ruì","zhī"],meaning:"聪明：耳聪目明；睿：深远的智慧；知：机巧之知。极度聪明有智慧。"},{term:"给数以敏",pinyin:["jǐ","shuò"],meaning:"给：敏捷；数：频繁、迅速；敏：敏锐。反应敏捷迅速。"},{term:"其性过人",pinyin:["qí","xìng","guò","rén"],meaning:"他的才性超过常人。"},{term:"以人受天",pinyin:["yǐ","rén","shòu","tiān"],meaning:"以人（人为的标准）来接受天（天道）。用人的标准来理解天道。"},{term:"审乎禁过",pinyin:["shěn"],meaning:"审：审察、精通。精通于禁止过失。"},{term:"乘人而无天",pinyin:["chéng","rén","ér","wú","tiān"],meaning:"依靠人（人为的能力）而没有天（天道）。"},{term:"方且为绪使",pinyin:["xù","shǐ"],meaning:"绪：丝绪、线头（比喻纷繁的事务）。正在被纷繁事务所驱使。"},{term:"方且为物絯",pinyin:["gài"],meaning:"絯：绳索、束缚。正在被外物所束缚。"}]}),i[18]||(i[18]=n("h3",{id:"核心句引读-3",tabindex:"-1"},[e("核心句引读 "),n("a",{class:"header-anchor",href:"#核心句引读-3","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(_,{title:"殆哉，圾乎天下！——让啮缺配天，天下会有危险",subtitle:"越聪明，越忙碌；越忙碌，越被事务驱使；越被驱使，越失去恒常。",lines:[{text:"啮缺之为人也，聪明睿知，给数以敏，其性过人，而又乃以人受天。",tone:"以人受天",guide:"许由，先描述啮缺的优点——聪明睿知（极度聪明有智慧），给数以敏（反应敏捷迅速），其性过人（才性超过常人）——这三点，都是优点——但许由紧接着说：而又乃以人受天——然而，他以人（人为的标准）来接受天（天道）。这一句，是啮缺问题的核心：他的聪明睿知，是人的聪明——这一切，都是「人」的层面——他用「人」的标准，来理解「天」——这，是根本性的错误。"},{text:"彼审乎禁过，而不知过之所由生。",tone:"治标",guide:"这一句，是对「治标不治本」的精准批判：啮缺，知道如何禁止过失——制定规范，惩罚过失，管理行为——但他不知道：过失，从哪里产生。从《在宥》的逻辑来看：过失，从「撄人心」产生——从本性失去安顿产生——从「治天下」本身产生。啮缺，只知道禁止过失，却不知道他的「治」，本身就是过失产生的根源——这，是治者最深的盲点。"},{text:"治，乱之率也，北面之祸也，南面之贼也。",tone:"最终判决",guide:"许由，给出了一个有限的肯定——虽然，有族有祖，可以为众父而不可以为众父父（啮缺有能力，但没有根本——「众父」是引导者，「众父父」是根本的源头）。治，乱之率也——治理，是混乱的率领者——治理，导致混乱——这与《在宥》「罪在撄人心」完全呼应；北面之祸也，南面之贼也——对臣子来说，是祸害；对君主来说，是贼害——治理，对君臣双方，都是害。这三句，是《天地》对「治」的最终判决：治，不只是无效的——治，是有害的。"}]}),i[19]||(i[19]=n("h2",{id:"五、尧观华封·三辞三驳",tabindex:"-1"},[e("五、尧观华封·三辞三驳 "),n("a",{class:"header-anchor",href:"#五、尧观华封·三辞三驳","aria-label":'Permalink to "五、尧观华封·三辞三驳"'},"​")],-1)),i[20]||(i[20]=n("h3",{id:"原文-4",tabindex:"-1"},[e("原文 "),n("a",{class:"header-anchor",href:"#原文-4","aria-label":'Permalink to "原文"'},"​")],-1)),a(s,{sections:x,glossary:p,"default-mode":"classic","aria-label":"天地·尧观华封 原文"}),i[21]||(i[21]=n("h3",{id:"生僻字词-4",tabindex:"-1"},[e("生僻字词 "),n("a",{class:"header-anchor",href:"#生僻字词-4","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(t,{items:[{term:"尧观乎华",pinyin:["huà"],meaning:"华：华山。尧巡视到华山。"},{term:"华封人",pinyin:["huà","fēng","rén"],meaning:"华山的守封之人（地方官员或守土之人）。"},{term:"请祝圣人",pinyin:["zhù"],meaning:"祝：祝愿、祝福。请允许我祝福圣人。"},{term:"使圣人寿",pinyin:["shòu"],meaning:"使：让、祝愿。祝圣人长寿。"},{term:"辞",pinyin:["cí"],meaning:"辞谢、拒绝。"},{term:"富则多事",pinyin:["fù","zé","duō","shì"],meaning:"富有了就有更多的事务（财富带来麻烦）。"},{term:"寿则多辱",pinyin:["shòu","zé","duō","rǔ"],meaning:"长寿了就有更多的屈辱（活得越久，经历的屈辱越多）。"},{term:"鹑居而彀食",pinyin:["chún","jū","gòu","shí"],meaning:"鹑居：像鹌鹑一样居处（随遇而安，不固定）；彀食：像幼鸟一样进食（随时取食，不积储）。"},{term:"鸟行而无彰",pinyin:["niǎo","xíng","wú","zhāng"],meaning:"鸟行：像鸟一样行走（自由，不留痕迹）；无彰：没有彰显（不留名声）。"},{term:"退已",pinyin:["tuì","yǐ"],meaning:"退下吧！（已：语气词，表示坚决）"}]}),i[22]||(i[22]=n("h3",{id:"核心句引读-4",tabindex:"-1"},[e("核心句引读 "),n("a",{class:"header-anchor",href:"#核心句引读-4","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(_,{title:"始也我以女为圣人邪，今然君子也",subtitle:"圣人，不计算——圣人，不问「这对我的德有没有好处」。",lines:[{text:"尧曰：多男子则多惧，富则多事，寿则多辱。是三者，非所以养德也，故辞。",tone:"养德",guide:"华封人，连续三次祝福——寿·富·多男子——尧，连续三次拒绝——辞·辞·辞。尧的回答：多男子则多惧，富则多事，寿则多辱——是三者，非所以养德也，故辞。尧的逻辑，是「养德」的逻辑——一切以德为标准——对德有害的，拒绝。看起来，尧的回答很高尚——但华封人，对尧的回答，给出了更深的批判。"},{text:"封人曰：始也我以女为圣人邪，今然君子也。",tone:"君子",guide:"这一句，是华封人对尧的最深批判——圣人，高于君子——尧，只是君子，不是圣人——为什么？因为尧的逻辑，还停留在「养德」的层面——还在计算：这对我的德有没有好处——还在以「德」为目标——这，是君子的逻辑，不是圣人的逻辑。圣人，不计算——圣人，不问「这对我的德有没有好处」——因为圣人，已经超越了这个层面。"},{text:"夫圣人，鹑居而彀食，鸟行而无彰。天下有道，则与物皆昌；天下无道，则修德就闲。",tone:"圣人",guide:"华封人，描绘真正的圣人——鹑居而彀食（像鹌鹑一样居处，像幼鸟一样进食——不执着于居所，不积储食物），鸟行而无彰（像鸟一样行走，没有彰显——不留痕迹，不留名声）。天下有道，则与物皆昌（不是独自昌盛，而是与物皆昌——顺应天下，与万物同流）；天下无道，则修德就闲（不是强行改变天下，而是退而修德）。尧，还在计算——这对我的德有没有好处——华封人的圣人，不计算——随遇而安，与物皆昌——这，才是真正的圣人。"}]}),i[23]||(i[23]=n("h2",{id:"六、伯成子高·辞诸侯而耕",tabindex:"-1"},[e("六、伯成子高·辞诸侯而耕 "),n("a",{class:"header-anchor",href:"#六、伯成子高·辞诸侯而耕","aria-label":'Permalink to "六、伯成子高·辞诸侯而耕"'},"​")],-1)),i[24]||(i[24]=n("h3",{id:"原文-5",tabindex:"-1"},[e("原文 "),n("a",{class:"header-anchor",href:"#原文-5","aria-label":'Permalink to "原文"'},"​")],-1)),a(s,{sections:z,glossary:b,"default-mode":"classic","aria-label":"天地·伯成子高 原文"}),i[25]||(i[25]=n("h3",{id:"生僻字词-5",tabindex:"-1"},[e("生僻字词 "),n("a",{class:"header-anchor",href:"#生僻字词-5","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(t,{items:[{term:"伯成子高",pinyin:["bó","chéng","zǐ","gāo"],meaning:"传说中的人物，尧时的诸侯，后辞官归耕。"},{term:"立为诸侯",pinyin:["lì","wéi","zhū","hóu"],meaning:"被立为诸侯（接受封赏）。"},{term:"禹趋就下风",pinyin:["qū","jiù","xià","fēng"],meaning:"趋：快步走；就下风：走到下风处（表示恭敬）。"},{term:"不赏而民劝",pinyin:["quàn"],meaning:"劝：勉励、努力。不奖赏，百姓自然努力。"},{term:"不罚而民畏",pinyin:["bù","fá","ér","mín","wèi"],meaning:"不惩罚，百姓自然敬畏。"},{term:"德自此衰",pinyin:["dé","zì","cǐ","shuāi"],meaning:"德性从此衰败。"},{term:"刑自此立",pinyin:["xíng","zì","cǐ","lì"],meaning:"刑罚从此建立。"},{term:"夫子阖行邪",pinyin:["hé","xíng","yé"],meaning:"阖：何不、还是。你还是走吧！"},{term:"无落吾事",pinyin:["luò"],meaning:"落：耽误、妨碍。不要耽误我的事！"}]}),i[26]||(i[26]=n("h3",{id:"核心句引读-5",tabindex:"-1"},[e("核心句引读 "),n("a",{class:"header-anchor",href:"#核心句引读-5","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(_,{title:"今子赏罚而民且不仁，德自此衰，刑自此立，后世之乱自此始矣",subtitle:"赏罚，不是解决问题的方法——赏罚，反而制造了问题。",lines:[{text:"昔者尧治天下，不赏而民劝，不罚而民畏。今子赏罚而民且不仁，德自此衰，刑自此立，后世之乱自此始矣！",tone:"赏罚",guide:"伯成子高的回答，是四则寓言中最直接的批判——从前尧治天下，不奖赏，百姓自然努力；不惩罚，百姓自然敬畏。现在你用赏罚，百姓反而不仁了——这一句，是《天地》对「赏罚」最直接的批判——与《在宥》「举天下以赏其善者不足，举天下以罚其恶者不给」完全呼应：赏罚，不是解决问题的方法——赏罚，反而制造了问题——因为赏罚，是对本性的干涉——有了赏，人才开始为赏而行善——有了罚，人才开始为避罚而行善——这，不是真正的善，而是功利的善——真正的善，消失了。"},{text:"夫子阖行邪？无落吾事！俋俋乎耕而不顾。",tone:"不回头",guide:"这个结尾，与华封人「退已」异曲同工——都是两个字，都是坚决的拒绝——都是在说完最重要的话之后，不再多说，不再回头。伯成子高，不是愤怒——而是：已经说完了，该做的事还要做——耕田，才是他的事——天下的治乱，不是他的事了。"}]}),i[27]||(i[27]=n("h2",{id:"七、泰初有无",tabindex:"-1"},[e("七、泰初有无 "),n("a",{class:"header-anchor",href:"#七、泰初有无","aria-label":'Permalink to "七、泰初有无"'},"​")],-1)),i[28]||(i[28]=n("h3",{id:"原文-6",tabindex:"-1"},[e("原文 "),n("a",{class:"header-anchor",href:"#原文-6","aria-label":'Permalink to "原文"'},"​")],-1)),a(s,{sections:c,glossary:w,"default-mode":"classic","aria-label":"天地·泰初有无 原文"}),i[29]||(i[29]=n("h3",{id:"生僻字词-6",tabindex:"-1"},[e("生僻字词 "),n("a",{class:"header-anchor",href:"#生僻字词-6","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(t,{items:[{term:"泰初",pinyin:["tài","chū"],meaning:"泰：极、最。泰初：最初、太初，宇宙的最初状态。"},{term:"有无",pinyin:["yǒu","wú"],meaning:"有：存在；无：不存在。泰初的状态是「有无」——有，但是无（有存在，但无形无名）。"},{term:"无有无名",pinyin:["wú","yǒu","wú","míng"],meaning:"没有「有」，没有「名」——无形无名的状态。"},{term:"一之所起",pinyin:["yī","zhī","suǒ","qǐ"],meaning:"「一」（道的本体）开始生起的地方。"},{term:"有一而未形",pinyin:["yǒu","yī","ér","wèi","xíng"],meaning:"有了「一」，但还没有形体。"},{term:"未形者有分",pinyin:["fèn"],meaning:"分：分化、区分。还没有形体，但已经有了分化（阴阳的分化）。"},{term:"留动而生物",pinyin:["liú","dòng"],meaning:"留：流动、停留；动：运动。流动而生成万物。"},{term:"性修反德",pinyin:["xiū","fǎn"],meaning:"修：修养；反：返回。修养本性，返回于德。"},{term:"德至同于初",pinyin:["dé","zhì","tóng","yú","chū"],meaning:"德达到极致，与最初（泰初）相同。"},{term:"合喙鸣",pinyin:["hé","huì","míng"],meaning:"合：合拢；喙：嘴。合拢嘴，不鸣叫（沉默）。"},{term:"其合缗缗",pinyin:["mín","mín"],meaning:"缗缗：连绵不断、混沌一体的样子。它的合，是连绵不断的。"},{term:"若愚若昏",pinyin:["ruò","yú","ruò","hūn"],meaning:"像愚钝，像昏昧（外表看似愚昏，实则与道合一）。"},{term:"玄德",pinyin:["xuán","dé"],meaning:"深远幽暗的德，最高的德。"},{term:"同乎大顺",pinyin:["dà","shùn"],meaning:"大顺：与天地万物完全顺应。与大顺相同。"}]}),i[30]||(i[30]=n("h3",{id:"核心句引读-6",tabindex:"-1"},[e("核心句引读 "),n("a",{class:"header-anchor",href:"#核心句引读-6","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(_,{title:"泰初有无——宇宙生成论与回归序列",subtitle:"生成，是从无到有，从一到多；回归，是从多到一，从有到无。",lines:[{text:"泰初有无，无有无名。一之所起，有一而未形。",tone:"生成",guide:"第7段，是《天地》全篇最重要的哲学段落——也是《庄子》外篇中，对宇宙生成论描述最完整的一段。泰初有无——宇宙最初的状态，是「有无」——不是「有」，也不是「无」——而是「有无」——有，但是无——存在，但无形无名。无有无名——没有「有」，没有「名」——无形，无名，无分别——这是《老子》「无名，天地之始」的呼应。一之所起，有一而未形——「一」（道的本体）开始生起——有了「一」，但还没有形体——这是《老子》「道生一，一生二，二生三，三生万物」的第一步：道生一。"},{text:"物得以生谓之德；未形者有分，且然无间谓之命；留动而生物，物成生理谓之形；形体保神，各有仪则谓之性。",tone:"四定义",guide:"四句，定义四个核心概念——德·命·形·性：物得以生谓之德（德，在这里的定义极为根本：不是道德的德，而是万物从道那里得到的、使它们能够生长的那个东西——德，是道在万物中的体现）；未形者有分，且然无间谓之命（命，是形体出现之前，已经存在的那个自然的分化与流动）；留动而生物，物成生理谓之形（形，包含了外在的形状与内在的条理）；形体保神，各有仪则谓之性（性，是每个存在的独特方式）。四个概念，构成一个完整的生成序列：泰初→一→德→命→形→性——从宇宙从无到有、从一到多、从无形到有形的完整过程。"},{text:"性修反德，德至同于初。同乃虚，虚乃大。",tone:"回归",guide:"生成序列之后，庄子给出了回归序列——性修反德（修养本性，返回于德），德至同于初（德达到极致，与最初相同），同乃虚（与初相同，就是虚），虚乃大（虚空，就是大）。这四句，是整个宇宙生成论的逆向：生成方向：泰初→一→德→命→形→性；回归方向：性→修→反德→同于初→虚→大。生成，是从无到有，从一到多；回归，是从多到一，从有到无。「性修反德」——不是抛弃形体，不是逃离世界——而是在形体之中，修养本性——修养到极致，自然返回于德——这，是《天地》对修道路径的最完整描述：不需要离开世界——在世界中修养本性——自然回归到泰初的虚大。"}]}),i[31]||(i[31]=n("h2",{id:"八、夫子问老聃·将闾葂见季彻",tabindex:"-1"},[e("八、夫子问老聃·将闾葂见季彻 "),n("a",{class:"header-anchor",href:"#八、夫子问老聃·将闾葂见季彻","aria-label":'Permalink to "八、夫子问老聃·将闾葂见季彻"'},"​")],-1)),i[32]||(i[32]=n("h3",{id:"原文-7",tabindex:"-1"},[e("原文 "),n("a",{class:"header-anchor",href:"#原文-7","aria-label":'Permalink to "原文"'},"​")],-1)),a(s,{sections:q,glossary:j,"default-mode":"classic","aria-label":"天地·夫子问老聃 原文"}),i[33]||(i[33]=n("h3",{id:"生僻字词-7",tabindex:"-1"},[e("生僻字词 "),n("a",{class:"header-anchor",href:"#生僻字词-7","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(t,{items:[{term:"治道若相放",pinyin:["xiāng","fǎng"],meaning:"相放：相仿、模仿。治道，好像在模仿（道）。"},{term:"离坚白",pinyin:["lí","jiān","bái"],meaning:"离：分离。坚白：坚硬与白色（公孙龙的「坚白论」）。"},{term:"若县寓",pinyin:["ruò","xuán","yù"],meaning:"县：通「悬」，悬挂；寓：寄寓。像悬挂在空中一样（高悬而不落地，脱离实际）。"},{term:"胥易技系",pinyin:["xū","yì","jì","xì"],meaning:"胥：相互；易：变换；技：技巧；系：束缚。相互变换技巧，被技巧所束缚。"},{term:"劳形怵心",pinyin:["chù","xīn"],meaning:"怵：恐惧、惊惧。劳累形体，惊惧内心。"},{term:"将闾葂",pinyin:["jiāng","lǘ","miǎn"],meaning:"庄子虚构的人物，向季彻请教。"},{term:"季彻",pinyin:["jì","chè"],meaning:"庄子虚构的人物，得道之人。"},{term:"必服恭俭",pinyin:["bì","fú","gōng","jiǎn"],meaning:"必须身着恭俭（以恭俭为表率）。"},{term:"无阿私",pinyin:["ē","sī"],meaning:"阿私：偏袒私情。不偏袒私情。"},{term:"摇荡民心",pinyin:["yáo","dàng","mín","xīn"],meaning:"摇动、感化民心（非强制，而是自然感化）。"}]}),i[34]||(i[34]=n("h3",{id:"核心句引读-7",tabindex:"-1"},[e("核心句引读 "),n("a",{class:"header-anchor",href:"#核心句引读-7","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(_,{title:"忘乎物，忘乎天，其名为忘己——入于天",subtitle:"辩者以为在追求道，实则被自己的辩论技巧所束缚——技巧，成了枷锁。",lines:[{text:"是胥易技系，劳形怵心者也。执留之狗成思，猿狙之便自山林来。",tone:"技系",guide:"夫子（孔子）问老聃：有人治道若相放，可不可，然不然——辩者有言曰：离坚白，若县寓——若是则可谓圣人乎？老聃的回答，极为直接——是胥易技系，劳形怵心者也——这是相互变换技巧、被技巧所束缚，劳累形体、惊惧内心的人。「胥易技系」——辩者，以为自己在追求道——实则，被自己的辩论技巧所束缚——技巧，成了枷锁。「执留之狗成思，猿狙之便自山林来」——被拴住的狗整天思虑，猿猴的灵便来自山林——离开了本然的环境，灵便就消失了。"},{text:"忘乎物，忘乎天，其名为忘己。忘己之人，是之谓入于天。",tone:"忘己",guide:"有治在人——治理，在于人。忘乎物，忘乎天，其名为忘己——忘掉外物，忘掉天，这叫做忘己——忘己之人，是之谓入于天——忘己的人，这叫做进入天（与天合一）。「忘己」——不是消灭自我——而是：不再执着于「我」与「物」的分别——忘记那个以自我为中心的「我」——这，与《人间世》的「吾丧我」、《大宗师》的「堕肢体，黜聪明」完全呼应——入于天，不是离开人间，而是放下执着，与天地合一。"}]}),i[35]||(i[35]=n("h2",{id:"九、子贡遇丈人·机心·全德之人",tabindex:"-1"},[e("九、子贡遇丈人·机心·全德之人 "),n("a",{class:"header-anchor",href:"#九、子贡遇丈人·机心·全德之人","aria-label":'Permalink to "九、子贡遇丈人·机心·全德之人"'},"​")],-1)),i[36]||(i[36]=n("h3",{id:"原文-8",tabindex:"-1"},[e("原文 "),n("a",{class:"header-anchor",href:"#原文-8","aria-label":'Permalink to "原文"'},"​")],-1)),a(s,{sections:f,glossary:k,"default-mode":"classic","aria-label":"天地·子贡遇丈人 原文"}),i[37]||(i[37]=n("h3",{id:"生僻字词-8",tabindex:"-1"},[e("生僻字词 "),n("a",{class:"header-anchor",href:"#生僻字词-8","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(t,{items:[{term:"汉阴",pinyin:["hàn","yīn"],meaning:"汉水的南边。"},{term:"为圃畦",pinyin:["pǔ","qí"],meaning:"圃：菜园；畦：菜畦。做菜园的畦。"},{term:"凿隧而入井",pinyin:["záo","suì","ér","rù","jǐng"],meaning:"凿一条隧道通到井里。"},{term:"抱瓮而出灌",pinyin:["wèng"],meaning:"瓮：陶罐。抱着陶罐出来浇灌。"},{term:"凿木为机",pinyin:["záo","mù","wéi","jī"],meaning:"凿木做成机械（桔槔）。"},{term:"挈水若抽",pinyin:["qiè"],meaning:"挈：提起。提水就像抽水一样。"},{term:"数如泆汤",pinyin:["yì","tāng"],meaning:"泆：溢出。迅速得像沸汤溢出一样。"},{term:"其名为槔",pinyin:["gāo"],meaning:"槔：桔槔（杠杆提水工具）。"},{term:"博学以拟圣",pinyin:["bó","xué","yǐ","nǐ","shèng"],meaning:"博学来比拟圣人——学了很多，但只是在模仿圣人。"},{term:"於于以盖众",pinyin:["yú","yú"],meaning:"於于：自鸣得意。自鸣得意地压过众人。"},{term:"全德之人",pinyin:["quán","dé","zhī","rén"],meaning:"德性完整的人。"},{term:"浑沌氏之术",pinyin:["hún","dùn","shì"],meaning:"浑沌氏（上古帝王）的方术。"}]}),i[38]||(i[38]=n("h3",{id:"核心句引读-8",tabindex:"-1"},[e("核心句引读 "),n("a",{class:"header-anchor",href:"#核心句引读-8","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(_,{title:"有机械者必有机事，有机事者必有机心",subtitle:"机心一旦进入，纯白就被侵蚀——纯白不备则神生不定，神生不定者，道之所不载也。",lines:[{text:"有机械者必有机事，有机事者必有机心。机心存于胸中则纯白不备。纯白不备则神生不定，神生不定者，道之所不载也。吾非不知，羞而不为也。",tone:"机心",guide:"子贡南游于楚，见一丈人抱瓮而出灌，搰然用力甚多而见功寡。子贡说：有械于此，一日浸百畦——丈人忿然作色而笑：吾闻之吾师，有机械者必有机事，有机事者必有机心——机心存于胸中则纯白不备——纯白不备则神生不定——神生不定者，道之所不载也——吾非不知，羞而不为也。这个逻辑链，是《天地》最著名的机心论：机械（工具）→机事（取巧的事）→机心（机巧算计的心）→纯白不备（本真破损）→神生不定（精神动荡）→道之所不载（与道隔绝）。丈人不是无知，而是有知而不为——知道桔槔，但羞于使用——因为使用桔槔，会带来机心——机心，会破坏纯白。"},{text:"非其志不之，非其心不为。虽以天下誉之，得其所谓，謷然不顾；以天下非之，失其所谓，傥然不受。天下之非誉无益损焉，是谓全德之人哉！",tone:"全德",guide:"子贡被丈人震撼，行三十里而后愈。他反思：始吾以为天下一人耳，不知复有夫人也——执道者德全，德全者形全，形全者神全。若夫人者，非其志不之，非其心不为——虽以天下誉之，謷然不顾；以天下非之，傥然不受——天下之非誉无益损焉，是谓全德之人哉！全德之人——天下称赞他，他不在意；天下非议他，他不接受——不是因为麻木，而是因为：他的根基，不在天下人的评价中——他的根基，在道与德中。"},{text:"彼假修浑沌氏之术者也。识其一，不识其二；治其内而不治其外。夫明白入素，无为复朴，体性抱神，以游世俗之间者，汝将固惊邪？",tone:"中间路",guide:"反于鲁，以告孔子。孔子曰：彼假修浑沌氏之术者也——识其一，不识其二——治其内而不治其外——丈人，拒绝桔槔，守住了纯白——但他，只治内，不治外——他，不是完整的圣人。真正的圣人，是：明白入素，无为复朴，体性抱神，以游世俗之间者——这，就是中间路：不是拒绝世俗（丈人的路），不是沉溺世俗（机心的路）——而是在世俗中游走，同时保持明白·入素·无为·复朴·体性·抱神。连孔子都承认：且浑沌氏之术，予与汝何足以识之哉！"}]}),i[39]||(i[39]=n("h2",{id:"十、谆芒论三境·圣治·德人·神人",tabindex:"-1"},[e("十、谆芒论三境·圣治·德人·神人 "),n("a",{class:"header-anchor",href:"#十、谆芒论三境·圣治·德人·神人","aria-label":'Permalink to "十、谆芒论三境·圣治·德人·神人"'},"​")],-1)),i[40]||(i[40]=n("h3",{id:"原文-9",tabindex:"-1"},[e("原文 "),n("a",{class:"header-anchor",href:"#原文-9","aria-label":'Permalink to "原文"'},"​")],-1)),a(s,{sections:P,glossary:T,"default-mode":"classic","aria-label":"天地·谆芒论三境 原文"}),i[41]||(i[41]=n("h3",{id:"生僻字词-9",tabindex:"-1"},[e("生僻字词 "),n("a",{class:"header-anchor",href:"#生僻字词-9","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(t,{items:[{term:"谆芒",pinyin:["zhūn","máng"],meaning:"庄子虚构的人物，得道者。"},{term:"大壑",pinyin:["dà","hè"],meaning:"大海（极深的沟壑）。"},{term:"苑风",pinyin:["yuàn","fēng"],meaning:"庄子虚构的人物。"},{term:"横目之民",pinyin:["héng","mù"],meaning:"横目：眼睛横着长的人（人）。指百姓。"},{term:"手挠顾指",pinyin:["ráo","gù","zhǐ"],meaning:"挠：挥动；顾：回头。挥动手，回过头指点（从容指挥）。"}]}),i[42]||(i[42]=n("h3",{id:"核心句引读-9",tabindex:"-1"},[e("核心句引读 "),n("a",{class:"header-anchor",href:"#核心句引读-9","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(_,{title:"圣治·德人·神人——三境",subtitle:"圣治：官施不失其宜；德人：居无思行无虑；神人：与天地乐而万事销亡。",lines:[{text:"圣治乎？官施而不失其宜，拔举而不失其能，毕见其情事而行其所为，行言自为而天下化。",tone:"圣治",guide:"谆芒将东之大壑（大海），适遇苑风于东海之滨。大壑之为物也，注焉而不满，酌焉而不竭——往里注入而不满，从里取出而不竭——这是大海的象征，也是道的象征。苑风问三境：愿闻圣治——谆芒曰：圣治乎？官施而不失其宜（设官施政不失其适宜），拔举而不失其能（提拔举荐不失其才能），毕见其情事而行其所为（完全看清事物的实情，然后做该做的事）——行言自为而天下化（行动与言论自然而为，天下自然被感化）。圣治，不是强制安排，而是让事物自然归位。"},{text:"德人者，居无思，行无虑，不藏是非美恶。四海之内共利之之谓悦，共给之之谓安。",tone:"德人",guide:"愿闻德人——德人者，居无思，行无虑（居处没有思虑，行动没有忧虑），不藏是非美恶（内心不藏是非美恶）——四海之内共利之之谓悦（四海之内共同得利，叫做悦），共给之之谓安（共同给养，叫做安）——财用有余而不知其所自来（财用有余却不知道从哪里来），饮食取足而不知其所从（饮食充足却不知道从何处来）——此谓德人之容。德人——本然自足，不计算，不执着——连财用从哪里来都不知道——不是无知，而是：不需要知道。"},{text:"上神乘光，与形灭亡，是谓照旷。致命尽情，天地乐而万事销亡，万物复情，此之谓混溟。",tone:"神人",guide:"愿闻神人——上神乘光（最高的神人乘着光明），与形灭亡（与形体一同消亡）——是谓照旷（这叫做照旷——照彻空旷）。致命尽情（穷尽天命与性情），天地乐而万事销亡（天地同乐而万事消融）——万物复情（万物复归本情）——此之谓混溟（这叫做混溟——混沌溟漠）。神人——与形灭亡，不是肉体的消灭，而是：不再执着于形体——乘光而行，与天地同乐——这，是《逍遥游》「神人」境界在《天地》中的回响。"}]}),i[43]||(i[43]=n("h2",{id:"十一、门无鬼·赤张满稽·至德之世",tabindex:"-1"},[e("十一、门无鬼·赤张满稽·至德之世 "),n("a",{class:"header-anchor",href:"#十一、门无鬼·赤张满稽·至德之世","aria-label":'Permalink to "十一、门无鬼·赤张满稽·至德之世"'},"​")],-1)),i[44]||(i[44]=n("h3",{id:"原文-10",tabindex:"-1"},[e("原文 "),n("a",{class:"header-anchor",href:"#原文-10","aria-label":'Permalink to "原文"'},"​")],-1)),a(s,{sections:G,glossary:v,"default-mode":"classic","aria-label":"天地·至德之世 原文"}),i[45]||(i[45]=n("h3",{id:"生僻字词-10",tabindex:"-1"},[e("生僻字词 "),n("a",{class:"header-anchor",href:"#生僻字词-10","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(t,{items:[{term:"门无鬼",pinyin:["mén","wú","guǐ"],meaning:"庄子虚构的人物。"},{term:"赤张满稽",pinyin:["chì","zhāng","mǎn","jī"],meaning:"庄子虚构的人物。"},{term:"秃而施髢",pinyin:["shī","dí"],meaning:"髢：假发。秃了头才戴假发（遮掩，不是解决）。"},{term:"病而求医",pinyin:["bìng","ér","qiú","yī"],meaning:"生了病才去求医（亡羊补牢，为时已晚）。"},{term:"其色燋然",pinyin:["jiāo","rán"],meaning:"燋然：焦虑的样子。孝子焦虑的脸色，说明父亲已经病了——这本身，就是失败。"},{term:"上如标枝",pinyin:["shàng","rú","biāo","zhī"],meaning:"君主，像树梢的枝条——高高在上，但轻盈，不压迫。"},{term:"民如野鹿",pinyin:["mín","rú","yě","lù"],meaning:"百姓，像野鹿——自由自在，不被驯化。"}]}),i[46]||(i[46]=n("h3",{id:"核心句引读-10",tabindex:"-1"},[e("核心句引读 "),n("a",{class:"header-anchor",href:"#核心句引读-10","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(_,{title:"至德之世，不尚贤，不使能，上如标枝，民如野鹿",subtitle:"端正而不知以为义——一旦有了名字，成了概念，本然就消失了。",lines:[{text:"有虞氏之药疡也，秃而施髢，病而求医。孝子操药以修慈父，其色燋然，圣人羞之。",tone:"药疡",guide:"门无鬼与赤张满稽观于武王之师。赤张满稽：不及有虞氏乎！门无鬼问：天下均治而有虞氏治之邪？其乱而后治之与？——赤张满稽答：天下均治之为愿，而何计以有虞氏为！有虞氏之药疡也——有虞氏（舜）治理天下，就像给疮疡上药——天下已经坏了，才来治。秃而施髢（秃了才戴假发），病而求医——治标，不治本。孝子操药以修慈父，其色燋然——孝子是好意的，但孝子焦虑的脸色，说明父亲已经病了——这本身，就是失败——圣人，羞于看到这种场景——因为真正的圣人，不会让天下病到需要治的程度。"},{text:"端正而不知以为义，相爱而不知以为仁，实而不知以为忠，当而不知以为信，蠢动而相使不以为赐。是故行而无迹，事而无传。",tone:"不知以为",guide:"至德之世，不尚贤，不使能，上如标枝（君主像树梢的枝条——高高在上，但轻盈，不压迫——这，是「在宥天下」的最形象的比喻），民如野鹿（百姓像野鹿——自由自在，不被驯化）。四个「不知以为」——端正·相爱·实·当——这些，都是好的——都是义·仁·忠·信的实质——但「不知以为义·仁·忠·信」——不知道这些有名字——因为：这些，是本然的——不是学来的，不是被教导的——是自然流淌的——所以，不需要名字。一旦有了名字——义·仁·忠·信，成了概念——成了可以追求的目标——成了可以用来评价别人的标准——本然，就消失了。是故行而无迹，事而无传——没有历史，没有记录，没有传说——因为：没有什么值得特别记录——一切，都是本然的——这，才是真正的「无为」。"}]}),i[47]||(i[47]=n("h2",{id:"十二、大惑论·天下皆惑",tabindex:"-1"},[e("十二、大惑论·天下皆惑 "),n("a",{class:"header-anchor",href:"#十二、大惑论·天下皆惑","aria-label":'Permalink to "十二、大惑论·天下皆惑"'},"​")],-1)),i[48]||(i[48]=n("h3",{id:"原文-11",tabindex:"-1"},[e("原文 "),n("a",{class:"header-anchor",href:"#原文-11","aria-label":'Permalink to "原文"'},"​")],-1)),a(s,{sections:D,glossary:C,"default-mode":"classic","aria-label":"天地·大惑论 原文"}),i[49]||(i[49]=n("h3",{id:"生僻字词-11",tabindex:"-1"},[e("生僻字词 "),n("a",{class:"header-anchor",href:"#生僻字词-11","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(t,{items:[{term:"不谀其亲",pinyin:["yú"],meaning:"谀：谄媚、奉承。不奉承自己的父母。"},{term:"不谄其君",pinyin:["chǎn"],meaning:"谄：谄媚。不谄媚自己的君主。"},{term:"不肖子",pinyin:["bù","xiào","zǐ"],meaning:"不肖：不像样、不孝顺。不孝顺的儿子。"},{term:"道谀之人",pinyin:["dào","yú"],meaning:"道谀：表面引导，实则奉承。"},{term:"勃然作色",pinyin:["bó","rán"],meaning:"勃然：激动地。突然变脸色（愤怒）。"},{term:"怫然作色",pinyin:["fú","rán"],meaning:"怫然：不高兴的样子。不高兴地变脸色。"},{term:"以媚一世",pinyin:["mèi"],meaning:"媚：讨好、迎合。来讨好一世之人。"},{term:"嗑然而笑",pinyin:["kē","rán"],meaning:"嗑然：开心大笑的样子。"}]}),i[50]||(i[50]=n("h3",{id:"核心句引读-11",tabindex:"-1"},[e("核心句引读 "),n("a",{class:"header-anchor",href:"#核心句引读-11","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(_,{title:"知其愚者，非大愚也；知其惑者，非大惑也",subtitle:"大惑者，终身不解；大愚者，终身不灵。",lines:[{text:"知其愚者，非大愚也；知其惑者，非大惑也。大惑者，终身不解；大愚者，终身不灵。",tone:"大惑",guide:"大惑论开篇：孝子不谀其亲，忠臣不谄其君——臣、子之盛也。但亲之所言而然，所行而善——则世俗谓之不肖子——君之所言而然，所行而善——则世俗谓之不肖臣。庄子追问：世俗之所谓然而然之，所谓善而善之——则不谓之道谀之人也！——世俗说对的就跟着说对，世俗说好的就跟着说好——却不认为这是「道谀」（奉承）——然则俗故严于亲而尊于君邪？知其愚者，非大愚也；知其惑者，非大惑也——大惑者，终身不解；大愚者，终身不灵——知道自己愚的人，不是大愚——不知道自己愚的，才是大愚——这，是「天下皆惑」的诊断：惑而不自知，才是最大的惑。"},{text:"三人行而一人惑，所适者，犹可致也，惑者少也；二人惑则劳而不至，惑者胜也。而今也以天下惑，予虽有祈向，不可得也。不亦悲乎！",tone:"天下惑",guide:"三人行而一人惑——目的地还可以到达——因为迷惑的人少；二人惑则劳而不至——因为迷惑的人占多数。而今也以天下惑——现在，天下的人都迷惑——予虽有祈向，不可得也——我虽然有祈求向往的方向，却无法到达——不亦悲乎！大声不入于里耳（高深的言论进不了俗耳），折杨、皇荂，则嗑然而笑（通俗的歌曲，反而开心大笑）——是故高言不止于众人之心；至言不出，俗言胜也。以二缶钟惑，而所适不得矣——以天下惑，予虽有祈向，其庸可得邪！知其不可得也而强之，又一惑也！故莫若释之而不推。不推，谁其比忧！——这，是《天地》最深的悲哀：道在那里，但天下皆惑，无人能识——与其强行，不如放下。"}]}),i[51]||(i[51]=n("h2",{id:"十三、失性五者·生之害",tabindex:"-1"},[e("十三、失性五者·生之害 "),n("a",{class:"header-anchor",href:"#十三、失性五者·生之害","aria-label":'Permalink to "十三、失性五者·生之害"'},"​")],-1)),i[52]||(i[52]=n("h3",{id:"原文-12",tabindex:"-1"},[e("原文 "),n("a",{class:"header-anchor",href:"#原文-12","aria-label":'Permalink to "原文"'},"​")],-1)),a(s,{sections:N,glossary:V,"default-mode":"classic","aria-label":"天地·失性五者 原文"}),i[53]||(i[53]=n("h3",{id:"生僻字词-12",tabindex:"-1"},[e("生僻字词 "),n("a",{class:"header-anchor",href:"#生僻字词-12","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(t,{items:[{term:"百年之木",pinyin:["bǎi","nián","zhī","mù"],meaning:"活了百年的树木。"},{term:"破为牺尊",pinyin:["xī","zūn"],meaning:"破：剖开。剖开做成牺尊（祭祀酒器）。"},{term:"青黄而文之",pinyin:["qīng","huáng","ér","wén","zhī"],meaning:"涂上青黄的花纹（装饰）。"},{term:"其断在沟中",pinyin:["qí","duàn","zài","gōu","zhōng"],meaning:"它的断木，被扔在沟里。"}]}),i[54]||(i[54]=n("h3",{id:"核心句引读-12",tabindex:"-1"},[e("核心句引读 "),n("a",{class:"header-anchor",href:"#核心句引读-12","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(_,{title:"百年之木——你，还是那棵树吗？",subtitle:"牺牲与沟中断木，美恶有别，其于失性一也。",lines:[{text:"百年之木，破为牺尊，青黄而文之，其断在沟中。比牺尊于沟中之断，则美恶有间矣，其于失性一也。跖与曾、史，行义有间矣，然其失性均也。",tone:"失性",guide:"失性五者开篇——百年之木，破为牺尊（精美的祭祀酒器），青黄而文之——其断在沟中（断木被扔在沟里）。比牺尊于沟中之断——则美恶有间矣（精美与粗陋有差别）——其于失性一也（但在失去本性上是一样的）。跖与曾、史，行义有间矣（盗跖与曾参、史鱼，行为善恶有差别）——然其失性均也（但失去本性是一样的）。这，是《天地》对「失性」最深的观察：无论你是被做成精美的牺尊（被社会珍视），还是被扔在沟里（被社会遗弃）——只要你的本性被改造了，你就失去了那棵百年大树的本然——你，还是那棵树吗？"},{text:"且夫失性有五：一曰五色乱目，使目不明；二曰五声乱耳，使耳不聪；三曰五臭熏鼻，困惾中颡；四曰五味浊口，使口厉爽；五曰趣舍滑心，使性飞扬。此五者，皆生之害也。",tone:"五者",guide:"失性有五：一曰五色乱目（五色扰乱眼睛，使眼睛不明）；二曰五声乱耳（五声扰乱耳朵，使耳朵不聪）；三曰五臭熏鼻（五种气味熏鼻子，使气闷而伤额头）；四曰五味浊口（五味扰乱嘴巴，使嘴巴受伤）；五曰趣舍滑心（取舍扰乱内心，使本性飞扬——失去安定）。此五者，皆生之害也——这五种，都是生命的伤害。五色·五声·五臭·五味·趣舍——五种感官刺激与取舍执着——都在损伤生命——这，与《骈拇》的「五色乱目」批判完全呼应。"},{text:"且夫趣舍声色以柴其内，皮弁鹬冠搢笏绅修以约其外。内支盈于柴栅，外重纆缴睆睆然在纆缴之中，而自以为得，则是罪人交臂历指而虎豹在于囊槛，亦可以为得矣！",tone:"笼中",guide:"杨、墨乃始离跂自以为得，非吾所谓得也——夫得者困，可以为得乎？则鸠鸮之在于笼也，亦可以为得矣（斑鸠被关在笼子里，也可以算是得了吗？）。趣舍声色以柴其内（欲望像柴草一样塞满内心），皮弁鹬冠搢笏绅修以约其外（礼法像绳索一样束缚外表）——内支盈于柴栅，外重纆缴——在枷锁之中，而自以为得——则是罪人交臂历指而虎豹在于囊槛，亦可以为得矣（罪人被反绑双手、虎豹被关在笼子里，也可以算是得了吗？）。这，是《天地》对「自以为得」最深的讽刺：那些自以为得道的人——其实是被欲望与礼法双重捆绑的囚徒。"}]}),i[55]||(i[55]=E(`<h2 id="脉络逻辑链" tabindex="-1">脉络逻辑链 <a class="header-anchor" href="#脉络逻辑链" aria-label="Permalink to &quot;脉络逻辑链&quot;">​</a></h2><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第1段·起（德兼于道·道兼于天）</span></span>
<span class="line"><span>    技兼于事·事兼于义·义兼于德·德兼于道·道兼于天</span></span>
<span class="line"><span>    → 全篇骨架：六层统摄的层级</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>第2段·承（夫子论道·刳心十者·王德之人）</span></span>
<span class="line"><span>    君子不可以不刳心焉·十者·王德之人视冥听无</span></span>
<span class="line"><span>    → 个人修养：挖空成见以容道</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>第3段·转（黄帝遗玄珠·象罔得之）</span></span>
<span class="line"><span>    知离朱喫诟索之不得·象罔得之</span></span>
<span class="line"><span>    → 无心无执，才能得道</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>第4段·批（尧问许由·啮缺不配天）</span></span>
<span class="line"><span>    聪明睿知其性过人·而以人受天·治乱之率也</span></span>
<span class="line"><span>    → 批判以人受天的聪明治者</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>第5段·批（尧观华封·三辞三驳）</span></span>
<span class="line"><span>    寿富多男子非所以养德·始也以为圣人今然君子也</span></span>
<span class="line"><span>    → 批判养德之算：圣人鹑居彀食不计算</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>第6段·批（伯成子高·辞诸侯而耕）</span></span>
<span class="line"><span>    不赏而民劝不罚而民畏·今子赏罚而民且不仁</span></span>
<span class="line"><span>    → 批判赏罚：德衰刑立乱始</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>第7段·立（泰初有无）</span></span>
<span class="line"><span>    泰初有无·一之所起·物得以生谓之德·性修反德</span></span>
<span class="line"><span>    → 宇宙生成论：从无到有的展开与回归</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>第8段·承（夫子问老聃·将闾葂见季彻）</span></span>
<span class="line"><span>    胥易技系劳形怵心·忘乎物忘乎天其名为忘己</span></span>
<span class="line"><span>    → 忘己入天：批判辩者，立忘己</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>第9段·转（子贡遇丈人·机心·全德之人）</span></span>
<span class="line"><span>    有机械者必有机事·机心存胸中纯白不备·全德之人</span></span>
<span class="line"><span>    → 机心论：技术时代的最深警告</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>第10段·立（谆芒论三境·圣治德人神人）</span></span>
<span class="line"><span>    圣治官施不失其宜·德人居无思行无虑·神人乘光照旷</span></span>
<span class="line"><span>    → 三境：从治理到存在</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>第11段·证（门无鬼·至德之世）</span></span>
<span class="line"><span>    有虞氏之药疡也·上如标枝民如野鹿·行而无迹事而无传</span></span>
<span class="line"><span>    → 至德之世：端正不知以为义</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>第12段·深（大惑论·天下皆惑）</span></span>
<span class="line"><span>    大惑者终身不解·至言不出俗言胜也·莫若释之而不推</span></span>
<span class="line"><span>    → 天下皆惑，强之又一惑，不如放下</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>第13段·合（失性五者·生之害）</span></span>
<span class="line"><span>    百年之木破为牺尊其断在沟中·失性一也·五者皆生之害</span></span>
<span class="line"><span>    → 全篇收束：你，还是那棵树吗</span></span></code></pre></div><p><strong>全篇主线</strong>：从六层骨架起，经刳心修养、象罔得珠，批判以人受天、养德之算、赏罚之乱，立泰初有无的宇宙论，再经忘己、机心、三境、至德之世，至大惑论与失性五者收束——层级为本，本性为归，失性即失树。</p><h2 id="三问解读" tabindex="-1">三问解读 <a class="header-anchor" href="#三问解读" aria-label="Permalink to &quot;三问解读&quot;">​</a></h2><h3 id="第一问·《天地》的层级与「机心」——它究竟在说什么" tabindex="-1">第一问·《天地》的层级与「机心」——它究竟在说什么？ <a class="header-anchor" href="#第一问·《天地》的层级与「机心」——它究竟在说什么" aria-label="Permalink to &quot;第一问·《天地》的层级与「机心」——它究竟在说什么？&quot;">​</a></h3><p>《天地》开篇建立了层级：技·事·义·德·道·天——每一层都统摄于更高层。这个层级，给了我们一个检验标准：</p><p>你在使用技术时——这个技术，服务于什么「事」？这个「事」，符合什么「义」？这个「义」，根植于什么「德」？这个「德」，通向什么「道」？</p><p>如果你只知道「技」，而不知道上面的层级——你，就是在用桔槔灌园——高效，但机心已存，纯白已破。机心论（有机械→有机事→有机心→纯白不备→神生不定→道之所不载），是《天地》对「技」的最高警告：不是技本身有害——而是：当你只停留在「技」的层面，忘记它之上的「事·义·德·道·天」——你就被技所役，失去了本性。</p><h3 id="第二问·「泰初有无」的宇宙生成论——它说的究竟是什么" tabindex="-1">第二问·「泰初有无」的宇宙生成论——它说的究竟是什么？ <a class="header-anchor" href="#第二问·「泰初有无」的宇宙生成论——它说的究竟是什么" aria-label="Permalink to &quot;第二问·「泰初有无」的宇宙生成论——它说的究竟是什么？&quot;">​</a></h3><p>第7段的宇宙生成论，是《天地》最难理解的部分——也是最重要的部分。生成序列：泰初（有无·无有无名）→一（有一而未形）→德（万物得道而生）→命（自然的必然性）→形（万物的形体与条理）→性（每个存在的独特方式）。</p><p>这个序列，说的究竟是什么？不是宇宙的物理起源——庄子不是在写宇宙学——而是：每一个存在，从道到性的展开。泰初有无——你，在出生之前，是无的；一——你，有了一个「一」，但还没有形体；德——你，从道那里得到了生长的能力；命——你，有了自然的必然性；形——你，有了形体与条理；性——你，有了独特的存在方式。这个序列，是每一个存在的「来路」——而回归序列（性修反德，德至同于初），是每一个存在的「归路」：「性修反德」——修养本性，不是变得更好——而是：返回——返回到德，返回到道，返回到泰初。这，是《天地》对「修道」最根本的定义：修道，不是积累，不是进步——而是返回。返回到你从道那里出发的地方。</p><h3 id="第三问·「机心」与「全德」——两者之间-有没有中间路" tabindex="-1">第三问·「机心」与「全德」——两者之间，有没有中间路？ <a class="header-anchor" href="#第三问·「机心」与「全德」——两者之间-有没有中间路" aria-label="Permalink to &quot;第三问·「机心」与「全德」——两者之间，有没有中间路？&quot;">​</a></h3><p>《天地》给出了两个极端：一端：机心（有机械→有机事→有机心→纯白不备→道之所不载——这，是失性的路）；另一端：全德之人（非其志不之，非其心不为——天下誉，謷然不顾；天下非，傥然不受——这，是全德的路）。</p><p>但孔子说：丈人，「治其内而不治其外」——丈人，拒绝桔槔，守住了纯白——但他，只治内，不治外——他，不是完整的圣人。真正的圣人，是：「明白入素，无为复朴，体性抱神，以游世俗之间者。」这，就是中间路：不是拒绝世俗（丈人的路），不是沉溺世俗（机心的路）——而是在世俗中游走，同时保持明白·入素·无为·复朴·体性·抱神。这条路，极难——连孔子，都承认自己无法完全认识这条路——但《天地》给出了方向：不是拒绝技（丈人），不是沉溺技（机心），而是——用技，但不被技所役（物而不物）；处世，但不被世所困（游世俗之间）；有知，但不被知所执（忘己入天）。</p><h2 id="现代思考与启发" tabindex="-1">现代思考与启发 <a class="header-anchor" href="#现代思考与启发" aria-label="Permalink to &quot;现代思考与启发&quot;">​</a></h2><p><strong>关于「技兼于事」：技术时代的位置感</strong></p><blockquote><p>我们生活在一个技术空前强大的时代——人工智能、算法推荐、自动化——每一项技术，都承诺「用力甚寡而见功多」。但庄子的问题是：这个技术，服务于什么「事」？这个「事」，符合什么「义」？这个「义」，根植于什么「德」？这个「德」，通向什么「道」？如果你只知道「技」，而不知道上面的层级——你，就是在用桔槔灌园——高效，但机心已存，纯白已破。不是拒绝技术——而是：给技术一个位置——它，是「技」，是「末」——它之上，还有事·义·德·道·天——不要把技，当成全部。</p></blockquote><p><strong>关于「象罔得珠」：为什么越努力越找不到？</strong></p><blockquote><p>黄帝派出了知（智识）、离朱（感知）、喫诟（辩论）——人类最引以为傲的三种能力——全部失败。最后，象罔（若有若无·无心无执）找到了。今天，我们寻找「道」的方式，比黄帝更「强」：更多的知识（知）、更敏锐的观察（离朱）、更强的表达（喫诟）——但越努力，越找不到。为什么？因为「找」本身，就是一种执着——而执着，与道相悖。象罔的启示：有时候，放下寻找，道反而出现——不是放弃追求，而是：不再用「强求」的方式追求——无心，才能得；有心，反而失。</p></blockquote><p><strong>关于「机心」：效率与纯白的平衡</strong></p><blockquote><p>「机心存于胸中则纯白不备」——这句话，在今天有了全新的紧迫性。今天的「机心」，不只是桔槔——是算法推送（计算你的偏好），是绩效指标（计算你的产出），是社交比较（计算你的位置）。每一样，都在培养「机心」——都在侵蚀「纯白」。但庄子不是说不要用机械——丈人自己也说「吾非不知」——而是：知道，但保持警觉——用技术，但不让技术塑造你的心——保持那份「纯白」——那份不计算、不比较、不取巧的本然。</p></blockquote><p><strong>关于「至德之世」：行而无迹，事而无传</strong></p><blockquote><p>至德之世——不尚贤，不使能，上如标枝，民如野鹿——端正而不知以为义，相爱而不知以为仁——行而无迹，事而无传。今天的社会，恰恰相反：尚贤（推崇成功者），使能（竞争能力），上如巨石（压迫），民如囚徒（焦虑）——什么都要求「留下痕迹」（打卡·记录·展示），什么都要「流传」（发布·点赞·转发）。庄子的至德之世，是一个反过来的世界：不是不做，而是：做了，不留痕迹；不是不爱，而是：爱了，不知道那叫仁。这，是对「表演型生活」最深的解药——你的价值，不需要被看见；你的善良，不需要被命名。</p></blockquote><p><strong>关于「失性五者」：你，还是那棵树吗？</strong></p><blockquote><p>百年之木——它，可以成为牺尊，精美，受人尊重；它，可以成为断木，粗陋，扔在沟里——但无论哪种，它都不再是那棵百年大树了。今天的「失性五者」，比庄子时代更密集：五色（屏幕的色彩）、五声（推送的声音）、五臭（消费的气味）、五味（过量的饮食）、趣舍（无尽的取舍）——每一种，都在改造我们的本性。庄子的问题是：你，还是那棵树吗？——不是说你不能成长，不能变化——而是：你的变化，是本然的生长，还是被外力改造成「牺尊」或「断木」？前者，是生长；后者，是失性。</p></blockquote><h2 id="关键词索引" tabindex="-1">关键词索引 <a class="header-anchor" href="#关键词索引" aria-label="Permalink to &quot;关键词索引&quot;">​</a></h2><table tabindex="0"><thead><tr><th>关键词</th><th>出处</th><th>核心含义</th></tr></thead><tbody><tr><td>畜天下</td><td>第1段</td><td>养育天下，而非治理天下。无欲而天下足，无为而万物化，渊静而百姓定</td></tr><tr><td>技兼于事……道兼于天</td><td>第1段</td><td>全篇哲学骨架。技→事→义→德→道→天，每一层统摄于更高层</td></tr><tr><td>刳心</td><td>第2段</td><td>挖空心中的成见与执着，使心虚空以容道。与「心斋」呼应</td></tr><tr><td>无为为之之谓天</td><td>第2段</td><td>以无为的方式去做，叫做天。做，但做的方式是无为的</td></tr><tr><td>不同同之之谓大</td><td>第2段</td><td>不强求相同而使之同，包容差异而达到大同，才是真正的大</td></tr><tr><td>不以物挫志之谓完</td><td>第2段</td><td>完整，是内在的志向不被外物所挫伤</td></tr><tr><td>王德之人</td><td>第2段</td><td>拥有最高德性的人。素逝而耻通于事，立之本原而知通于神</td></tr><tr><td>冥冥之中，独见晓焉</td><td>第2段</td><td>道的见与闻：在感官无法到达的地方，道独自见到、听到</td></tr><tr><td>玄珠</td><td>第3段</td><td>黑色的珠，象征道。黄帝遗失了玄珠，就是遗失了道</td></tr><tr><td>象罔</td><td>第3段</td><td>若有若无，无心无执。象罔得之——越主动地找，越找不到</td></tr><tr><td>以人受天</td><td>第4段</td><td>用人的框架来理解天道。啮缺的根本错误</td></tr><tr><td>治，乱之率也</td><td>第4段</td><td>治理，是混乱的率领者——治理，导致混乱</td></tr><tr><td>鹑居而彀食</td><td>第5段</td><td>像鹌鹑一样居处，像幼鸟一样进食——不执着于居所，不积储食物</td></tr><tr><td>美则美矣，而未大也</td><td>第5段</td><td>华封人对尧的判断：君子的逻辑（养德），不是圣人的逻辑（不计算）</td></tr><tr><td>赏罚而民且不仁</td><td>第6段</td><td>赏罚不是解决问题的方法，反而制造了问题</td></tr><tr><td>泰初有无</td><td>第7段</td><td>宇宙最初的状态——有，但是无——无形无名</td></tr><tr><td>物得以生谓之德</td><td>第7段</td><td>德是道在万物中的体现，道给予万物的生长能力</td></tr><tr><td>性修反德</td><td>第7段</td><td>修道不是积累，而是返回——返回到你从道那里出发的地方</td></tr><tr><td>忘己之人，是之谓入于天</td><td>第8段</td><td>忘掉外物，忘掉天——放下执着，与天地合一</td></tr><tr><td>机心</td><td>第9段</td><td>有机械→有机事→有机心→纯白不备→神生不定→道之所不载</td></tr><tr><td>全德之人</td><td>第9段</td><td>非其志不之，非其心不为。天下誉之，謷然不顾；天下非之，傥然不受</td></tr><tr><td>浑沌氏之术</td><td>第9段</td><td>识其一，不识其二；治其内而不治其外。丈人只治内，不治外</td></tr><tr><td>明白入素，无为复朴</td><td>第9段</td><td>中间路：在世俗中游走，同时保持明白·入素·无为·复朴·体性·抱神</td></tr><tr><td>圣治·德人·神人</td><td>第10段</td><td>三境：圣治（官施不失其宜）·德人（居无思行无虑）·神人（与形灭亡）</td></tr><tr><td>注焉而不满，酌焉而不竭</td><td>第10段</td><td>大海的象征，也是道的象征——大壑为物</td></tr><tr><td>上如标枝，民如野鹿</td><td>第11段</td><td>至德之世：君主轻盈不压迫，百姓自由不被驯化</td></tr><tr><td>端正而不知以为义</td><td>第11段</td><td>至德之世的特征：行为本然，但不知道这些有名字</td></tr><tr><td>行而无迹，事而无传</td><td>第11段</td><td>至德之世的最终状态：没有什么值得特别记录</td></tr><tr><td>大惑者，终身不解</td><td>第12段</td><td>惑而不自知，才是最大的惑。以天下惑，不可得也</td></tr><tr><td>至言不出，俗言胜也</td><td>第12段</td><td>高深的言论无法停留，俗言就占了上风</td></tr><tr><td>失性五者</td><td>第13段</td><td>五色乱目·五声乱耳·五臭熏鼻·五味浊口·趣舍滑心——皆生之害</td></tr><tr><td>鸠鸮之在于笼也，亦可以为得矣</td><td>第13段</td><td>被关在笼子里，也可以算是得了吗？自以为得的讽刺</td></tr></tbody></table><h3 id="一句话" tabindex="-1">一句话 <a class="header-anchor" href="#一句话" aria-label="Permalink to &quot;一句话&quot;">​</a></h3><p>如果《天地》全篇，只能用一句话来总结——</p><blockquote><p><strong>「古之畜天下者，无欲而天下足，无为而万物化，渊静而百姓定。」</strong></p></blockquote><p>如果只能用一个意象来记住《天地》——</p><blockquote><p><strong>百年之木——它，可以成为牺尊，精美，受人尊重；它，可以成为断木，粗陋，扔在沟里——但无论哪种，它都不再是那棵百年大树了。你，还是那棵树吗？</strong></p></blockquote><h2 id="参考来源" tabindex="-1">参考来源 <a class="header-anchor" href="#参考来源" aria-label="Permalink to &quot;参考来源&quot;">​</a></h2><ul><li>《庄子·外篇·天地》</li></ul>`,34))])}}});export{O as __pageData,U as default};
